window.__CHRONICLE_CHUNK["cn-03"] = [
  {"id":"cn--b221--p01","track":"cn","year":-221,"yearApprox":false,"dim":"politics","weight":5,"title":"秦灭六国成一统","summary":"王贲入临淄虏齐王建，十年尽并六国，天下归一。","detail":{"background":"自商鞅变法后秦历六世益强，至秦王政已先后灭韩、赵、魏、楚、燕，唯齐未服。","process":"前221年王贲自燕南下袭临淄，齐王建不战而降，迁于共。自前230灭韩起十年间六国尽除，以咸阳为都，天下为一。","impact":"结束春秋战国五百余年分裂割据，确立以官僚郡县统治广土众民的帝国模式，成为后世统一王朝的范本。","figures":["嬴政","王贲","齐王建"],"place":"咸阳（今陕西咸阳市东北）","state":"秦朝","sources":["《史记·秦始皇本纪》","《战国策·秦策》"],"tags":["秦统一","战国终结","帝国"]},"related":[]},
  {"id":"cn--b221--i01","track":"cn","year":-221,"yearApprox":false,"dim":"institution","weight":5,"title":"创皇帝号与三公九卿","summary":"兼用三皇五帝号定皇帝之称，中央置三公九卿分掌。","detail":{"background":"统一后丞相绾、御史大夫劫、廷尉斯等请议尊号，古之帝、皇、天皇皆被认为不足以称成功。","process":"前221年从「古有天皇、地皇、泰皇，泰皇最贵」之议，去「泰」留「皇」、取上古「帝」号，合称「皇帝」，命为「制」、令为「诏」、自称曰「朕」；中央设丞相、太尉、御史大夫为三公，下设九卿分掌政务。","impact":"皇帝专制与三公九卿的官僚架构此后沿袭两千年，构成中国帝制时代中央官制的主干。","figures":["嬴政","王绾","李斯","冯去疾"],"place":"咸阳（今陕西咸阳东北）","state":"秦朝","sources":["《史记·秦始皇本纪》","《汉书·百官公卿表》"],"tags":["帝制","中央官制","皇权"]},"related":["cn--b221--p01"]},
  {"id":"cn--b221--i02","track":"cn","year":-221,"yearApprox":false,"dim":"institution","weight":5,"title":"遍行郡县废封建","summary":"分天下为三十六郡，郡守县令由中央任免不世袭。","detail":{"background":"统一之际王绾请以燕、齐远地立皇子为王，李斯反驳谓周封姓同气异而相攻击如仇雠。","process":"前221年采李斯议，「罢诸侯、立郡县」，分天下为三十六郡（后世增置至四十余），郡置守、尉、监，县万户称令、不满称长，长官皆由朝廷任免、给俸而不世袭。","impact":"以直接流官取代世袭封君，中央政令得直达编户，成为中国两千余年地方行政的基本框架。","figures":["李斯","王绾","嬴政"],"place":"全国（初治关中，后推及旧六国地）","state":"秦朝","sources":["《史记·秦始皇本纪》","《通典·职官》"],"tags":["郡县制","地方行政","中央集权"]},"related":["cn--b221--p01", "cn--b221--i01"]},
  {"id":"cn--b221--e01","track":"cn","year":-221,"yearApprox":false,"dim":"economy","weight":3,"title":"徙天下豪富十二万户","summary":"迁旧六国豪富于咸阳，强干弱枝并充实京师。","detail":{"background":"六国旧贵族与工商豪家在地方宗族势力庞大，为统一政权的潜在威胁。","process":"前221年「徙天下豪富于咸阳十二万户」，与先前迁蜀、迁河套之民相配合；京师户口骤增，关中为全国人口与经济重心。","impact":"开了后世以迁徙豪强充实京畿、抑制地方大族的政策先例，也促成了咸阳的都会化与消费市场。","figures":["嬴政"],"place":"咸阳（今陕西咸阳东北）","state":"秦朝","sources":["《史记·秦始皇本纪》","《汉书·地理志》"],"tags":["移民","豪强","京师"]},"related":["cn--b221--i02"]},
  {"id":"cn--b221--i03","track":"cn","year":-221,"yearApprox":false,"dim":"institution","weight":4,"title":"书同文车同轨统一度量","summary":"以小篆为标准字，定车轨宽度与度衡量制标准器。","detail":{"background":"战国文字异形、度量衡不一，公文转输与赋税计算阻碍极大。","process":"前221年诏「一法度衡石丈尺，车同轨，书同文字」，李斯作《仓颉篇》、赵高《爰历篇》、胡毋敬《博学篇》为标准字书，通行小篆并容隶书；出土有商鞅方升与秦诏版可证。","impact":"文字、度量与道路标准的统一使帝国政令与税收得以跨方言区运行，是维系长期统一的技术前提。","figures":["李斯","赵高","胡毋敬","嬴政"],"place":"咸阳及各郡（诏版出土多地）","state":"秦朝","sources":["《史记·秦始皇本纪》","《汉书·艺文志》","秦诏版铭文"],"tags":["书同文","度量衡","标准化"]},"related":["cn--b221--i02"]},
  {"id":"cn--b219--a01","track":"cn","year":-219,"yearApprox":false,"dim":"art","weight":3,"title":"泰山刻石与小篆典范","summary":"始皇东巡封泰山，李斯刻辞确立小篆书法正统。","detail":{"background":"统一后始皇五次出巡，所至刻石颂德，以宣示新政权受命于天地。","process":"前219年始皇自泰山封禅，南登琅琊，刻琅琊台、泰山诸石；传为李斯所书，字形匀整对称，为小篆成熟期的代表，今存宋拓摹本（泰山刻石残字）。","impact":"秦刻石既是帝王纪功碑的开端，也被后世书家奉为篆书正宗，影响两千年碑刻与书法传统。","figures":["李斯","嬴政"],"place":"泰山、琅琊台（今山东泰安、胶南）","state":"秦朝","sources":["《史记·秦始皇本纪》","泰山刻石拓本"],"tags":["书法","小篆","刻石"]},"related":["cn--b221--i03"]},
  {"id":"cn--b219--x01","track":"cn","year":-219,"yearApprox":false,"dim":"explore","weight":2,"title":"徐福率众入海求仙","summary":"将童男女数千、百工出海，求三神山不死药。","detail":{"background":"战国燕齐方士盛传海中有蓬莱、方丈、瀛洲三神山，仙人和不死药可得。","process":"前219年始皇东游至琅琊，齐人徐福等上书请入海求仙人，得遣童男女数千人，资五谷百工出海；前210年再次出发，终不返，传说止于「平原广泽」。","impact":"这是中国史上最早有明确记载的大规模远洋行动，日本列岛与朝鲜半岛传出徐福登陆的长期记忆。","figures":["徐福","嬴政"],"place":"琅琊（今山东青岛黄岛区沿海）","state":"秦朝","sources":["《史记·秦始皇本纪》","《史记·淮南衡山列传》"],"tags":["海外交通","方士","东渡"]},"related":["cn--b219--a01"]},
  {"id":"cn--b219--m01","track":"cn","year":-219,"yearApprox":false,"dim":"military","weight":3,"title":"五十万众南戍五岭","summary":"尉屠睢将五军逾岭南攻越人，越人夜击杀屠睢。","detail":{"background":"秦取楚地后设长沙、豫章郡，岭南西瓯、骆越犹独立，始皇欲并其地。","process":"前219年命尉屠睢发卒五十万为五军，一塞镡城之岭，一守九疑之塞，一处番禺之西，一守岭，一处三江，因粮不继，又使禄侯渠转漕；三年越人夜袭大破秦军，屠睢死。","impact":"这场持续数年的山越战争造成南方人口锐减，也迫使秦修灵渠以通漕运，客观上打通长江与珠江水系。","figures":["尉屠睢","史禄","嬴政"],"place":"岭南五岭一带（今湘桂粤交界）","state":"秦朝","sources":["《淮南子·人间训》","《史记·平津侯主父列传》"],"tags":["南征","百越","山地战"]},"related":["cn--b214--i01"]},
  {"id":"cn--b215--m01","track":"cn","year":-215,"yearApprox":false,"dim":"military","weight":4,"title":"蒙恬北击匈奴取河南地","summary":"将兵出上郡渡黄河，尽取阳山北假地，置四十四县。","detail":{"background":"战国末匈奴已度黄河牧于高阙、阳山、北假中，秦边郡数被寇掠。","process":"前215年（始皇三十二年）使蒙恬将兵（史无确数，说者以为三十万）自上郡肤施出发，渡黄河，夺高阙、阳山、北假中，置九原郡等四十四县，「斥逐匈奴」十余年。","impact":"河套平原自此长期纳入农耕政权版图，成为中原王朝的北方粮仓与马政基地，也奠定长城防线走向。","figures":["蒙恬","嬴政"],"place":"河南地（今内蒙古河套及陕北）","state":"秦朝","sources":["《史记·蒙恬列传》","《史记·匈奴列传》"],"tags":["北疆","匈奴","河套"]},"related":["cn--b221--p01"]},
  {"id":"cn--b214--i01","track":"cn","year":-214,"yearApprox":false,"dim":"institution","weight":4,"title":"略定陆梁置岭南三郡","summary":"任嚣赵佗平定岭南，设南海、桂林、象三郡。","detail":{"background":"屠睢战死后秦复发诸逋亡人、赘婿、贾人南行，历数年乃定。","process":"前214年悉发诸尝逋亡人、赘婿、贾人略取陆梁地，为南海、桂林、象三郡，以谪徙民与越人杂处；任嚣为南海尉，赵佗为龙川令，行「和辑百越」之策。","impact":"岭南首次纳入郡县体系，珠江流域进入国家编户，为秦亡后南越国的割据和此后两汉经略南方奠基。","figures":["任嚣","赵佗","嬴政"],"place":"番禺（今广州）及桂林、象郡","state":"秦朝","sources":["《史记·秦始皇本纪》","《汉书·地理志》"],"tags":["岭南","郡县","谪戍"]},"related":["cn--b219--m01"]},
  {"id":"cn--b214--s01","track":"cn","year":-214,"yearApprox":false,"dim":"science","weight":3,"title":"史禄凿灵渠通湘漓","summary":"于始安绝水凿渠，连接湘江与漓江以漕军粮。","detail":{"background":"南征五岭军粮由长江水系转运，陆行翻越山岭损耗极重。","process":"前214年前后监御史禄（史禄）主持，在今广西兴安一带筑坝分水，凿长三十六里、宽约五米的渠道，使湘江与漓江相通，「饶输者得转漕」，始得通粮。","impact":"灵渠是世界上现存最早的长距离通航人工运河之一，此后两千年为中原经略岭南的水运命脉。","figures":["史禄","嬴政"],"place":"始安郡漓水县（今广西兴安县）","state":"秦朝","sources":["《史记·平津侯主父列传》","桂海虞衡志","灵渠遗址调查报告"],"tags":["水利工程","运河","漕运"]},"related":["cn--b219--m01"]},
  {"id":"cn--b214--m01","track":"cn","year":-214,"yearApprox":false,"dim":"military","weight":4,"title":"蒙恬连筑长城起临洮","summary":"因边险筑长城，起临洮至辽东万余里连接旧塞。","detail":{"background":"河南地既取，匈奴仍以骑射越界，边郡无从守险。","process":"前214年起，蒙恬「因边山险，堑溪谷，可缮者治之」，自临洮北上、沿阳山向东至辽东，全长万余里，凡筑城置戍、徙民实之，与亭障、直道构成一体防御体系。","impact":"这条防线塑造了此后中原王朝北疆的基本地理格局，修筑中的征发与死亡成为秦末动乱的直接诱因之一。","figures":["蒙恬","嬴政"],"place":"临洮至辽东一线（今甘、宁、内蒙、冀、辽）","state":"秦朝","sources":["《史记·蒙恬列传》","《史记·匈奴列传》"],"tags":["长城","边防","徭役"]},"related":["cn--b215--m01"]},
  {"id":"cn--b213--i01","track":"cn","year":-213,"yearApprox":false,"dim":"institution","weight":4,"title":"焚书令禁私学语诗书","summary":"李斯请非秦记而烧，有敢偶语诗书弃市。","detail":{"background":"前213年咸阳宫置酒，仆射周青臣颂郡县之利，齐人淳于越以「事不师古而能长久者非所闻」相驳，引发议政。","process":"李斯请史官非秦记皆烧之，天下敢藏诗、书、百家语者「悉诣守尉杂烧之」，有敢偶语诗书者弃市，以古非今者族，所不去者医药卜筮种树之书，欲有学令以吏为师。","impact":"先秦诸子文献遭受第一次制度性毁灭，「以吏为师」把知识垄断于官署，开了后世思想管制与禁书之先例。","figures":["李斯","淳于越","周青臣","嬴政"],"place":"咸阳及各郡（今陕西咸阳）","state":"秦朝","sources":["《史记·秦始皇本纪》","《汉书·艺文志》"],"tags":["焚书","思想管制","儒法之争"]},"related":["cn--b221--i03"]},
  {"id":"cn--b212--p01","track":"cn","year":-212,"yearApprox":false,"dim":"politics","weight":3,"title":"坑术士于咸阳四百余","summary":"侯生卢生亡去，始皇怒案问诸生，坑杀四百六十人。","detail":{"background":"始皇厚遇方士求不死药，卢生、侯生既不得药，又私下批评其贪于权势。","process":"前212年卢生、侯生亡去，始皇大怒，案问诸生更相告捕，坐而坑之「于咸阳，令天下闻之以惩后」，死者四百六十余人，又益发谪徙边。","impact":"此事件后被汉代儒者改述为「坑儒」，成为秦政暴虐的象征，也促成后世对焚书坑儒的长期争论。","figures":["侯生","卢生","嬴政"],"place":"咸阳（今陕西咸阳东北）","state":"秦朝","sources":["《史记·秦始皇本纪》"],"tags":["坑儒","方士","思想管制"]},"related":["cn--b213--i01"]},
  {"id":"cn--b212--a01","track":"cn","year":-212,"yearApprox":false,"dim":"art","weight":3,"title":"营建阿房宫前殿","summary":"渭南安朝官，作前殿阿房，东西五百步。","detail":{"background":"始皇以为咸阳君主之家太少，欲营朝宫于渭南以象天极。","process":"前212年开始营建朝宫，先作前殿阿房，「东西五百步、南北五十丈，上可以坐万人」，周阁为复道，自殿属咸阳，跨渭水为桥；至秦亡仍未完工，遗址在今西安三桥一带。","impact":"阿房宫成为后世文学中批判奢靡徭役的母题，考古勘探显示其前殿仅成台基，与《史记》描述有异。","figures":["嬴政"],"place":"上林苑（今西安市西郊）","state":"秦朝","sources":["《史记·秦始皇本纪》","阿房宫遗址考古勘探报告"],"tags":["宫殿建筑","徭役","秦都"]},"related":["cn--b210--e01"]},
  {"id":"cn--b212--x01","track":"cn","year":-212,"yearApprox":false,"dim":"explore","weight":3,"title":"蒙恬壅山堙谷治直道","summary":"自九原抵云阳堙山堙谷千八百里，一岁而半成。","detail":{"background":"北边驻军与京师之间道路迂回，转输与调兵迟缓。","process":"前212年使蒙恬将作治直道，自九原郡治至云阳（今内蒙包头至陕西淳化），「堙山堙谷，千八百里」，道宽可数车并行，至前210年尚未毕，始皇崩后徒刑人乃得成之。","impact":"直道与驰道构成秦代的国家级交通网，是古代军事道路工程的杰出实例，也是中央控制北疆的动脉。","figures":["蒙恬","嬴政"],"place":"九原至云阳（今内蒙古包头—陕西淳化）","state":"秦朝","sources":["《史记·秦始皇本纪》","《史记·蒙恬列传》","秦直道沿线调查简报"],"tags":["道路工程","直道","军事交通"]},"related":["cn--b215--m01"]},
  {"id":"cn--b210--p01","track":"cn","year":-210,"yearApprox":false,"dim":"politics","weight":5,"title":"沙丘之谋立胡亥","summary":"始皇崩于沙丘，赵高李斯矫诏杀扶苏而立二世。","detail":{"background":"前210年始皇东巡，至平原津而病，恶言死，群臣不敢言后事，独与少子胡亥在侧。","process":"七月丙寅始皇崩于沙丘平台，赵高说李斯合谋，秘不发丧，矫诏赐大将军蒙恬、公子扶苏死，立胡亥为太子；行从直道至咸阳发丧，九月葬骊山。","impact":"扶苏、蒙恬一系被清除，秦廷失去自我纠正的可能，统一帝国三年内崩溃，也为后世宦官外戚干政提供了原型。","figures":["赵高","李斯","胡亥","蒙恬","扶苏"],"place":"沙丘平台（今河北广宗西北）","state":"秦朝","sources":["《史记·秦始皇本纪》","《史记·李斯列传》"],"tags":["宫廷政变","矫诏","秦亡"]},"related":["cn--b212--x01"]},
  {"id":"cn--b210--e01","track":"cn","year":-210,"yearApprox":false,"dim":"economy","weight":4,"title":"骊山徒七十万与厚敛","summary":"始皇陵隐宫徒刑者七十余万人，赋敛无度民不聊生。","detail":{"background":"骊山陵园工程自即位起已历三十九年，统一后又征发北边长城、南越戍卒与转输之民。","process":"前210年「天下徒送诣七十余万人」治骊山，穿三泉、下铜而致椁，又发民转漕北河、漕输南粮，关东「男子疾耕不足于粮馈，女子纺绩不足于盖形」。","impact":"人力与征发远超小农经济的承受极限，直接引发次年的成卒起义；司马迁以「财尽力殚」概括秦财政的崩溃。","figures":["嬴政","李斯"],"place":"骊山（今陕西西安市临潼区）","state":"秦朝","sources":["《史记·秦始皇本纪》","《史记·平津侯主父列传》"],"tags":["徭役","财政崩溃","陵寝"]},"related":["cn--b212--a01"]},
  {"id":"cn--b209--m01","track":"cn","year":-209,"yearApprox":false,"dim":"military","weight":5,"title":"大泽乡戍卒斩木为兵","summary":"九百戍渔阳会蕲县大雨失期，陈胜吴广首难。","detail":{"background":"秦征闾左九百人为屯戍卒渔阳，会九月大雨，道不通，失期当斩。","process":"前209年七月，陈胜、吴广至蕲县大泽乡，「诈称公子扶苏、项燕」，袒右军，攻大泽乡，收而攻蕲，斩秦县尉；比至陈，车六七百乘、骑千余、卒数万。","impact":"这是中国第一次有明确记载的大规模农民武装起义，六国旧贵族与豪杰随之并起，秦的统治在两年内瓦解。","figures":["陈胜","吴广","葛婴"],"place":"蕲县大泽乡（今安徽宿州东南）","state":"秦朝","sources":["《史记·陈涉世家》","《史记·秦始皇本纪》"],"tags":["农民起义","戍卒","秦末"]},"related":["cn--b210--e01"]},
  {"id":"cn--b209--p01","track":"cn","year":-209,"yearApprox":false,"dim":"politics","weight":3,"title":"陈胜建号张楚","summary":"入陈县自立为将军，号张楚，诸郡县多杀长吏应之。","detail":{"background":"起义军西进至陈（今河南淮阳），当地豪杰请立六国后以号召天下，陈胜不从。","process":"前209年七月陈胜率军入陈，自立即将军位，国号「张楚」；分遣葛婴、武臣、张耳陈馀、周市、汝阴等分徇赵、魏、九江，山东云会响应，「诸郡县皆刑其长吏以应陈涉」，旬月间众至数万。","impact":"张楚政权虽四月而败，却瓦解了秦在关东的统治秩序，项羽、刘邦皆在其造成的乱局中崛起。","figures":["陈胜","武臣","张耳","陈馀"],"place":"陈县（今河南淮阳）","state":"张楚","sources":["《史记·陈涉世家》","《史记·张耳陈馀列传》"],"tags":["张楚","割据","秦末"]},"related":["cn--b209--m01"]},
  {"id":"cn--b208--a01","track":"cn","year":-208,"yearApprox":false,"dim":"art","weight":4,"title":"秦俑坑与骊陵园陪葬","summary":"兵马俑坑八千余陶俑成阵，为帝陵陪葬的宿卫军。","detail":{"background":"始皇陵园自庄襄王元年（前246年）起营建，前208年二世时犹发徒续作，前206年陵东工程因周章军至而罢。","process":"1974年在临潼西杨村发现一号坑，其后二、三号坑与未建成之四号坑总面积两万余平米，出土陶俑陶马八千余件，真人真马大小，皆塑五官铠甲、原施彩绘。","impact":"俑群是中国雕塑史上最早的大型写实陶塑群雕，也是研究秦军编制、兵器、辔具的第一手实物。","figures":["嬴政","章邯"],"place":"骊山北麓（今陕西西安临潼区）","state":"秦朝","sources":["《史记·秦始皇本纪》","《秦始皇陵兵马俑坑一号坑发掘报告1974—1984》"],"tags":["考古","陶俑","帝陵"]},"related":["cn--b210--e01"]},
  {"id":"cn--b208--m01","track":"cn","year":-208,"yearApprox":false,"dim":"military","weight":3,"title":"周章入戏与章邯反攻","summary":"起义军西至戏水，少府章邯以丽山徒免罪为前锋。","detail":{"background":"陈胜派主力周文（周章）西征，乘虚入关至骊山附近，而秦正规边军多在北方。","process":"前208年冬章邯至戏，兵少不及发兵，请「赦丽山徒多者，授之兵」击周章，周章乃却出关；章邯遂定关中，再旬之间曹阳、渑池连破起义军。","impact":"以刑徒免罪为兵一举扭转了关中危局，也使章邯军成为秦末最后的主力，直至次年降于项羽。","figures":["章邯","周章","二世胡亥"],"place":"戏水、骊山（今陕西临潼东）","state":"秦朝","sources":["《史记·项羽本纪》","《史记·秦始皇本纪》"],"tags":["刑徒兵","反攻","秦末"]},"related":["cn--b209--m01"]},
  {"id":"cn--b208--f01","track":"cn","year":-208,"yearApprox":false,"dim":"figure","weight":2,"title":"李斯具五刑腰斩咸阳","summary":"赵高案文成罪，李斯具五刑、夷三族，叹牵犬逐兔。","detail":{"background":"李斯依附二世以求位，赵高欲专权，数言其「位上卿而外慕四世之功」。","process":"前208年赵高诬斯与子李由通盗，收斯案治，榜笞数千；斯不堪苦，自陈不得见二世，最终「具斯五刑，论腰斩咸阳市」，夷三族，临刑顾谓其中子曰欲复牵黄犬俱出上蔡东门逐狡兔，岂可得乎。","impact":"法家官僚与帝国设计者的下场，象征秦中枢自毁，此后无人能约束二世与赵高的聚敛与征发。","figures":["李斯","赵高","二世胡亥"],"place":"咸阳（今陕西咸阳东北）","state":"秦朝","sources":["《史记·李斯列传》"],"tags":["丞相","宦官专权","秦末"]},"related":["cn--b210--p01"]},
  {"id":"cn--b207--m01","track":"cn","year":-207,"yearApprox":false,"dim":"military","weight":5,"title":"巨鹿之战诸侯莫敢仰视","summary":"项羽渡河破釜沉舟，九战绝秦甬道，虏王离。","detail":{"background":"章邯围巨鹿，张耳告急，楚怀王遣宋义北救，畏秦不进而项羽斩义夺军。","process":"前207年十二月（公历前206年）项羽悉引兵渡漳水，「皆沉船、破釜甑、烧庐舍，持三日粮」，至则围王离，九战绝其甬道，大破之，杀苏角、虏王离；章邯却驻棘原，项羽召见诸侯将，入辕门者「无不膝行而前，莫敢仰视」。","impact":"秦军主力由此崩溃，项羽一跃为反秦联盟的实际盟主；巨鹿成为古代以少击众、断敌粮道的经典战例。","figures":["项羽","章邯","王离","宋义"],"place":"巨鹿（今河北平乡西南）","state":"楚","sources":["《史记·项羽本纪》","《史记·张耳陈馀列传》"],"tags":["巨鹿之战","破釜沉舟","经典战役"]},"related":["cn--b208--m01"]},
  {"id":"cn--b207--p01","track":"cn","year":-207,"yearApprox":false,"dim":"politics","weight":3,"title":"指鹿为马群臣尽阿高","summary":"赵高献鹿谓马，暗计左右不附己者而阴中之。","detail":{"background":"二世居深宫，赵高独侍，恐诸侯与群臣共诛己，乃先立威验群臣之附。","process":"前207年赵高持鹿献于二世曰马，二世笑曰丞相误耶，问左右，或默或言马以阿顺高，有言鹿者高即阴中之，「于是群臣皆畏高」；同年高迫二世自杀。","impact":"中枢决策机制彻底瘫痪，秦廷最后调和的可能丧失；该成语此后成为颠倒是非、权臣胁迫君主的代称。","figures":["赵高","二世胡亥"],"place":"咸阳望夷宫（今陕西咸阳东北）","state":"秦朝","sources":["《史记·秦始皇本纪》","《史记·李斯列传》"],"tags":["权臣","朝政崩坏","秦末"]},"related":["cn--b208--f01"]},
  {"id":"cn--b207--p02","track":"cn","year":-207,"yearApprox":false,"dim":"politics","weight":5,"title":"刘邦入武关秦王子婴降","summary":"自武关入霸上，子婴素车白马系颈以组，秦遂亡。","detail":{"background":"怀王与诸将约先入关者王之，刘邦引兵西，会韩王成于张良计，下十余县，又破南阳、晓峣关。","process":"前207年十月刘邦军至霸上，子婴「系颈以组，白马素车」奉天子玺符降于轵道旁，遂入咸阳，籍吏民、封府库，还军霸上，与父老约法三章，秦历二帝十五年而亡。","impact":"秦亡与「约法三章」树立了新政宽简收心的样板，刘邦抢在项羽前取得关中的政治与地理资本。","figures":["刘邦","子婴","张良","赵高"],"place":"武关、霸上、咸阳（今陕西丹凤、西安东）","state":"秦朝","sources":["《史记·高祖本纪》","《史记·秦始皇本纪》"],"tags":["秦亡","约法三章","入关"]},"related":["cn--b207--m01", "cn--b207--p01"]},
  {"id":"cn--b207--p03","track":"cn","year":-207,"yearApprox":false,"dim":"politics","weight":3,"title":"鸿门宴范增数项王","summary":"项羽宴刘邦于鸿门，范增举玦示意而羽默然不应。","detail":{"background":"曹无伤告变，言沛公欲王关中令子婴为相，珍宝尽有之，项羽怒，旦日飨士卒为击破沛公军。","process":"前207年十二月刘邦从百余骑至鸿门谢罪，范增数目项王、举所佩玉玦以示者三，项羽默然；项伯、张良、樊哙入，刘邦托如厕间行逃归霸上，立诛曹无伤。","impact":"项羽失去了消灭刘邦的最佳机会，此事成为后世关于「妇人之仁、竖子不足与谋」的政治教训原型。","figures":["项羽","刘邦","范增","张良","樊哙"],"place":"鸿门（今陕西临潼东）","state":"西楚","sources":["《史记·项羽本纪》"],"tags":["鸿门宴","政治谋断","楚汉"]},"related":["cn--b206--p01"]},
  {"id":"cn--b206--p01","track":"cn","year":-206,"yearApprox":false,"dim":"politics","weight":4,"title":"项羽分封十八路诸侯","summary":"阳尊怀王为义帝，以沛公为汉王王巴蜀汉中。","detail":{"background":"戏下之会，诸侯三十余万，关东旧贵族与功臣各欲得地，项羽欲自立而忌刘邦居关中。","process":"前206年正月项羽尊怀王为义帝，徙之长沙郴县，阴令三王杀之；分天下王诸将相，自王梁楚九县号西楚霸王，封刘邦为汉王处巴蜀汉中，置三秦于关中以防之。","impact":"这次分封以私恩和地理制衡取代了统一的郡县，两年内即被刘邦的东出打破，但楚汉格局由此形成。","figures":["项羽","刘邦","范增"],"place":"戏下、彭城（今陕西临潼、江苏徐州）","state":"西楚","sources":["《史记·项羽本纪》","《史记·高祖本纪》"],"tags":["分封","西楚霸王","汉中对立"]},"related":["cn--b207--p02"]},
  {"id":"cn--b206--s01","track":"cn","year":-206,"yearApprox":false,"dim":"science","weight":2,"title":"项羽屠咸阳烧秦宫室","summary":"引兵西屠咸阳，烧秦宫室火三月不灭，收其货宝妇女。","detail":{"background":"新安坑卒二十余万后，项羽西入关，与刘邦已成对峙之势，关中秦民大恐。","process":"前206年十二月项羽至，遂屠咸阳，杀降王子婴，烧秦宫室，「火三月不灭」，收其货宝妇女而东，韩生说都关中而羽思东归，乃东徙都彭城。","impact":"咸阳的宫殿、府库与图书档案毁于一旦，先秦文献与制度实物的重大损失；关中的政治中心此后让位于长安。","figures":["项羽","韩信（韩生）"],"place":"咸阳（今陕西咸阳东北）","state":"西楚","sources":["《史记·项羽本纪》","《史记·高祖本纪》"],"tags":["焚毁","咸阳","战争破坏"]},"related":["cn--b212--a01"]},
  {"id":"cn--b206--e01","track":"cn","year":-206,"yearApprox":false,"dim":"economy","weight":3,"title":"汉王之国还定三秦","summary":"烧栈道示无东意，因陈计袭章邯，尽并关中。","detail":{"background":"刘邦就国南郑，士卒皆崤东人，日夜企足而望归，项羽封三秦以距汉。","process":"前206年四月汉王就国，所过烧绝栈道；八月用韩信「明修栈道、暗度陈仓」策，故道出击，围章邯于废丘，塞司马欣、董翳降，同年尽定雍、塞、翟三国地，都栎阳。","impact":"夺得关中粮仓与兵源地，是楚汉胜负的财政基础；「明修栈道暗度陈仓」成为军事佯动的千古成语。","figures":["刘邦","韩信","张良","章邯"],"place":"南郑至咸阳（今陕西汉中、西安）","state":"汉","sources":["《史记·高祖本纪》","《史记·淮阴侯列传》"],"tags":["还定三秦","栈道","关中"]},"related":["cn--b206--p01"]},
  {"id":"cn--b205--m01","track":"cn","year":-205,"yearApprox":false,"dim":"military","weight":3,"title":"彭城之败与诸侯背汉","summary":"汉聚五十六万入彭城，项羽三万骑晨击大破之。","detail":{"background":"前205年四月刘邦趁项羽北击齐地，率五诸侯兵五十六万入楚都彭城，日置酒高会。","process":"项羽以三万骑南，晨击汉军而东，大破之，「汉军皆走，相随入谷泗水，水为之不流」，死者十余万；刘邦收散卒，赖萧何发关中老未傅者来迎，诸侯复附楚背汉。","impact":"汉方元气大伤而靠关中与荥阳粮道重建防线，此后转入以荥阳—成皋为轴的消耗对峙。","figures":["刘邦","项羽","萧何","夏侯婴"],"place":"彭城（今江苏徐州）","state":"汉","sources":["《史记·项羽本纪》","《史记·高祖本纪》"],"tags":["彭城之战","以少击多","楚汉"]},"related":["cn--b206--e01"]},
  {"id":"cn--b205--p01","track":"cn","year":-205,"yearApprox":false,"dim":"politics","weight":2,"title":"下邑之谋联英布反间","summary":"张良画计：捐山东与韩信彭越，致布为羽患。","detail":{"background":"彭城败后刘邦下邑驻马，问谁能与共创功业，认识到须借重诸侯与楚将之间的矛盾。","process":"前205年五月张良献策，请捐「从信以东至海」与韩信，「睢阳以北至谷城」与彭越，使英布「反楚」，三国合力则楚可破；刘邦即从其计，随何遂使淮南。","impact":"这一战略统一战线使项羽陷入多面作战，是楚汉战争从被动转为主动的关键决策。","figures":["张良","刘邦","英布","彭越","韩信"],"place":"下邑（今安徽砀山）","state":"汉","sources":["《史记·留侯世家》","《史记·项羽本纪》"],"tags":["统一战线","谋略","楚汉"]},"related":["cn--b205--m01"]},
  {"id":"cn--b204--m01","track":"cn","year":-204,"yearApprox":false,"dim":"military","weight":2,"title":"荥阳成皋持久相持","summary":"汉筑甬道取敖仓粟，项羽数断之，荥阳几陷。","detail":{"background":"彭城败后汉退保荥阳，「筑甬道属之河，以取敖仓粟」，与楚隔汴水相持经年。","process":"前204年项羽急围荥阳，汉将军纪信乘黄屋车诳楚称「城中食尽，汉王降」，得使刘邦与数十骑出西门走；陈平以四万斤金行间，范增见疑请归，至彭城疽发背死；汉复取成皋，作甬道以转敖仓。","impact":"敖仓粮与荥阳—成皋防线使汉在兵力劣势下不被击破，「关中—荥阳」双线支撑成为后世中原战争的经典布局。","figures":["刘邦","项羽","纪信","陈平","范增"],"place":"荥阳、成皋、敖仓（今河南荥阳一带）","state":"汉","sources":["《史记·项羽本纪》","《史记·陈丞相世家》"],"tags":["成皋之战","敖仓","持久对峙"]},"related":["cn--b205--p01"]},
  {"id":"cn--b203--p01","track":"cn","year":-203,"yearApprox":false,"dim":"politics","weight":3,"title":"立萧何为丞相制律令","summary":"汉王出关至栎阳，置吏、立太子，任萧何守关中。","detail":{"background":"楚汉相持之际，汉需一个能转兵食、稳定后方的行政中枢。","process":"前203年汉王立萧何为丞相，「律令比对，次比户口，筹计多寡」，何作《九章律》之基；关中给饷馈不绝，太子盈留守栎阳，又分军置边郡。","impact":"以律令与户籍为骨架的战时行政体系，成为汉承秦制后国家治理常态化运转的枢纽。","figures":["萧何","刘邦"],"place":"栎阳、长安（今陕西西安一带）","state":"汉","sources":["《史记·萧相国世家》","《汉书·刑法志》"],"tags":["萧何","律令","战时行政"]},"related":[]},
  {"id":"cn--b202--m01","track":"cn","year":-202,"yearApprox":false,"dim":"military","weight":5,"title":"垓下楚军歌散","summary":"韩信十面埋伏，围项羽垓下，夜闻四面皆楚歌。","detail":{"background":"前203年鸿沟和约后项羽东归，刘邦用张良、陈平「养虎自遗患」之计，回军追之，齐王韩信不至，乃益封而会军。","process":"前202年十二月（公历前202年初）刘贾、英布、韩信与将军柴武、周殷别击城父，会于垓下，卒六十万，楚卒十万，韩信用「十面埋伏」，夜闻四面皆楚歌，以为楚地尽入于汉，羽夜起饮帐中，悲歌泣下，遂溃围南出。","impact":"楚军主力在垓下被歼，项羽乌江自刎，历时四年的楚汉战争结束，中国再次归于一个稳定的统一政权。","figures":["韩信","刘邦","项羽","张良","陈平"],"place":"垓下（今安徽固镇东、灵璧南）","state":"汉","sources":["《史记·项羽本纪》","《史记·高祖本纪》"],"tags":["垓下之战","四面楚歌","楚汉"]},"related":["cn--b203--p01"]},
  {"id":"cn--b202--f01","track":"cn","year":-202,"yearApprox":false,"dim":"figure","weight":2,"title":"项羽乌江自刎","summary":"二十八骑突围至乌江，拒亭长渡江，自刎而死。","detail":{"background":"垓下突围至东城，只剩二十八骑，分四队驰山下，斩汉一将，犹曰天亡我非战之罪。","process":"前202年十二月至乌江，亭长具船曰江东虽小地方千里众数十万人亦足王也，羽笑谢之，以骑赠亭长，步战手杀汉军数百人，身被十余创，见故人吕马童，「吾为若德」乃自刎，年三十一，汉以鲁公礼葬谷城。","impact":"其败被后世反复书写为「时势与个人」的悲剧典型，「不肯过江东」成为耻于失败而归的政治人格符号。","figures":["项羽","吕马童","乌江亭长"],"place":"乌江（今安徽和县东北）","state":"西楚","sources":["《史记·项羽本纪》"],"tags":["项羽","自刎","悲剧英雄"]},"related":["cn--b202--m01"]},
  {"id":"cn--b202--p01","track":"cn","year":-202,"yearApprox":false,"dim":"politics","weight":5,"title":"刘邦即皇帝位于定陶","summary":"齐王韩信等率群臣上书请尊大号，汉王即真。","detail":{"background":"垓下后项羽已死，唯异姓诸侯王势盛，群臣以「大王虽即皇帝位，天下未集」请定名分。","process":"前202年二月（公历前202年春）楚王韩信、韩王信、淮南王英布、梁王彭越等与列侯将相上书，曰「大王德施四海，臣等以为皇帝宜当」，王三让乃即皇帝位于定陶氾水之阳，尊父太公曰太上皇，次日赦，五月兵休士卒皆罢归家。","impact":"汉代四百年统治自此始；其即位方式（诸侯将相共推）也暴露了帝国初期皇权与异姓王共存的脆弱结构。","figures":["刘邦","韩信","张良","叔孙通"],"place":"定陶（今山东定陶）","state":"西汉","sources":["《史记·高祖本纪》","《汉书·高帝纪》"],"tags":["西汉开国","皇帝即位","定陶"]},"related":["cn--b202--m01"]},
  {"id":"cn--b202--i01","track":"cn","year":-202,"yearApprox":false,"dim":"institution","weight":5,"title":"汉初郡国并行","summary":"承秦郡县而又裂土封王，王国侯国与郡县杂处。","detail":{"background":"刘邦以「秦孤立而亡」为诫，又不得不酬异姓功臣，遂采取折中的地方制度。","process":"前202年后，先后封楚、齐、淮南、梁、赵、燕、韩等异姓七王，复以同姓代之，王国「宫殿官僚号称天子」，实际辖郡数至十余，郡内置都尉；同时保留郡、县、乡、里与列侯食邑。","impact":"郡国并行既安抚了功臣豪强，也酿成七国之乱；此后削藩与「推恩令」的整个流程都是对该制度的矫正。","figures":["刘邦","张良","萧何"],"place":"长安及各王国（今陕西关中与关东）","state":"西汉","sources":["《史记·汉兴以来诸侯王年表》","《汉书·地理志》"],"tags":["郡国并行","封建","地方制度"]},"related":["cn--b221--i02", "cn--b202--p01"]},
  {"id":"cn--b202--e01","track":"cn","year":-202,"yearApprox":false,"dim":"economy","weight":4,"title":"汉初困乏天子不能具钧驷","summary":"自天子不能具钧驷，而将相或乘牛车，米至石万钱。","detail":{"background":"秦末「兵革数起，男子疾耕不得于粮馈」，又经楚汉五年战争，关东人口流亡、田畴荒废。","process":"前202年前后「米至石万钱，马一匹则百金」，乃令贾人不得衣丝乘车、重租税以困辱之，并「令民得卖子就食蜀汉」，同时罢兵散卒复故秦田宅，军卒守关者免其家。","impact":"经济破产迫使汉初六十年行「无为而治、与民休息」，轻徭薄赋与省刑成为基本国策，文景之治由此铺垫。","figures":["刘邦","萧何"],"place":"关中关东（今陕西、河南）","state":"西汉","sources":["《史记·平准书》","《汉书·食货志》"],"tags":["经济凋敝","重农抑商","休养生息"]},"related":["cn--b210--e01"]},
  {"id":"cn--b201--p01","track":"cn","year":-201,"yearApprox":false,"dim":"politics","weight":3,"title":"韩王信徙国马邑降匈奴","summary":"汉徙韩王信守北边，被围马邑，遂与匈奴约攻汉。","detail":{"background":"汉以韩王信王韩，忌其材武，前201年春徙之太原，都晋阳，使拒匈奴；信以马邑在边急，请徙治马邑。","process":"前201年秋匈奴冒顿急围马邑，信数遣使与匈奴求和，汉使让之，信惧诛，遂与匈奴约共攻汉，夺太原；十一月高帝自将击之，初战连胜，遂北逾勾注进至平城。","impact":"异姓王与北疆势力结合，直接引发白登被围，也使汉廷对异姓王的猜忌转为翦除，加速了郡国关系的重组。","figures":["韩王信","冒顿单于","刘邦"],"place":"马邑、晋阳（今山西朔州、太原）","state":"西汉","sources":["《史记·韩信卢绾列传》","《汉书·匈奴传》"],"tags":["韩王信","匈奴","异姓王"]},"related":["cn--b202--i01"]},
  {"id":"cn--b200--p01","track":"cn","year":-200,"yearApprox":false,"dim":"politics","weight":4,"title":"白登之围与和亲之议","summary":"高帝被围平城白登七日得解，始与匈奴约为和亲。","detail":{"background":"汉军轻进，冒顿以老弱示弱诱其深入，精骑四十万别而夹击。","process":"前200年（一说前201年冬）高帝至平城，为匈奴围于白登山七日，「军中不得食，外内隔绝」，遣使赂阏氏、用陈平奇计围乃解；还从刘敬议，以宗室女为公主嫁单于，岁致匈奴絮缯酒米食物，约为昆弟，并徙齐诸田、楚昭屈景、燕赵韩魏后与豪吏实关中。","impact":"汉朝承认暂时无力以武力解决北疆问题，和亲与馈赠政策延续七十余年；「强干弱枝」的迁民政策则成为定制。","figures":["刘邦","冒顿单于","陈平","刘敬"],"place":"平城白登山（今山西大同东北）","state":"西汉","sources":["《史记·匈奴列传》","《史记·高祖本纪》","《中国历史纪年表》"],"tags":["白登之围","和亲","匈奴"]},"related":["cn--b201--p01"]},
  {"id":"cn--b200--i01","track":"cn","year":-200,"yearApprox":false,"dim":"institution","weight":3,"title":"叔孙通朝仪成皇帝之贵","summary":"采古礼与秦仪杂就之，诸侯群臣无敢喧哗失礼。","detail":{"background":"汉初功臣在朝廷上饮争功、醉或妄呼、拔剑击柱，高祖患之，谓「吾乃今日知为皇帝之贵也」。","process":"约前200至前199年，叔孙通征鲁诸生三十余人，「采古礼与秦仪杂就之」，习月余，于长乐宫大朝会应用：谒者掌礼，诸侯王以下莫不振恐肃敬，御史执法举不如仪者辄引去；通由此为太子太傅。","impact":"以仪式化的君臣秩序重塑了朝廷政治，儒学由此进入国家礼制，为后来「独尊儒术」准备了技术前提。","figures":["叔孙通","刘邦","陆贾"],"place":"长乐宫（今陕西西安西北）","state":"西汉","sources":["《史记·刘敬叔孙通列传》","《汉书·礼乐志》"],"tags":["朝仪","儒学","礼制"]},"related":[]},
  {"id":"cn--b196--p01","track":"cn","year":-196,"yearApprox":false,"dim":"politics","weight":4,"title":"长乐宫钟室诛韩信","summary":"吕后用萧何谋伪称陈豨已破，袭杀楚王信，夷三族。","detail":{"background":"前201年后汉廷陆续疑忌异姓功王，韩信先由楚王徙封淮阴，又坐告陈豨谋反而被夺国居长安。","process":"前196年正月，陈豨反于代，高祖自将；吕后与萧何诈称「豨已败死，群臣皆贺」，诱称病不朝之韩信入长乐宫钟室，使武士斩之，「夷信三族」，临终叹「悔不用蒯通之言」。","impact":"开汉代以谋反案翦除异姓王先例，「成也萧何、败也萧何」成为功高见忌的政治寓言；异姓王问题此后至文帝时基本解决。","figures":["吕后","萧何","韩信","陈豨"],"place":"长安长乐宫（今陕西西安西北）","state":"西汉","sources":["《史记·淮阴侯列传》","《汉书·高帝纪》"],"tags":["异姓王","韩信","吕后"]},"related":["cn--b202--i01"]},
  {"id":"cn--b196--m01","track":"cn","year":-196,"yearApprox":false,"dim":"military","weight":3,"title":"淮南王英布举兵反","summary":"见诛醢彭越，恐及己，东返兵反，立败于会氏。","detail":{"background":"前196年夏，吕后醢梁王彭越以其肉赐诸侯，淮南王英布见而恐，阴令人聚兵备汉。","process":"秋七月英布反，东并吴，西渡淮，与汉兵会战蕲西会氏，布兵精，初战破汉前行，高祖自将三十万（一说身被流矢）壁庸城，望布军置阵如项羽，骂而降，布走江南，前195年年底为番阳人所杀。","impact":"最后一支异姓王军队被消灭，汉代中央对东方的直接控制推进至吴楚之地，也为七国之乱的地理格局埋下伏笔。","figures":["英布","刘邦","彭越"],"place":"淮南、会氏（今安徽六安、霍州一带）","state":"西汉","sources":["《史记·黥布列传》","《汉书·高帝纪》"],"tags":["英布","异姓王","平叛"]},"related":["cn--b196--p01"]},
  {"id":"cn--b195--p01","track":"cn","year":-195,"yearApprox":false,"dim":"politics","weight":3,"title":"高帝崩于长乐宫","summary":"四月甲辰高祖崩，太子盈立，太子母吕后专政。","detail":{"background":"前196年征英布军中被流矢所中，道病愈甚，吕后问萧何以后可相国者。","process":"前195年四月甲辰高祖崩于长乐宫，葬长陵，太子盈即位是为惠帝，年十七，吕后立为皇太后；同年诏郡国立高祖庙，令春三月祠之，并颁「与天下豪士共定天下者世世不绝」之令。","impact":"主少母壮的局面使吕后得以临朝称制，惠帝一朝的政令多出太后，成为中国外戚政治的第一个完整案例。","figures":["刘邦","惠帝刘盈","吕后","萧何"],"place":"长安长乐宫（今陕西西安西北）","state":"西汉","sources":["《史记·吕太后本纪》","《汉书·高帝纪》"],"tags":["高祖崩","惠帝","外戚"]},"related":["cn--b196--m01"]},
  {"id":"cn--b195--i01","track":"cn","year":-195,"yearApprox":false,"dim":"institution","weight":4,"title":"白马之盟非刘氏不得王","summary":"刑白马而盟，非刘氏而王者天下共击之。","detail":{"background":"异姓王尽除之后，高祖以「秦孤立无辅」而亡为鉴，大封同姓子弟为王。","process":"前195年二月与群臣刑白马而盟，定「非刘氏而王，天下共击之；非有功不得侯」之约，以周勃、陈平、灌婴等列侯为侯功标准，又定「无功赏、毋德爵」之律（《二年律令·置后律》《史律》可见其制）。","impact":"这次盟誓成为汉代的最高宪章，前180年诛诸吕即以「违盟」为法理依据，并在后世反复被援引为宗藩与功臣权力的边界。","figures":["刘邦","周勃","陈平"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《史记·汉兴以来诸侯王年表》","《史记·吕太后本纪》","张家山汉简《二年律令》"],"tags":["白马之盟","同姓封王","功臣制度"]},"related":["cn--b196--p01"]},
  {"id":"cn--b195--c01","track":"cn","year":-195,"yearApprox":false,"dim":"culture","weight":2,"title":"陆贾奏新语十二篇","summary":"以「马上得之，宁可以马上治之乎」为汉初立论。","detail":{"background":"高帝谓陆贾试为我著秦所以失天下、吾所以得之者何，及古成败之国。","process":"约前196至前195年陆贾奉命述无为之要，「粗陈存亡之征，奏之，天子未尝不称善」，凡十二篇，号曰《新语》，以仁义为治本，以陆莒为不学诗书之戒。","impact":"这是汉代第一篇系统总结秦亡教训的政论，开贾谊《过秦论》、桓宽《盐铁论》之先，也标志儒术开始在汉廷取得话语权。","figures":["陆贾","刘邦"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《史记·郦生陆贾列传》","《新语·道基》"],"tags":["新语","秦鉴","儒学"]},"related":["cn--b195--i01"]},
  {"id":"cn--b194--s01","track":"cn","year":-194,"yearApprox":false,"dim":"science","weight":3,"title":"发十四万人始筑长安城","summary":"元年筑长安，六年而成，周回六十五里。","detail":{"background":"高帝仅居长乐、未央两宫，栎阳为临时之都，惠帝欲以京师象天子之制。","process":"前194年（惠帝元年）发长安方圆六百里内男女十四万六千人筑城，三十日罢，每年三旬一发；前192年复发十万六千人，前190年五月新城成，周回六十五里，十六门，与未央、长乐、桂宫等相错。","impact":"长安成为当时世界上规模最大的都城之一，其不规则斗形布局因依渭水与旧宫地形，成为后世都城规划的典型。","figures":["惠帝刘盈","萧何"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《史记·吕太后本纪》","《汉书·惠帝纪》","汉长安城遗址考古勘探报告"],"tags":["都城建设","长安","徭役"]},"related":["cn--b200--i01"]},
  {"id":"cn--b191--i01","track":"cn","year":-191,"yearApprox":false,"dim":"institution","weight":3,"title":"惠帝除挟书律","summary":"四年除挟书律，民间藏书与私学之禁乃解。","detail":{"background":"前213年秦焚书令「非博士官所职而敢藏诗书百家语者」弃市，汉初犹承秦法未及删改。","process":"前191年（惠帝四年）十一月诏除挟书律，民间始可自由藏书授受，河间献王、鲁中堂等遂得收先秦旧籍；至文帝又置《诗》《书》《论语》《孝经》博士，前136年定五经。","impact":"这一纸废止令使先秦典籍在民间重新流通，是汉代经学复兴与后来石渠阁、天禄阁校书得以可能的制度前提。","figures":["惠帝刘盈","高帝诸臣"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《汉书·惠帝纪》","《汉书·艺文志》"],"tags":["挟书律","书籍","经学复兴"]},"related":["cn--b213--i01"]},
  {"id":"cn--b188--p01","track":"cn","year":-188,"yearApprox":false,"dim":"politics","weight":2,"title":"惠帝崩吕后立少帝","summary":"秋八月帝崩，太后哭不下泣，立昌邑王为太子。","detail":{"background":"惠帝见戚夫人为人彘而病，日饮淫乐不听政，在位七年，前188年秋八月丁卯崩于未央宫。","process":"葬安陵后，吕后「哭而不下泣」，命立皇后张氏之子为帝（前187年），密令左右毋泄；同年以审食其左丞相入宫决事，「号令出于房闼」，实际开始临朝。","impact":"少帝之立使皇统名实分离，吕氏由此全面掌握南北军与相位，为七年后周勃、陈平的政变提供了口实。","figures":["吕后","惠帝刘盈","审食其"],"place":"长安未央宫（今陕西西安西北）","state":"西汉","sources":["《史记·吕太后本纪》","《汉书·高后纪》"],"tags":["吕后","少帝","女主临朝"]},"related":["cn--b195--p01"]},
  {"id":"cn--b187--p01","track":"cn","year":-187,"yearApprox":false,"dim":"politics","weight":4,"title":"吕后临朝称制","summary":"正月元日太后遂称制，号令一出，四字为高后。","detail":{"background":"前187年正月，吕后废杀前少帝，立常山王义为帝，「帝进自称臣于太后」，诸事皆决于后。","process":"前187年（高后元年）改元称制，「天下事无大小皆决焉」；封吕台为吕王、产为吕王、禄为绛侯，又杀赵幽王友、共王恢，以吕氏女妻诸刘王。","impact":"这是中国历史上第一次太后专政的全面运行，其用人方式确立「诸吕不典兵则权不固」的先例，也被后世当作外戚戒鉴的标本。","figures":["吕后","吕台","吕产","吕禄"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《史记·吕太后本纪》","《汉书·高后纪》"],"tags":["外戚","太后临朝","诸吕"]},"related":["cn--b188--p01", "cn--b195--i01"]},
  {"id":"cn--b187--i01","track":"cn","year":-187,"yearApprox":false,"dim":"institution","weight":2,"title":"高后除三族罪妖言令","summary":"元年除三族罪、妖言令，约法省刑继续推进。","detail":{"background":"惠帝、高后之际承「无为而治」，刑罚之网自高祖入关约法三章以来持续收束。","process":"前187年（高后元年）诏除三族罪与「妖言令」，以族刑与以言罪人之律文被废止；同年又除「见厌不完者」之令，「刑罚罕用，罪人是希」，民务稼穑衣食滋殖。","impact":"肉刑连坐的减轻与文景时除收帑相坐、除肉刑相衔接，构成汉初法制从秦系重刑向宽省转折的中间环节。","figures":["吕后"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《汉书·高后纪》","《汉书·刑法志》"],"tags":["刑法","省刑","高后"]},"related":["cn--b191--i01"]},
  {"id":"cn--b187--p02","track":"cn","year":-187,"yearApprox":false,"dim":"politics","weight":3,"title":"诸吕分掌南北军","summary":"王诸吕四人，居长安者典兵，居京师者卫两宫。","detail":{"background":"高后欲以吕氏为屏藩，又忌刘氏与功臣共谋。","process":"前187至前180年间，先后封吕台（吕王）、吕产（吕王）、吕禄（赵王），「吕产为吕王将南军，吕禄为上将军将北军」，诸吕皆王；又令「诸王皆徙封」，把齐、赵等大藩移置于吕女控制之下。","impact":"诸吕掌军直接违反了白马之盟，也造成功臣派与宗室派的恐惧与结盟，是前180年政变最直接的导火线。","figures":["吕后","吕产","吕禄","刘章"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《史记·吕太后本纪》","《史记·孝文本纪》"],"tags":["诸吕","南北军","外戚专权"]},"related":["cn--b187--p01"]},
  {"id":"cn--b180--m01","track":"cn","year":-180,"yearApprox":false,"dim":"military","weight":4,"title":"周勃夺北军诛诸吕","summary":"曲周侯劫郦寄夺将印，北军左袒为刘，遂斩吕产。","detail":{"background":"前180年七月高后崩，遗诏赐诸侯王、大酺十五日，吕产、吕禄畏诛，欲为乱，未发。","process":"九月，丞相陈平与太尉周勃合谋，使人劫郦寄令绐吕禄归印，「太尉将入军门，行令军中曰：为吕氏右袒，为刘氏左袒」，军皆左袒；周勃遂北军，入未央宫阙，逐斩吕产、吕禄，尽捕诸吕无少长皆斩之。","impact":"功臣派以一次宫廷军事政变维护了白马之盟，也由此取得拥立之功，导致文帝初期「列侯用事、权在右姓」的格局。","figures":["周勃","陈平","刘章","魏其侯窦婴","纪通"],"place":"长安北军、未央宫（今陕西西安西北）","state":"西汉","sources":["《史记·吕太后本纪》","《史记·孝文本纪》"],"tags":["诛诸吕","政变","北军"]},"related":["cn--b187--p02", "cn--b195--i01"]},
  {"id":"cn--b180--p01","track":"cn","year":-180,"yearApprox":false,"dim":"politics","weight":3,"title":"迎立代王恒为文帝","summary":"薄姬之子代王以仁孝闻，五月己酉即位。","detail":{"background":"诛诸吕后少帝实非惠帝子，齐王有强弟而不立，功臣欲择「谨良」之王。","process":"前180年十一月遣使迎代王刘恒，代王与郎中令张武议，薄太后与宋昌以「汉之为汉，几四岁矣」定策，宋昌占之得「横吉、震用作龙」，至长安，代王即位于代邸，即舍人北入未央宫，夜拜宋昌为卫将军，二月立皇太子。","impact":"文帝以旁支入继，其即位依赖功臣拥戴，故初期君相对外戚（窦氏）与列侯（周勃、灌婴）极为谦抑，「文景之治」的宽松政治由此定型。","figures":["文帝刘恒","宋昌","张武","薄太后","周勃"],"place":"代（今山西太原一带）至长安","state":"西汉","sources":["《史记·孝文本纪》","《汉书·文帝纪》"],"tags":["文帝即位","旁支入继","谦抑"]},"related":["cn--b180--m01"]},
  {"id":"cn--b179--i01","track":"cn","year":-179,"yearApprox":false,"dim":"institution","weight":3,"title":"文帝除收帑相坐律令","summary":"元年十二月除收帑诸相坐律令，罪人不孥。","detail":{"background":"秦法有「收帑」（籍没妻子为帑）与族坐相承之律，汉初萧何《九章律》犹因其制。","process":"前179年（文帝元年）十二月有司请「族大罪一人，以惩恶止乱」，文帝谓「法所以禁暴止乱，非法以虐民」，诏除收帑诸相坐律令，「罪人已在，帑不当收」。","impact":"以诏令形式废止连坐籍没，使家庭与人身责任相分离，是汉初省刑政策的关键一步，也为缇萦上书废肉刑铺平了舆论。","figures":["文帝刘恒","有司"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《史记·孝文本纪》","《汉书·刑法志》","张家山汉简《二年律令》"],"tags":["连坐","省刑","文帝"]},"related":["cn--b187--i01"]},
  {"id":"cn--b178--e01","track":"cn","year":-178,"yearApprox":false,"dim":"economy","weight":4,"title":"诏赐民田租之半","summary":"二年三月诏收租三十而税一，农民负担减半。","detail":{"background":"高帝「十五税一」，文帝即位后以「力田，生民之本」为口号屡蠲田租。","process":"前178年（文帝二年）三月「赐天下民今年田租之半」，把十五税一改行三十税一，前167年更「除田之租税」，十三年乃复收；同时减口赋、弛山泽、省苑马。","impact":"三十税一成为汉代田租的长期标尺，也促成文景时「京师之钱累百钜万，贯朽而不可校；太仓之粟陈陈相因」的国库积累。","figures":["文帝刘恒"],"place":"全国（京师长安排除）","state":"西汉","sources":["《汉书·文帝纪》","《史记·平准书》","《汉书·食货志》"],"tags":["三十税一","轻徭薄赋","文景之治"]},"related":["cn--b202--e01"]},
  {"id":"cn--b178--i01","track":"cn","year":-178,"yearApprox":false,"dim":"institution","weight":3,"title":"除诽谤妖言之罪","summary":"二年五月诏除「诽谤妖言之罪」，使下情得尽。","detail":{"background":"秦有「偶语诗书弃市、诽谤族」之法，汉初律令仍有约束议政之条。","process":"前178年（文帝二年）五月诏曰「今法有诽谤妖言之罪，是使众臣不敢尽情而上无由闻过也」，其除之；又除秘祝之官，自谓「民未安，唯法之失」。","impact":"言路在法律上被打开，文景一朝贤良文学、贾山《至言》、贾谊诸疏得以直陈得失，构成汉代「对策」政治的传统。","figures":["文帝刘恒","贾山"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《史记·孝文本纪》","《汉书·文帝纪》"],"tags":["言路","诽谤罪","文帝"]},"related":["cn--b212--p01"]},
  {"id":"cn--b175--e01","track":"cn","year":-175,"yearApprox":false,"dim":"economy","weight":3,"title":"更铸四铢钱听民放铸","summary":"五年以钱益多而轻，更铸四铢钱，除盗铸令。","detail":{"background":"汉初「为秦钱重难用，更令民铸荚钱」，至文帝时「钱益多而轻」，米贵而物贱，币制紊乱。","process":"前175年（文帝五年）更铸四铢钱，文曰半两，重如其文，除盗铸钱令使民放铸；贾谊上疏谏「铸钱有四祸」，谓「法使天下公得顾租铸铜锡为钱，敢杂以铅铁为他巧者，其罪黥」。","impact":"自由铸钱使邓通、吴王濞「以铸钱富」，地方财力与货币发行权膨胀，成为武帝盐铁官营与上林三官铸五铢的直接动因。","figures":["文帝刘恒","贾谊","邓通","吴王刘濞"],"place":"长安与吴、蜀（今江苏苏州、四川）","state":"西汉","sources":["《汉书·食货志》","《史记·佞幸列传》","《贾谊新书·铜布》"],"tags":["四铢钱","自由铸钱","货币"]},"related":["cn--b178--e01"]},
  {"id":"cn--b174--p01","track":"cn","year":-174,"yearApprox":false,"dim":"politics","weight":2,"title":"冒顿单于死老上立","summary":"匈奴冒顿死，太子老上单于立，仍以和亲为约。","detail":{"background":"冒顿击杀鸣镝弑父后单于，破东胡、逐月氏，控弦三十万，是匈奴极盛之主。","process":"前174年冒顿死，右贤王前与汉和亲之宗室女妻之；太子稽鬰（老上单于）立，继续向西域进取，约前174—前160年间击败大月氏，杀月氏王以其头为饮器。","impact":"老上单于时期匈奴仍是汉北方最大压力源，前166年入朝那萧关即在其任；同时匈奴西征改变了中亚部族格局。","figures":["冒顿单于","老上单于","文帝刘恒"],"place":"龙城（今蒙古国鄂尔浑河流域）","state":"匈奴","sources":["《史记·匈奴列传》","《汉书·匈奴传》"],"tags":["匈奴","单于更替","和亲"]},"related":["cn--b201--p01"]},
  {"id":"cn--b174--p02","track":"cn","year":-174,"yearApprox":false,"dim":"politics","weight":2,"title":"淮南王刘长谋反废迁道死","summary":"杀辟阳侯、自比天子，谋反觉，废迁蜀道不食死。","detail":{"background":"刘长以文帝同产弟骄恣，不受汉法，前177年以铁椎杀辟阳侯审食其，又请得称太子、自置御史，出入称警跸。","process":"刘长以文帝弟骄恣，前177年杀辟阳侯审食其，又请太子、自置御史；前174年（文帝六年）与棘蒲侯太子奇谋反，遣使北约匈奴、南连闽越，事觉，有司请诛，文帝「不忍致法于王」，赦其死、废王号，徙严道蜀郡，「载以辎车，令县次传」；长安令袁盎追谏「上所不忍，暴之不食死」，长果不食死，葬雍。","impact":"文帝以「亲弟不忍加刑」处理宗藩，被贾谊批为「立可为之后，以乱宗庙」，其优柔使诸侯王割据的危险延至景帝削藩。","figures":["刘长","文帝刘恒","袁盎","审食其"],"place":"寿春至雍（今安徽寿县、陕西凤翔）","state":"西汉","sources":["《史记·淮南衡山列传》","《汉书·贾谊传》"],"tags":["宗藩","淮南王","削藩"]},"related":["cn--b155--p01"]},
  {"id":"cn--b169--c01","track":"cn","year":-169,"yearApprox":false,"dim":"culture","weight":3,"title":"晁错上论贵粟疏","summary":"以「方今之务莫若使民务农」，请入粟拜爵实边。","detail":{"background":"文帝时「商贾大者积贮倍息，小者坐列贩卖」，农民「男不耕耘，女不蚕织」而流亡日众。","process":"约前169年（文帝前元十一年）御史大夫晁错上《论贵粟疏》，请「募天下入粟县官，得以拜爵除罪」，以「粟者，王者大用，政之本务」立论，又请「募民徙塞下」以代远戍。","impact":"疏入即见用，「拜爵、免罪」与输粟之令成为汉代常平仓与实边政策的理论源头，也塑造了此后两千年「重农抑商」政策的话语范式。","figures":["晁错","文帝刘恒"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《汉书·食货志》","《汉书·晁错传》"],"tags":["重农","贵粟","实边"]},"related":["cn--b178--e01"]},
  {"id":"cn--b168--d01","track":"cn","year":-168,"yearApprox":false,"dim":"disaster","weight":3,"title":"黄河决酸枣东溃金堤","summary":"十二年河决酸枣，东溃金堤，发卒数万塞之。","detail":{"background":"汉初河堤久废，关东平原水利失修，「东郡、陈留、济阴、山阳」一带尤受河患。","process":"前168年（文帝十二年）「黄河决酸枣，东溃金堤」，于是「东郡大兴卒塞之」，发卒数万人，以「下淇园之竹以为楗」；前168年又东周「河水溢于平原」。","impact":"这次决口是两汉治河的起点性事件，武帝瓠子之塞与王景之治河都在其经验延长线上，金堤成为黄河堤防的通名。","figures":["文帝刘恒"],"place":"酸枣、金堤（今河南延津、原阳一带）","state":"西汉","sources":["《汉书·文帝纪》","《史记·河渠书》"],"tags":["河患","金堤","治河"]},"related":["cn--b169--c01"]},
  {"id":"cn--b168--f01","track":"cn","year":-168,"yearApprox":false,"dim":"figure","weight":1,"title":"贾谊自伤为傅无状卒","summary":"梁怀王坠马死，谊哭泣岁余亦卒，年三十有三。","detail":{"background":"谊以文帝召为博士，一岁中超太中大夫，因绛灌之属毁之，出为长沙王太傅、梁怀王太傅。","process":"前169年（一说前168年）梁怀王刘揖坠马而死，谊「自伤为傅无状」，「哭泣岁余亦死」，年三十三；其《陈政事疏》《过秦论》《吊屈原赋》《鵩鸟赋》皆传于世。","impact":"这位三十三岁去世的政治家兼辞赋家，是汉初思想与文学转型的象征，其「众建诸侯而少其力」之议被文帝、武帝先后实施。","figures":["贾谊","梁怀王刘揖","文帝刘恒"],"place":"长沙、梁国（今湖南长沙、河南商丘）","state":"西汉","sources":["《史记·屈原贾生列传》","《汉书·贾谊传》"],"tags":["贾谊","辞赋","政治悲剧"]},"related":["cn--b169--c01"]},
  {"id":"cn--b168--i01","track":"cn","year":-168,"yearApprox":false,"dim":"institution","weight":2,"title":"除关无用传弛关禁","summary":"十二年除关，无用传，关梁之禁大弛。","detail":{"background":"汉都关中，以函谷、潼关等六关为限，出入持「传」以验身份，「关梁所以禁末流、备非常」。","process":"前168年（文帝十二年）诏「除关，无用传」，又「开关梁，弛山泽之禁」，行旅与商贾往来不再受符传限制；至景帝中六年（前144）又「更限诸关」，出入复须符籍。","impact":"关禁松弛造成「衣食滋殖，万物众伙」的国内大市场，也促成游士与商人跨地域活动，武帝时以算缗告缗再施收紧。","figures":["文帝刘恒"],"place":"函谷关、潼关（今河南灵宝、陕西潼关）","state":"西汉","sources":["《史记·孝文本纪》","《汉书·文帝纪》","《史记·货殖列传》"],"tags":["关禁","符传","商业自由"]},"related":["cn--b175--e01"]},
  {"id":"cn--b167--e01","track":"cn","year":-167,"yearApprox":false,"dim":"economy","weight":3,"title":"募民徙塞下实边备胡","summary":"用晁错议徙民塞下，筑室置伍、择肥饶近水处。","detail":{"background":"匈奴入边「得塞内之畜产而无所归」，远调戍卒「一岁而代」，不知敌情，边备常虚。","process":"约前169至前167年文帝从其议「募民欲徙塞下」：先为筑室、置伍有率、「择邑里之肥饶、近水泉者」，「令远方之卒守塞一岁而代，不如选常居者、家室田作且以备」；「民至，为筑室，有一门内，具兵器、教习战射」，边塞自此有定居之农兵。","impact":"把屯田与乡里编制移植到边防，成为武帝元朔年间置朔方郡（前127）的直接蓝本，也是古代屯戍制度的定型之作。","figures":["晁错","文帝刘恒"],"place":"北边塞下、朔方（今内蒙古河套与陕北）","state":"西汉","sources":["《汉书·晁错传》","《史记·平津侯主父列传》"],"tags":["实边","屯田","晁错"]},"related":["cn--b169--c01"]},
  {"id":"cn--b166--m01","track":"cn","year":-166,"yearApprox":false,"dim":"military","weight":3,"title":"匈奴十四万骑入朝那萧关","summary":"老上单于入北地杀都尉孙卬，候骑至雍甘泉。","detail":{"background":"前162年汉与匈奴复和亲，文帝前元十四年匈奴约期背盟入边。","process":"前166年冬匈奴十四万骑入朝那、萧关，杀北地都尉孙卬，虏人民畜产甚多，「燔烽候」，候骑至雍甘泉宫；文帝以周亚夫、刘礼、徐厉将骑三万屯细柳、霸上、棘门，自将驻霸上，遣张释之等让单于，匈奴塞外去。","impact":"这次深入关中的入侵宣告和亲政策的破产，迫使汉朝改取「屯边积粟、以民实塞」的长期防御战略，直至武帝转守为攻。","figures":["老上单于","文帝刘恒","周亚夫","孙卬"],"place":"朝那、萧关、细柳（今宁夏彭阳、甘肃环县）","state":"西汉","sources":["《史记·匈奴列传》","《史记·绛侯周勃世家》"],"tags":["萧关之入侵","北边","和亲破产"]},"related":["cn--b174--p01"]},
  {"id":"cn--b164--p01","track":"cn","year":-164,"yearApprox":false,"dim":"politics","weight":4,"title":"分齐为六分淮南为三","summary":"齐文王薨无后，帝从其策，裂大藩为九以弱之。","detail":{"background":"贾谊「众建诸侯而少其力」之议与文帝前元时的削藩思路至此落地；齐、赵、淮南三系大藩并立为患。","process":"前164年（文帝十六年）齐文王则无嗣国除，帝乃「举尽裂齐地以为六」：齐、城阳、济北、济南、菑川、胶西；又分淮南为三：衡山、庐江、淮南，徙长沙王梁为梁王以临东方。","impact":"以分封代替夺除，兵不血刃地把最大两个藩国肢解，推恩令不过是这一手法的制度化；梁国则成为朝廷屏障与后来七国之乱的焦点。","figures":["文帝刘恒","贾谊","梁孝王刘武"],"place":"齐、淮南地（今山东、安徽一带）","state":"西汉","sources":["《史记·孝文本纪》","《汉书·景十三王传》","《贾谊新书·藩强》"],"tags":["削藩","众建诸侯","文帝"]},"related":["cn--b174--p02"]},
  {"id":"cn--b158--m01","track":"cn","year":-158,"yearApprox":false,"dim":"military","weight":2,"title":"细柳霸上棘门三军备胡","summary":"后六年三将军长安旁以备匈奴，文帝亲劳。","detail":{"background":"前158年（文帝后六年）匈奴二万骑入上郡、三万骑入中地，北边烽候大急，帝乃「拜中尉周亚夫为将军军细柳」。","process":"前158年以河内守周亚夫、宗正刘礼、祝兹侯徐厉分屯细柳、霸上、棘门，「以备胡」，文帝自劳军，至细柳「军士吏被甲、锐兵刃、彀弓弩持满」，天子先驱不得入，乃「使使持节诏将军」，成礼而去。","impact":"细柳营成为古代军礼与职业军队的典范（「嗟乎，此真将军矣」），也显示文帝时中央以京师三营镇抚天下的布防思路。","figures":["周亚夫","文帝刘恒","刘礼","徐厉"],"place":"细柳、霸上、棘门（今陕西咸阳、西安东）","state":"西汉","sources":["《史记·绛侯周勃世家》","《汉书·匈奴传》"],"tags":["细柳营","军礼","京师防务"]},"related":["cn--b166--m01"]},
  {"id":"cn--b157--p01","track":"cn","year":-157,"yearApprox":false,"dim":"politics","weight":2,"title":"文帝崩景帝即位","summary":"遗诏三日而葬、霸陵因山不封，太子启立。","detail":{"background":"文帝在位二十三年（前179—前157），「身衣弋绨、所幸慎夫人衣不曳地」，以节俭宽省著称。","process":"前157年（后元七年）六月文帝崩，遗诏令天下服三日而释、毋禁嫁娶祠祀饮酒食肉，治霸陵皆以瓦器、不用金银铜锡为饰，因山为藏不复封土；太子刘启即位是为景帝，前156年罢卫将军军，太仆诸苑马以赐贫民。","impact":"「文景之治」在这一交接中完成了积累（户口滋息、国库充盈），但也把削藩、币制与诸侯王这三项未了的难题交给景帝。","figures":["文帝刘恒","景帝刘启","张武","周亚夫"],"place":"长安、霸陵（今陕西西安东北）","state":"西汉","sources":["《史记·孝文本纪》","《汉书·文帝纪》"],"tags":["文帝崩","霸陵薄葬","景帝即位"]},"related":["cn--b178--e01"]},
  {"id":"cn--b156--e01","track":"cn","year":-156,"yearApprox":false,"dim":"economy","weight":2,"title":"景帝诏劝农桑省赋役","summary":"元年五月诏郡国务农桑，勿收田租之半。","detail":{"background":"文帝末「民半而饥寒不作」，关东连年水旱，新即位之朝廷以务本为急。","process":"前156年（景帝元年）五月诏「农，天下之本也；其令郡国务劝农桑，益种树，可得衣食物」，又诏「吏以货赂为市、渔夺百姓者，郡守深责」，并「令民得卖爵」以振贫乏。","impact":"景帝延续文帝的轻赋政策，「三十税一」在这一时期基本确立为定制，为七国之乱后武帝时代的财政扩张留下空间。","figures":["景帝刘启"],"place":"长安及各郡国（今陕西、关东）","state":"西汉","sources":["《汉书·景帝纪》","《史记·平准书》"],"tags":["劝农","轻赋","文景之治"]},"related":["cn--b157--p01"]},
  {"id":"cn--b155--p01","track":"cn","year":-155,"yearApprox":false,"dim":"politics","weight":3,"title":"晁错请削吴藩","summary":"请削吴会稽、东海郡，以「先削强藩」定策。","detail":{"background":"吴王濞以「病不朝」被削，「即山铸钱、煮海水为盐」，诱天下豪桀，反状日显。","process":"前155年御史大夫晁错「令人削支郡」，因吴太子之怨请收其会稽、东海郡，楚以臧请削东海，赵请削常山，胶西以请削六县，「诸侯不胜其愤，唯削为辞」，奏可三月而吴反。","impact":"以削藩强行推进中央集权，代价是三年之内一场几乎危及京师的战争；景帝以「错本数端，吴楚为乱」归罪，错遂为替罪。","figures":["晁错","景帝刘启","吴王刘濞","袁盎"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《史记·吴王濞列传》","《汉书·晁错传》"],"tags":["削藩","吴王濞","晁错"]},"related":["cn--b164--p01"]},
  {"id":"cn--b154--m01","track":"cn","year":-154,"yearApprox":false,"dim":"military","weight":5,"title":"吴楚七国之乱","summary":"七国以「诛晁错、清君侧」西向，太尉周亚夫三月平之。","detail":{"background":"前155年起削藩连及吴、楚、赵、胶西、胶东、淄川、济南，吴王濞「即山铸钱煮海为盐」，纠合六国。","process":"前154年正月吴楚反书至，景帝遣太尉周亚夫将三十六将军北击吴楚、大将军窦婴屯荥阳；吴急攻梁睢阳，梁王坚守，亚夫以「梁委之」之策坚壁昌邑，使轻兵绝其淮泗粮道；吴兵饥，正月相持三月余而溃，濞亡走江南，被杀于东越。","impact":"诸侯王的军事独立性从此终结，前145年「令诸侯王不得复治国」使王国沦为食邑，郡县制中央集权在帝国内部真正完成。","figures":["周亚夫","吴王刘濞","楚王刘戊","梁孝王刘武","窦婴"],"place":"荥阳、睢阳、昌邑（今河南荥阳、商丘）","state":"西汉","sources":["《史记·吴王濞列传》","《史记·绛侯周勃世家》","《汉书·景帝纪》"],"tags":["七国之乱","平叛","中央集权"]},"related":["cn--b155--p01"]},
  {"id":"cn--b154--p01","track":"cn","year":-154,"yearApprox":false,"dim":"politics","weight":3,"title":"杀晁错而兵不解","summary":"帝与袁盎谋，朝错东市，使吴楚罢兵，事不成。","detail":{"background":"七国以「请诛贼臣错，已而罢兵」为口号，景帝欲以外交手段换取时间，窦婴、袁盎与错素有隙。","process":"前154年三月，袁盎说景帝「独斩错，发使赦吴楚七国，复其故地，则兵可无血刃而俱罢」；帝乃使中尉召错，「绐载行市」，错朝服被斩于东市，遣袁盎持诏告吴。濞已称「我已为东帝」，尚戏而拜诏；盎被劫持，逃归。","impact":"以牺牲政策设计者换取妥协的失败，成为后世君臣讨论「削藩不可中悔、谋臣不可为饵」的经典教训；汉廷此后坚持武力解决。","figures":["晁错","景帝刘启","袁盎","吴王刘濞"],"place":"长安东市（今陕西西安东北）","state":"西汉","sources":["《史记·袁盎晁错列传》","《史记·吴王濞列传》","《汉书·景帝纪》"],"tags":["晁错之死","东市","政治牺牲"]},"related":["cn--b154--m01"]},
  {"id":"cn--b150--c01","track":"cn","year":-150,"yearApprox":true,"dim":"culture","weight":3,"title":"黄老之治与黄帝四经","summary":"曹参以治道贵清静，文景之际黄老为显学。","detail":{"background":"齐人盖公以「治道贵清静而民自定」说曹参，曹参相齐、相汉皆从其言。","process":"前189至前141年间，「孝文本黄老」，窦太后「好黄帝老子言，帝及太子诸窦不得不读黄帝老子，尊其术」；马王堆三号墓（前168年葬）出土帛书《经法》《十六经》《称》《道原》，学界称为《黄帝四经》。","impact":"黄老之学提供了「轻徭薄赋、约法省刑」的哲学根据，是文景之治的思想底色；其在武帝时被儒术取代，构成汉代言论政策最大的一次转折。","figures":["曹参","盖公","窦太后","文帝刘恒"],"place":"齐国临淄、长安（今山东淄博、陕西西安）","state":"西汉","sources":["《史记·曹相国世家》","《史记·外戚世家》","马王堆汉墓帛书整理小组《经法》"],"tags":["黄老之学","无为而治","马王堆"]},"related":["cn--b178--e01"]},
  {"id":"cn--b145--i01","track":"cn","year":-145,"yearApprox":false,"dim":"institution","weight":4,"title":"令诸侯王不得复治国","summary":"中五年王不得理其国，汉为置吏，减其官属。","detail":{"background":"七国之乱平定后诸王反侧未定，前154年已「夺诸侯吏，诸侯王不得复专国政」，前145年再立法制之。","process":"前145年（景帝中五年）令「诸侯王不复治国，汉为置吏」，以国相当郡太守、秩二千石掌众事，王国丞相改称相、御史大夫改内史，郎中令以下吏皆由朝廷任免，又定「诸侯王朝礼」与私献之禁。","impact":"王国由半独立政权降为「食邑于国、行政属汉」的行政区，郡县制在形式与实质上统一，是推恩令得以顺利施行的制度前提。","figures":["景帝刘启","武帝刘彻"],"place":"长安与各王国（今关中与关东）","state":"西汉","sources":["《汉书·百官公卿表》","《史记·汉兴以来诸侯王年表》","《汉书·景帝纪》"],"tags":["王国官制","中央集权","景帝"]},"related":["cn--b154--m01"]},
  {"id":"cn--b141--p01","track":"cn","year":-141,"yearApprox":false,"dim":"politics","weight":3,"title":"武帝即位建元改元","summary":"十六岁即皇帝位，明年改建元，首开年号之制。","detail":{"background":"前150年栗姬失宠、胶东王彻以长公主之谋立为皇太子；前141年正月景帝崩，太子即位。","process":"前141年二月武帝即位于未央宫，年十六；六月「诏丞相、御史、列侯、中二千石、二千石、郡国举贤良方正能直言极谏之士」；前140年正月以「建元」纪年，是中国历史上第一个正式年号，前135年窦太后崩后得以自由施展。","impact":"年号制度此后沿用到清（1911年）；建元之政（明堂、襃博、逐窦太尉）虽为窦氏所阻，却宣示了从黄老到儒术的政策转向。","figures":["武帝刘彻","田蚡","窦太后","卫绾"],"place":"长安未央宫（今陕西西安西北）","state":"西汉","sources":["《汉书·武帝纪》","《史记·封禅书》","《中国历史纪年表》"],"tags":["汉武帝","年号","建元"]},"related":["cn--b157--p01"]},
  {"id":"cn--b139--c01","track":"cn","year":-139,"yearApprox":false,"dim":"culture","weight":2,"title":"淮南王刘安献内篇","summary":"入朝献所作《内篇》，儒道杂陈，武帝爱密之。","detail":{"background":"刘安为高祖之孙，都寿春，招致宾客方术数千人，「旦暮饭宾客」，招致宾客方术之士数千人，与苏飞、李尚、左吴、田由、雷被、伍被、晋昌八人号八公。","process":"约前139年（建元二年）刘安入朝，献所作《内篇》凡二十一篇，号《淮南子》，以道为宗、兼采儒法名阴阳，「上爱密之」；其书存《原道》《俶真》《天文》《地形》《时则》诸篇。","impact":"《淮南子》是汉代第一部体系性子书，保存了大量先秦天文、地理与神话材料；两年后刘安以谋反狱死，其宾客集团随之瓦解。","figures":["刘安","武帝刘彻","苏飞","伍被"],"place":"寿春、长安（今安徽寿县、陕西西安）","state":"西汉","sources":["《史记·淮南衡山列传》","《汉书·淮南王传》","《淮南子·要略》"],"tags":["淮南子","黄老","诸侯养士"]},"related":["cn--b150--c01"]},
  {"id":"cn--b138--x01","track":"cn","year":-138,"yearApprox":false,"dim":"explore","weight":5,"title":"张骞应募西使月氏","summary":"以郎应募使月氏，经匈奴被留十余年乃得西。","detail":{"background":"汉降者言「匈奴破月氏王，以其头为饮器，月氏常怨匈奴而无与报者」，武帝募能使者。","process":"前138年汉中人张骞以郎应募，与堂邑氏胡奴甘父俱出陇西，为匈奴所得，「留骞十余岁，予妻有子」；骞持汉节不失，得脱西行，经大宛、康居至大月氏，因月氏「地肥饶无寇」不肯东报。","impact":"此行虽未成军事同盟，却第一次把中亚的地理、物产与政治情报带回汉朝，司马迁称「凿空」，是丝绸之路开辟的起点。","figures":["张骞","堂邑甘父","武帝刘彻"],"place":"陇西—大月氏（今甘肃临洮至阿姆河流域）","state":"西汉","sources":["《史记·大宛列传》","《汉书·张骞传》"],"tags":["张骞","凿空","丝路"]},"related":["cn--b126--x01"]},
  {"id":"cn--b138--m01","track":"cn","year":-138,"yearApprox":false,"dim":"military","weight":2,"title":"东瓯内徙江淮","summary":"闽越围东瓯，汉浮海救之，东瓯请举国徙中国。","detail":{"background":"建元三年闽越发兵围东瓯，东瓯食尽告急，太尉田蚡以为「越人相攻击，固其常」不必往救。","process":"前138年武帝从庄助「天子方欲讨之」之议，遣会稽郡「浮江下海」救之；汉兵未至，闽越已引去，东瓯「愿举国徙中国」，乃率众四万余人来朝，处之江淮之间。","impact":"东南百越之地开始大规模内迁，会稽至闽越的海岸线第一次进入汉朝军事视野，为元鼎年间平定两越准备了条件。","figures":["庄助","田蚡","武帝刘彻","东瓯王望"],"place":"东瓯、江淮（今浙江温州、苏北皖中）","state":"西汉","sources":["《史记·东越列传》","《汉书·武帝纪》"],"tags":["东瓯","闽越","内徙"]},"related":["cn--b111--i01"]},
  {"id":"cn--b136--i01","track":"cn","year":-136,"yearApprox":false,"dim":"institution","weight":4,"title":"初置五经博士","summary":"建元五年罢治申韩苏张言者，专置五经博士。","detail":{"background":"建元元年卫绾奏「所举贤良或治申、商、韩非、苏秦、张仪之言，乱国政，请皆罢」；文帝所置《诗》《书》及百家传记博士待续调整。","process":"前136年（建元五年）「初置五经博士」，《易》施、《书》欧阳、《诗》鲁齐韩、《礼》后、《春秋》公羊各立博士，「罢不用五经之博士者」，学官自此以经术为限。","impact":"经学取得官方学术与选官的垄断地位，博士弟子员制（前124）与太学由此而来，「世儒吏治」的格局延续至清末。","figures":["武帝刘彻","卫绾","田蚡"],"place":"长安太常官学（今陕西西安西北）","state":"西汉","sources":["《汉书·武帝纪》","《汉书·儒林传》"],"tags":["五经博士","经学","官学"]},"related":[]},
  {"id":"cn--b134--c01","track":"cn","year":-134,"yearApprox":false,"dim":"culture","weight":5,"title":"天人三策与推明孔氏","summary":"董仲舒对策，请「诸不在六艺之科者皆绝其道」。","detail":{"background":"元光元年诏贤良，「今子大夫睎然，朕甚嘉之」，对策者以百数；赵人董仲舒、齐人公孙弘并起。","process":"前134年（元光元年）董仲舒以《举贤良对策》三问三对，提出「道之大原出于天，天不变，道亦不变」，「诸不在六艺之科、孔子之术者，皆绝其道，勿使并进」，又论「更化」与德教、限民名田、去奴婢、除专杀。","impact":"儒学由百家之一变为国家意识形态，「独尊儒术」的说法后世成为两千年政治文化的基石；其「更化」论也构成对黄老旧政的正式废止。","figures":["董仲舒","公孙弘","武帝刘彻"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《汉书·董仲舒传》","《资治通鉴·汉纪九》"],"tags":["独尊儒术","天人感应","对策"]},"related":["cn--b136--i01"]},
  {"id":"cn--b134--i01","track":"cn","year":-134,"yearApprox":false,"dim":"institution","weight":4,"title":"初令郡国举孝廉","summary":"元光元年令郡国口二十万率一人，岁举孝廉。","detail":{"background":"前140年、前135年屡诏举贤良方正，然「有司不复举行」，元光初以郡国岁举为常科。","process":"前134年（元光元年）十一月「初令郡国举孝廉各一人」，「二十万率一人」，不举者有坐（「不举孝，不奉诏，当以不敬论；不察廉，不胜任也，当免」）；岁举成为定制，与特诏贤良、明经、茂才并行。","impact":"选官之权由军功、赀选转向道德与才学的考察，士人家族由此累积「门生故吏」关系，是东汉门阀与九品官人法的历史源头。","figures":["武帝刘彻","公孙弘"],"place":"长安及各郡国","state":"西汉","sources":["《汉书·武帝纪》","《汉书·黄霸传》","《通典·选举典》"],"tags":["察举","孝廉","选官制度"]},"related":["cn--b134--c01", "cn--b136--i01"]},
  {"id":"cn--b133--m01","track":"cn","year":-133,"yearApprox":false,"dim":"military","weight":3,"title":"马邑之谋不成与和亲绝","summary":"王恢韩安国伏兵三十万于马邑，单于觉而引去。","detail":{"background":"雁门马邑豪聂壹因大行王恢言「匈奴初和亲，亲信边，可诱以利致之，伏兵袭击，必破之道也」。","process":"前133年汉诈斩死囚头马邑北门，聂壹绐单于，「尉史」告变，汉伏车骑材官三十余万于旁，单于觉，引兵而去；王恢以三万辎重不敢击，下廷尉，「闻单于既去，乃自杀」；自是「匈奴绝和亲，攻当路塞，往往入盗于边」。","impact":"四十年和亲政策由此终结，汉朝转入主动攻势，边患却因此加剧；「马邑之谋」成为古代诱敌伏击未成的典型教训。","figures":["王恢","韩安国","聂壹","武帝刘彻"],"place":"马邑（今山西朔州）","state":"西汉","sources":["《史记·韩长孺列传》","《汉书·匈奴传》"],"tags":["马邑之谋","和亲断绝","伏击"]},"related":["cn--b138--x01"]},
  {"id":"cn--b132--d01","track":"cn","year":-132,"yearApprox":false,"dim":"disaster","weight":4,"title":"黄河决瓠子东泛十六郡","summary":"东决瓠子，东南注巨野，通淮泗，二十余年不治。","detail":{"background":"前168年酸枣之决未塞其源，元封前二十余年河复南徙；时「丞相田蚡奉邑在鄢、魏，言河徙乃天意，不可塞」。","process":"前132年（元光三年）「河水复决瓠子，东南注巨野，并淮泗」，「梁楚之时尤被其害」，「岁比不登，郡国颇困」；武帝方事匈奴、河渠，「二十岁而瓠子不决」，至前109年始自临决河。","impact":"这次长达二十余年的决口是武帝一朝最大的环境灾难之一，造成关东粮道与人口损失，也引出武帝《瓠子歌》与瓠子堵口的历史事件。","figures":["田蚡","武帝刘彻","汲黯"],"place":"瓠子、巨野泽（今河南濮阳、山东巨野）","state":"西汉","sources":["《史记·河渠书》","《汉书·沟洫志》","《汉书·武帝纪》"],"tags":["黄河决口","瓠子","河患"]},"related":["cn--b168--d01"]},
  {"id":"cn--b130--c01","track":"cn","year":-130,"yearApprox":false,"dim":"culture","weight":2,"title":"公羊春秋与春秋繁露","summary":"董仲舒以《公羊》决事，著书八十二篇号繁露。","detail":{"background":"《春秋》公羊先师董仲舒「下帷讲诵，三年不窥园」，《汉书》载其书八十二篇。","process":"约前130年前后仲舒退居著述，以《公羊》义例断汉事，「春秋决狱」二百三十二事，其学说后辑为《春秋繁露》，论天人、阴阳、名分、「经权」、贵贱同井诸义。","impact":"公羊学成为两汉最盛的经学流派，「以经决狱」把儒家经义引入司法，也埋下东汉末谶纬化的根苗。","figures":["董仲舒","司马迁","儿宽"],"place":"广川、长安（今河北故城、陕西西安）","state":"西汉","sources":["《汉书·董仲舒传》","《春秋繁露》","《后汉书·应劭传》"],"tags":["公羊学","春秋繁露","以经决狱"]},"related":["cn--b134--c01"]},
  {"id":"cn--b129--m01","track":"cn","year":-129,"yearApprox":false,"dim":"military","weight":3,"title":"四将军分道出塞至龙城","summary":"车骑将军卫青出上谷直至龙城，斩获首功。","detail":{"background":"马邑之谋后匈奴数入代、雁门，元光六年汉「遣卫尉李息为护军」，四将军分道出击。","process":"前129年（元光六年）公孙敖出北地、公孙贺出代、李广出雁门皆败，唯「车骑将军青出上谷至龙城，斩首七百级」，赐爵关内侯；自是卫青日以亲贵为大将军，三子俱封侯。","impact":"汉军第一次以骑兵集团深入漠南取得战果，名将卫青出身奴隶而登大将，标志武帝以「军功—外戚」重组军权的方式。","figures":["卫青","李广","公孙敖","武帝刘彻"],"place":"上谷、龙城（今河北怀来至蒙古鄂尔浑河）","state":"西汉","sources":["《史记·卫将军骠骑列传》","《汉书·武帝纪》"],"tags":["龙城之战","骑兵","卫青"]},"related":["cn--b133--m01"]},
  {"id":"cn--b129--s01","track":"cn","year":-129,"yearApprox":false,"dim":"science","weight":3,"title":"齐人徐伯凿漕渠","summary":"令齐郡船六岁，漕关东粟四百万入关，水衡治渠。","detail":{"background":"「山东上河都漕致长安」，旧自崤黾「三百里而运」，道险难，「一岁不得通」。","process":"前129年（元光六年）齐人徐伯等奏请「令齐郡船六岁、关东漕粟四百万石」，发卒数万人「作漕渠，三年而成」，「引渭入河，起杜里至郑，沿溯三百里」，且田且漕，「漕从是亦大利」。","impact":"漕渠与后来之成国、六辅等渠，使关中渠系密如蛛网，「关中之饶」支撑了对匈奴长期用兵，也是中国最早以国家工程解决漕运的案例。","figures":["徐伯","武帝刘彻","东郭咸阳"],"place":"长安至河、渭（今陕西西安、大荔）","state":"西汉","sources":["《史记·河渠书》","《汉书·沟洫志》"],"tags":["漕运","水利","关中"]},"related":["cn--b132--d01"]},
  {"id":"cn--b127--m01","track":"cn","year":-127,"yearApprox":false,"dim":"military","weight":4,"title":"卫青略取河南地","summary":"将军卫青出云中，至于陇，收秦河南地。","detail":{"background":"河南地为蒙恬所取、秦末复失，「匈奴贤王居之」，距长安近，为北边最大威胁。","process":"前127年（元朔二年）卫青出云中西至陇西，「击破匈奴白羊王、楼烦王」，「斩首数千级而获牛马羊百余万」，遂有河南地；匈奴失之「悲歌：亡我祁连山，使我六畜不蕃息」（此为河西事）。","impact":"汉朝把国界推到黄河一线，解除了对长安的侧背威胁，朔方、五原自此屯田置郡，成为此后北伐的前进基地。","figures":["卫青","李息","武帝刘彻"],"place":"云中以西至陇西、河南地（今内蒙河套）","state":"西汉","sources":["《史记·卫将军骠骑列传》","《汉书·匈奴传》"],"tags":["河南地","朔方","北伐"]},"related":["cn--b127--i01"]},
  {"id":"cn--b127--i01","track":"cn","year":-127,"yearApprox":false,"dim":"institution","weight":3,"title":"置朔方五原郡徙民实之","summary":"收河南地，筑朔方城，置郡徙民十余万口。","detail":{"background":"主父偃上疏盛言「朔方土地肥饶，外有黄河为固，内省转漕之费」，「罢筑朔方，以赈穷困」。","process":"前127年起「筑朔方城，复缮秦时蒙恬所塞障，因河为塞」，置朔方、五原郡；元狩间「徙郡国豪民及有罪者以实之」，「募民徙朔方十万口」，转漕仰关东。","impact":"以郡县—屯田—移民三事并行为经边定式，后世唐代朔方节度与明代套鲁之议皆以此为源；其漕运负担也暴露了边郡不可自给的结构问题。","figures":["主父偃","公孙敖","武帝刘彻"],"place":"朔方、五原（今内蒙古乌拉特前旗、包头）","state":"西汉","sources":["《史记·平津侯主父列传》","《汉书·地理志》","《汉书·武帝纪》"],"tags":["朔方郡","移民实边","边郡"]},"related":["cn--b167--e01", "cn--b127--m01"]},
  {"id":"cn--b127--i02","track":"cn","year":-127,"yearApprox":false,"dim":"institution","weight":5,"title":"推恩令","summary":"令诸侯王分食邑以推恩子弟，不必削而国自分。","detail":{"background":"前154年后诸侯王已不得治国，然国大者「连数十城」，贾谊、主父偃前后请「众建而少其力」。","process":"前127年（元朔二年）用主父偃议，「诸侯王或欲推私恩分子弟邑，莫能至者」，诏「诸侯王私慕天子之德，欲分邑以侯子弟，有司勿拥蔽，令得以户邑封」，是为推恩令；齐国分为七、淮南分为三，列侯属汉郡。","impact":"以「推恩」之名行「分国」之实，不费一兵而使藩国愈分愈小，是中国制度史上最成功的削藩设计，王国问题自此消解。","figures":["主父偃","武帝刘彻","贾谊"],"place":"长安及各王国","state":"西汉","sources":["《汉书·武帝纪》","《史记·汉兴以来诸侯王年表》","《汉书·中山靖王传》"],"tags":["推恩令","削藩","中央集权"]},"related":["cn--b164--p01", "cn--b145--i01"]},
  {"id":"cn--b127--p01","track":"cn","year":-127,"yearApprox":false,"dim":"politics","weight":2,"title":"主父偃以罪族齐王后诛","summary":"偃既折齐王，齐王自杀，公孙弘奏其离宗族，族之。","detail":{"background":"偃为齐相，「发齐王与姊奸事」，齐王自杀，武帝欲不罪偃。","process":"前127年齐王之狱成，「狱案」胶西王亦以事闻，丞相弘奏「偃身无行，以诸侯王之乱为始，虽亡汉，不可不尽法」，遂族偃；偃初为布衣，「北游燕赵，南游齐，六十余岁乃得进」。","impact":"以「首恶」归罪建议者的做法与晁错之死如出一辙，显示武帝朝大臣之进退无常，士人「朝为布衣、夕为卿相」与「族诛」同时存在。","figures":["主父偃","公孙弘","齐厉王"],"place":"长安、临淄（今陕西西安、山东淄博）","state":"西汉","sources":["《史记·平津侯主父列传》","《汉书·公孙弘传》"],"tags":["主父偃","族诛","酷吏政治"]},"related":["cn--b127--i02"]},
  {"id":"cn--b126--x01","track":"cn","year":-126,"yearApprox":false,"dim":"explore","weight":4,"title":"张骞归国号博望侯","summary":"十三年间两遭拘留，元朔三年与甘父还汉。","detail":{"background":"骞去汉十三年，「身所至者大宛、康居、大月氏、大夏」，具为武帝道之。","process":"前126年（元朔三年）张骞与堂邑甘父俱归，「拜为博望侯」，为郎中；所具言「大宛之迹、条枝、安息、身毒」诸国风土，司马迁采为《大宛列传》；同年因与李广俱出右北平失期当斩，赎为庶人。","impact":"中亚的地理、物产与兵势首次系统进入中国知识，汉廷据此确立「断匈奴右臂」的西向战略，史源即其口述。","figures":["张骞","堂邑甘父","武帝刘彻"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《史记·大宛列传》","《汉书·张骞李广利传》"],"tags":["张骞归","西域情报","凿空"]},"related":["cn--b138--x01"]},
  {"id":"cn--b125--c01","track":"cn","year":-125,"yearApprox":true,"dim":"culture","weight":2,"title":"银雀山汉简抄本群书","summary":"临沂汉墓出土《孙子兵法》《孙膑兵法》竹简。","detail":{"background":"山东临沂金雀山、银雀山一号汉墓约武帝前期（前140—前118）所葬，墓主或为下级官吏。","process":"1972年发掘银雀山一、二号汉墓，出土竹简约4900余枚，含《孙子兵法》《孙膑兵法》《六韬》《尉缭子》《管子》《守法守令十三篇》与历谱、阴阳时令等。","impact":"《孙膑兵法》的重见解决了「孙武孙膑一人一书」的千年疑案，也是先秦兵学与法律文本抄本形态最重要的实物证据。","figures":["银雀山一号墓墓主"],"place":"临沂（今山东临沂银雀山）","state":"西汉","sources":["《银雀山汉墓竹简》壹至叁（文物出版社）","《史记·孙子吴起列传》"],"tags":["出土文献","竹简","兵书"]},"related":["cn--b195--i01"]},
  {"id":"cn--b124--i01","track":"cn","year":-124,"yearApprox":false,"dim":"institution","weight":4,"title":"立太学与博士弟子员","summary":"为博士官置弟子五十人，复其身，课试补郎吏。","detail":{"background":"公孙弘与太常「因前博士故员」请「为博士官置弟子五十人」，「有缺，择其便辟者补之」。","process":"前124年（元朔五年）立太学于长安城南，博士弟子五十人「复其身」，「岁课甲科四十人为郎中、乙科二十人为太子舍人」，不通五经者罢；昭帝时增百人，宣帝千二百人，元帝三千人，成帝万人。","impact":"中国有了第一所国家最高学府与以考试定去取的官学制度，士人「射策观于周室」，儒生入仕成为汉代政治主流。","figures":["公孙弘","武帝刘彻"],"place":"长安城南太学（今陕西西安西北）","state":"西汉","sources":["《汉书·儒林传》","《汉书·武帝纪》","《三辅黄图》"],"tags":["太学","博士弟子","教育制度"]},"related":["cn--b136--i01", "cn--b134--i01"]},
  {"id":"cn--b122--i01","track":"cn","year":-122,"yearApprox":false,"dim":"institution","weight":3,"title":"左官律与附益之法","summary":"为左官律、附益法，诸侯王不得复与朝士交通。","detail":{"background":"淮南、衡山二王谋反狱起（前122）之后，武帝「惧诸侯王之党与渐盛」，乃立法以绝其羽翼。","process":"前122年前后（元狩元年狱成后）定「左官律」（诸侯王官属「位在汉廷左」，不得入仕中央）与「附益法」（「阿党诸侯、附益其不法者，重法以绳之」），又「限诸侯王朝请」；淮南王安、衡山王赐皆自杀，党与死者数万人。","impact":"从法律上隔绝了诸侯与士人的结合，切断了分裂势力的人才来源；「左迁」一词由此而来，可见其用语影响之深。","figures":["武帝刘彻","张汤","淮南王刘安"],"place":"长安（今陕西西安西北）","state":"西汉","sources":["《汉书·诸侯王表序》","《史记·淮南衡山列传》","《汉书·主父偃传》"],"tags":["左官律","附益法","淮南狱"]},"related":["cn--b127--i02", "cn--b139--c01"]},
  {"id":"cn--b122--x01","track":"cn","year":-122,"yearApprox":false,"dim":"explore","weight":3,"title":"间出西羌求身毒道","summary":"骞言可在蜀身毒，帝因间出西羌，至滇为吏所闭。","detail":{"background":"张骞在大夏见「邛竹杖、蜀布」，问之曰「吾贾人从身毒市之」，身毒「在大夏东南可数千里」。","process":"前122年骞以校尉建议「从蜀郡出身毒，便近无寇」，武帝乃令「王然于、柏始昌、吕越人等间出西羌」求身毒道，至滇越，「滇王尝羌留之岁余」，为昆明所阻而返，遂有求通印、缅甸之道第一次官方探查。","impact":"这是中原王朝最早对西南国际商道的官方勘察，直接促成元封二年降滇置益州郡，也印证了早在官方使节之前已有民间蜀身毒贸易。","figures":["张骞","王然于","滇王尝羌","武帝刘彻"],"place":"蜀郡至滇、昆明（今四川至云南）","state":"西汉","sources":["《史记·大宛列传》","《汉书·西南夷传》"],"tags":["身毒道","西南夷","商路"]},"related":["cn--b126--x01"]},
  {"id":"cn--b121--m01","track":"cn","year":-121,"yearApprox":false,"dim":"military","weight":4,"title":"霍去病两出河西","summary":"春出陇西过焉支，夏逾居至祁连，斩首八千余。","detail":{"background":"前123年后汉以霍去病为骠骑将军，「匈奴未灭，何以家为」，专任河西之役。","process":"前121年（元狩二年）春去病将万骑出陇西，「逾乌、援狐阼，得休屠王祭天金人」；夏再出陇西北，逾居延，至祁连山，斩首八千余级，「匈奴歌曰：失我祁连山，使我六畜不蕃息；失我焉支山，使我嫁妇无颜色」。","impact":"汉朝由此取得河西走廊，祁连山马场与焉支山牧场归汉，「断匈奴右臂」的战略第一步完成，匈奴在西北的统治开始瓦解。","figures":["霍去病","武帝刘彻","公孙敖"],"place":"陇西、居延、祁连山（今甘肃河西）","state":"西汉","sources":["《史记·卫将军骠骑列传》","《汉书·霍去病传》"],"tags":["河西之战","霍去病","祁连山"]},"related":["cn--b127--m01"]},
  {"id":"cn--b121--p01","track":"cn","year":-121,"yearApprox":false,"dim":"politics","weight":4,"title":"浑邪王杀日逐王降汉","summary":"秋浑邪、日逐谋降，日逐悔，浑邪杀之，将众来奔。","detail":{"background":"去病两出河西，匈奴「混邪王、休屠王地」损失最重，单于欲诛之，二王惧而谋降汉。","process":"前121年秋，浑邪王杀日逐王，并将其众，遣使请降；汉「遣骠骑将三百骑迎之」，浑邪众「十余万，真可击者数万」，临河多有逃者，遂斩「欲降汉之乱」，「既至，号其王为漯阴侯」，余众分处陇西、北地、上郡、朔方、云中五郡塞外为五属国。","impact":"河西自此无王庭势力，汉以属国安置降众、取其精骑为兵，「金城、西河至武威」的降众体系成为两汉胡汉杂处的开端。","figures":["浑邪王","休屠王","霍去病","武帝刘彻"],"place":"黄河、五属国（今内蒙河套至陇东）","state":"西汉","sources":["《史记·匈奴列传》","《汉书·武帝纪》","《汉书·卫青霍去病传》"],"tags":["浑邪王降","属国","匈奴"]},"related":["cn--b121--m01"]},
  {"id":"cn--b119--i01","track":"cn","year":-119,"yearApprox":false,"dim":"institution","weight":4,"title":"置武威酒泉郡列河西四郡","summary":"浑邪王地空，汉置武威、酒泉，后分张掖、敦煌。","detail":{"background":"河西既无匈奴，「空地方」，汉「初置张掖、酒泉郡」而徙民实之，与「列四郡、据两关」之策相为表里。","process":"前119年（元狩四年）徙民置武威、酒泉二郡，元鼎六年（前111）分置张掖、敦煌，「玉门、阳关」为其门户，又屯田、置都尉、驿置，「初通西域，列四郡、两关据之」。","impact":"河西四郡成为中原通往西域的行政与军事基地，「张国臂掖」使丝路得以维持两千年，也奠定了甘肃的行政格局。","figures":["武帝刘彻"],"place":"武威、酒泉、张掖、敦煌（今甘肃河西走廊）","state":"西汉","sources":["《汉书·地理志》","《史记·平津侯主父列传》","悬泉置汉简"],"tags":["河西四郡","玉门关","屯田"]},"related":["cn--b121--p01"]},
  {"id":"cn--b119--e01","track":"cn","year":-119,"yearApprox":false,"dim":"economy","weight":5,"title":"盐铁官营","summary":"以东郭咸阳、孔仅为大农丞，笼盐铁于县官。","detail":{"background":"「县官之费不肯省，用不足」，而「山东遭水灾，民多饥乏，天子遣使虚郡国仓禀」，「于是御史大夫请令大农置盐铁丞」；于是用大农尉康等请「笼盐铁」。","process":"前119年（元狩四年）以盐铁官属大农，「令民得卖爵」，「山，日出租也；海，盐利之也」，请募民「因官器作煮盐，官与牢盆」，于盐铁多郡置「盐官、铁官」，「敢私铸铁器煮盐者，釱左趾，没入其器物」；后桑弘羊领大农，「诸郡国前所置盐铁吏，皆更属大农」，全国设盐官37、铁官48处。","impact":"国家掌握了最重要的两种手工业与财政来源，盐铁利入官而商贾利源断，成为后世两千余年「禁榷」制度的原型；其弊端在昭帝时引发盐铁会议。","figures":["东郭咸阳","孔仅","桑弘羊","武帝刘彻"],"place":"长安与各盐铁郡（全国）","state":"西汉","sources":["《史记·平准书》","《汉书·食货志》","《盐铁论·非鞅》"],"tags":["盐铁官营","禁榷","国家财政"]},"related":["cn--b119--e02"]},
  {"id":"cn--b119--e02","track":"cn","year":-119,"yearApprox":false,"dim":"economy","weight":4,"title":"初算缗钱","summary":"号令民自占商贾车船，率钱二千而算一。","detail":{"background":"「贾人以末苦，非遇水旱之灾，则民不及之；然其富累万金，不佐国家之急」，故有算钱之法。","process":"前119年（元狩四年）「初算缗钱」：商贾「率缗钱二千而算一」，手工业者四千而算一，「诸贾人、末作、贳贷、卖买、居物邑中及有市籍者，虽诸工商，皆有算」；「有敢隐匿，戍边一岁，没其缗钱」。","impact":"这是中国史上第一次全国性的财产（资本）税，直接打击中等以上商人，也迫使资本转向土地，为告缗令与「中家以上大抵皆遇告」的大搜捕铺路。","figures":["武帝刘彻","桑弘羊"],"place":"全国郡国","state":"西汉","sources":["《史记·平准书》","《汉书·食货志》"],"tags":["算缗","财产税","抑商"]},"related":["cn--b114--e01"]},
  {"id":"cn--b119--e03","track":"cn","year":-119,"yearApprox":false,"dim":"economy","weight":3,"title":"造白金三品与皮币","summary":"以银锡为白金三品，禁苑白鹿皮为皮币直四千钱。","detail":{"background":"「少府言：令诸常赋少而用度不足，请诏造银锡为白金」，以「天用莫如龙、地用莫如马、人用莫如龟」为三品文。","process":"前119年「更造白金三品」：龙文直三千、马文直五百、龟文直三百，「皮币」以方尺白鹿皮缘以文绣，直四千钱，「王侯朝享祠堂，不得此皮币不得荐」；「于是荆楚豪强多铸伪钱，不可禁」。","impact":"虚币与强制折价造成物价腾贵与盗铸蜂起，两年后白金废而五铢钱专，是武帝币制改革失败的一页，也是「货币名目论」的早期实验。","figures":["少府有司","武帝刘彻"],"place":"长安及各郡","state":"西汉","sources":["《史记·平准书》","《汉书·食货志》"],"tags":["白金三品","皮币","通货膨胀"]},"related":["cn--b113--e01"]},
  {"id":"cn--b118--f01","track":"cn","year":-118,"yearApprox":false,"dim":"figure","weight":1,"title":"司马相如病免卒","summary":"坐受金使所爱，病免居茂陵，元狩五年卒。","detail":{"background":"相如以《子虚赋》得幸，拜郎中，又上《大人赋》「以示天子仙好仙之意」；后「使略定西南夷」，「受使通西南夷，矫天子之命」，被有司所劾，「岁余，使斯从官谢，乃得解」。","process":"约前125年免官，居茂陵，「家居临邛，与富人程郑游」；前118年前后病免卒，武帝使其所善者求书，「其遗书言封禅」，《汉书》录其赋二十八篇（今存《子虚》《上林》《大人》《长门》《哀二世》）。","impact":"其「合綦组以成文、列锦绣而为质」的大赋体式定型了汉赋两千年范式，「凤求凰」的野史叙事则成为士人婚姻想象的母题。","figures":["司马相如","卓文君","武帝刘彻"],"place":"成都、茂陵（今四川成都、陕西兴平）","state":"西汉","sources":["《史记·司马相如列传》","《汉书·司马相如传》"],"tags":["汉赋","司马相如","茂陵"]},"related":["cn--b122--x01"]},
  {"id":"cn--b117--a01","track":"cn","year":-117,"yearApprox":false,"dim":"art","weight":3,"title":"霍去病墓马踏匈奴石刻","summary":"为骠骑将军起冢象祁连山，墓前置大型石刻群。","detail":{"background":"前117年霍去病卒，年二十四，武帝「为治悼」，「为冢象祁连山」以纪其河西破匈奴之功，谥为景桓侯，发属国玄甲军自长安列阵至茂陵送葬。","process":"墓前以整块花岗岩「循石造型」琢成石刻群：主像《马踏匈奴》为一昂首屹立的战马，腹下压一持弓执矢、面目狰狞的匈奴武士；另有卧马、跃马、石人、卧牛、伏虎、怪兽食羊、人与熊搏等十余件，构成中国现存最早、保存最完整的大型纪念碑性石雕组群。","impact":"这批石刻确立了中国雕塑因势成形、以意为主的写意传统，与后世陵墓神道石刻一脉相承；也是河西之战的实物纪念，现藏陕西茂陵博物馆，为研究西汉军事、雕刻与丧葬制度的第一手材料。","figures":["霍去病","武帝刘彻"],"place":"茂陵东侧（今陕西兴平）","state":"西汉","sources":["《史记·卫将军骠骑列传》","《汉书·霍去病传》","霍去病墓石刻实物"],"tags":["霍去病墓","马踏匈奴","纪念碑石刻"]},"related":["cn--b121--m01"]},
  {"id":"cn--b114--e01","track":"cn","year":-114,"yearApprox":false,"dim":"economy","weight":4,"title":"杨可告缗，中家以上大抵皆遇告","summary":"遣御史杨可主告缗，得民财物以亿数。","detail":{"background":"缗钱令行而「民不奉诏」，「于是作贤缗钱令，令民得自占，犹不能相领」，有司请「益禁铸钱」。","process":"前114年（元鼎三年）使杨可「主告缗」，「告缗遍天下」，「中家以上大抵皆遇告」，「得民财物以亿计，奴婢以千万数，田大县数百顷、小县百余顷，宅亦如之」；商贾「中家以上大率破」，「于是水衡、中都官之财益饶」。","impact":"一次针对民间资本的全面清算，中产商人破产，「民偷甘食好衣，不事畜藏之业」；国家财政危机缓解，但也永久改变了社会对商业资本的态度。","figures":["杨可","武帝刘彻"],"place":"全国郡国","state":"西汉","sources":["《史记·平准书》","《汉书·食货志》"],"tags":["告缗","抑商","财政"]},"related":["cn--b119--e02"]},
  {"id":"cn--b113--e01","track":"cn","year":-113,"yearApprox":false,"dim":"economy","weight":4,"title":"上林三官专铸五铢钱","summary":"悉禁郡国无铸钱，专令上林三官，非三官钱不得行。","detail":{"background":"自文帝放铸以来「吴邓钱布天下」，「郡国多奸铸钱，钱多轻」，而「公卿又请令郡国铸三铢钱」，「吏民之坐盗铸钱死者甚众」。","process":"前113年（元鼎四年）「悉禁郡国无铸钱，专令上林三官铸」（钟官、辨铜、均输），钱文「五铢」，「重如其文」，「非三官钱不得行」，诸郡国所铸钱皆毁销以供铜；「民铸钱者甚鲜，计其费不能相当，唯真工大奸乃盗为之」。","impact":"中国第一次实现货币铸造权与标准的真正统一，五铢钱行用七百余年（至唐武德），是古代世界最成功、最长的货币制度。","figures":["武帝刘彻","桑弘羊"],"place":"上林三官（今陕西西安西南）","state":"西汉","sources":["《汉书·食货志》","《史记·平准书》","西汉五铢钱范实物"],"tags":["五铢钱","货币统一","上林三官"]},"related":[]},
  {"id":"cn--b112--a01","track":"cn","year":-112,"yearApprox":false,"dim":"art","weight":4,"title":"立乐府采诗夜诵","summary":"乃立乐府，采赵代秦楚之讴，李延年为都尉。","detail":{"background":"「至今上即位，作十九章，令侍中李延年次序其声，拜为协律都尉」，又「郊祀歌」需新声。","process":"前112年（元鼎五年）因平乐馆迎神乐，乃「立乐府，采诗夜诵，有赵、代、秦、楚之讴」，以李延年为协律都尉，「多举司马相如等数十人造为诗赋，略论律吕」，「以合八音之调」，作《郊祀歌》十九章。","impact":"乐府使民间歌谣第一次大规模进入国家礼乐与文学，《陌上桑》《战城南》《十五从军征》一类的乐府诗由此上接《诗经》「观风」传统。","figures":["李延年","司马相如","武帝刘彻"],"place":"长安乐府（今陕西西安西北）","state":"西汉","sources":["《汉书·礼乐志》","《乐府诗集》","《史记·乐书》"],"tags":["乐府","采诗","郊祀歌"]},"related":["cn--b113--e01"]},
  {"id":"cn--b112--m01","track":"cn","year":-112,"yearApprox":false,"dim":"military","weight":3,"title":"汉发罪人击南越","summary":"使驰义侯将夜郎兵、楼船将军下沅江，五道俱进。","detail":{"background":"南越丞相吕嘉杀王兴与汉使，反，「请太子婴齐为质」不成，武帝怒，「以卫尉路博德为伏波将军，出桂阳，下汇水」。","process":"前112年秋，以少内张歧为山壁、路博德出桂阳、杨仆出豫章下横浦、驰义侯将巴蜀罪人发夜郎兵下牂柯，五路俱进；「越中震恐」，次年冬仆先至番禺，博德合军，城破，吕嘉、赵建德亡海上被擒。","impact":"南越国九十二年统治结束，汉廷把郡县推行到珠江三角洲与红河平原，两越之地自此长期成为中国直辖疆域。","figures":["路博德","杨仆","吕嘉","武帝刘彻"],"place":"番禺（今广州）","state":"南越","sources":["《史记·南越列传》","《汉书·西南夷两粤朝鲜传》"],"tags":["平南越","楼船","岭南"]},"related":["cn--b111--i01"]},
  {"id":"cn--b111--i01","track":"cn","year":-111,"yearApprox":false,"dim":"institution","weight":4,"title":"平南越置九郡","summary":"以其地儋耳、珠崖、南海、苍梧、玉林、合浦、交趾、九真、日南九郡。","detail":{"background":"元鼎六年冬南越平，「南越已破，遂斩夜郎侯，夷且兰为牂柯郡」，汉之「南诸侯」体系彻底终结。","process":"前111年以其地置儋耳、珠崖、南海、苍梧、玉林、合浦、交趾、九真、日南九郡，「以其王故地」；「自合浦、徐闻缘海得交趾」，「粤地土地湿、暑多病」，「吏率用豪长，治以宽简」；珠崖以「吏侵求」数反，前46年竟弃之。","impact":"九郡之置使中国行政权首次延伸到今越南中部，南海诸郡也开启合浦—徐闻的海上贸易，与「海上丝绸之路」的起点相联系。","figures":["武帝刘彻","路博德"],"place":"番禺、交趾（今广州至越南中部）","state":"西汉","sources":["《汉书·地理志》","《史记·南越列传》"],"tags":["九郡","岭南","海上贸易"]},"related":["cn--b112--m01", "cn--b214--i01"]},
  {"id":"cn--b111--s01","track":"cn","year":-111,"yearApprox":false,"dim":"science","weight":4,"title":"井渠法作龙首渠","summary":"穿洛以溉重泉，凿井井渠相衔，得引水灌溉。","detail":{"background":"「庄熊罴言：临晋民愿穿洛，以溉重泉以东万余顷故卤地」，而渠经渠行沙土地带，「岸善崩」，凿治为难。","process":"前111年前后（元鼎、征和间）发万人「穿渠，自徵引洛至商颜山下」，因「岸善崩，乃凿井，深者四十余丈，往往为井，井下相通行水」，「水颓以绝商颜，东至山岭普谷之闲」，是为「井渠」，即后世新疆坎儿井之原型；「渠成且溉且粪，收至亩一钟」。","impact":"井渠法是中国水利史上罕见的地下引水技术发明，西传中亚、波斯，成为干旱地区灌溉技术的东亚—中亚谱系，「龙首渠」之名沿用至今。","figures":["庄熊罴","有司"],"place":"冯翊、临晋（今陕西大荔、澄城）","state":"西汉","sources":["《史记·河渠书》","《汉书·沟洫志》"],"tags":["井渠法","坎儿井","水利技术"]},"related":[]},
  {"id":"cn--b110--e01","track":"cn","year":-110,"yearApprox":false,"dim":"economy","weight":4,"title":"行均输平准之法","summary":"大农部丞均输于郡国，置平准官贵买贱卖调天下。","detail":{"background":"「自公孙弘后，国用不足」，「而均输令平准都卫之官置矣」；桑弘羊以「算、缗、盐、铁」之余，进一步以「官营物流」取利。","process":"前110年（元封元年）以桑弘羊为治粟都尉、领大农，「尽笼天下盐铁」，行均输法：郡国「以所饶之物当赋，官受而贩之」，「置均输官于郡国」；又「治平准，都内受郡国输物，贵即卖之、贱即买之」，「诸平准皆在长安」。","impact":"均输平准以官府直接经商，既省转输之费又平抑物价，「民不益赋而天下用饶」；这一模式在唐宋（市易、均输）与明代反复被援引与批判。","figures":["桑弘羊","武帝刘彻"],"place":"长安及郡国均输官（全国）","state":"西汉","sources":["《史记·平准书》","《汉书·食货志》","《盐铁论》"],"tags":["均输","平准","国家商业"]},"related":["cn--b119--e01", "cn--b114--e01"]},
  {"id":"cn--b110--m01","track":"cn","year":-110,"yearApprox":false,"dim":"military","weight":3,"title":"勒兵十八万骑北临朔方","summary":"帝亲巡朔方，将十八万骑，使郭吉告单于战。","detail":{"background":"元封元年帝「北巡边」，「行自池阳，上郡、朔方」，「顺之白登」；匈奴自「伊稚单于后数弱」，而汉「既得浑邪，空匈奴右地」。","process":"前110年（元封元年）春「勒兵十八万骑，旌旗径千余里，威震匈奴」，遣郭吉告单于「南面亡匿，何不为汉臣」；单于怒而「拘汉使」，然终不敢应战；西至「令居之设」，又「初开河西、列四郡、两关」。","impact":"这次军事威慑实际确立了汉强匈弱的新均势，汉朝得以从容经营河西与西域，但连年出塞与巡边的开支也埋下了财政与民力的危机。","figures":["武帝刘彻","郭吉"],"place":"朔方、上郡（今内蒙、陕北）","state":"西汉","sources":["《史记·匈奴列传》","《汉书·武帝纪》"],"tags":["巡边","军事威慑","汉强匈弱"]},"related":[]},
  {"id":"cn--b109--s01","track":"cn","year":-109,"yearApprox":false,"dim":"science","weight":3,"title":"武帝自临瓠子塞河决","summary":"天子亲临决河，令将军以下皆负薪，塞瓠子。","detail":{"background":"瓠子自前132年决口后「二十岁而瓠子不决」，河东南注巨野，通淮泗，梁、楚之间尤被其害；丞相田蚡以河徙乃天意、不可塞阻议，山东水旱与漕粮乏绝并至。","process":"前109年（元封二年）四月武帝东巡还，自临决河，沉白马玉璧祭河，令群臣自将军以下皆负薪投堵；时薪尽，「东下淇园之竹以为楗」，征调伐竹为柱桩，终塞决口，其上筑宫，名为宣房。","impact":"二十余年的河患暂告平息，梁、楚故地复得耕业，黄河回归北道；帝王亲临决河、举国负薪塞决自此成为汉代治河常例，水利与漕运正式列为国家常政。","figures":["武帝刘彻","汲仁","郭昌"],"place":"瓠子（今河南濮阳西南）","state":"西汉","sources":["《史记·河渠书》","《汉书·沟洫志》"],"tags":["瓠子堵口","治河","淇园竹楗"]},"related":["cn--b132--d01", "cn--b109--c01"]},
  {"id":"cn--b109--c01","track":"cn","year":-109,"yearApprox":false,"dim":"culture","weight":2,"title":"瓠子歌二首","summary":"塞决时作歌，开中国文学的治水题材。","detail":{"background":"塞决之际君臣负薪，功役艰危，武帝临河既塞，「作歌」自哀河患之久与人功之难。","process":"其辞曰「瓠子决兮将奈何？皓皓旰旰兮闾殚为河」，又叹「佞人给兮，咸云圣人之所不能」；既塞之后歌「宣房封兮天功成，东流之舍兮归故道」，「咄嗟行路难」之叹，与《郊祀歌》新声同时并制。","impact":"这是中国文学史上最早以治水工程为题材、由帝王亲临现场所作的诗章，把《诗经》「劳者歌其事」的传统接到帝国工程现场，也是乐府新体走出庙堂的记录。","figures":["武帝刘彻"],"place":"瓠子（今河南濮阳西南）","state":"西汉","sources":["《史记·河渠书》","《汉书·沟洫志》"],"tags":["瓠子歌","治水文学","宣房"]},"related":["cn--b109--s01", "cn--b112--a01"]},
  {"id":"cn--b109--i01","track":"cn","year":-109,"yearApprox":false,"dim":"institution","weight":3,"title":"滇王降置益州郡","summary":"以滇池为益州郡，赐滇王印，复长其民。","detail":{"background":"汉使求通身毒道为昆明所阻，元封间发罪人击劳深、且兰；将军郭昌兵至，滇王尝羌举国降，「滇小邑，君长以什数」而滇最著。","process":"前109年（元封二年）汉「以滇池为益州郡」，「赐滇王王印，复长其民」，即以其故君仍治其众而隶于汉郡；发蜀地贾人徙居，「复募天下徙民」，置吏收赋。","impact":"滇池区域自此纳入郡县与编户体系，蜀身毒道的南方商路由民间走私转为国家驿道；云南晋宁石寨山六号墓出土的蛇钮金印「滇王之印」与此记载相合，是文献与考古互证的范例。","figures":["武帝刘彻","郭昌","尝羌"],"place":"滇池区域（今云南晋宁）","state":"西汉","sources":["《史记·西南夷列传》","《汉书·武帝纪》","石寨山六号墓金印"],"tags":["益州郡","滇王之印","西南夷"]},"related":["cn--b122--x01"]},
  {"id":"cn--b109--m01","track":"cn","year":-109,"yearApprox":false,"dim":"military","weight":2,"title":"两将军水陆并攻朝鲜","summary":"楼船将军浮海，左将军出辽东，围王险城。","detail":{"background":"卫氏朝鲜阻兵胁服燕、齐、真番诸小国，「绝不得朝请」；汉使涉何渡浿水还，杀朝鲜送将，朝鲜遂发兵距塞汉使。","process":"前109年（元封二年）夏，遣楼船将军杨仆将齐地水军浮渤海击其南，左将军荀彘出辽东击其北，约期会于王险；杨仆军先到，「战败，走入山中」，荀彘攻浿水，两军「更相疑疾」，各持两端，故围城连岁不下。","impact":"此役暴露汉军水陆协同与将帅相争的极限，也把汉朝边防轴线第一次推到黄海与朝鲜半岛；前108年朝鲜贵人杀王右渠降，战役以设郡收场。","figures":["杨仆","荀彘","右渠"],"place":"王险城（今朝鲜平壤）","state":"西汉","sources":["《史记·朝鲜列传》","《汉书·武帝纪》"],"tags":["伐朝鲜","楼船军","王险城"]},"related":["cn--b108--i01"]},
  {"id":"cn--b108--i01","track":"cn","year":-108,"yearApprox":false,"dim":"institution","weight":4,"title":"朝鲜定置汉四郡","summary":"分其地为真番、临屯、乐浪、玄菟四郡。","detail":{"background":"围王险岁余不下，朝鲜相与尼溪参等谋杀王右渠以降；前108年夏汉军入城，「遂定朝鲜」，其人众、土地皆属汉。","process":"「真番、临屯、乐浪、玄菟」四郡置：乐浪郡治朝鲜县（今平壤），玄菟在东北，真番在南，临屯在东；郡下设县，置三老、啬夫，编户齐民如内郡，徙天下奸吏与罪人实之。","impact":"这是中原王朝第一次在朝鲜半岛北部实行郡县统治，乐浪成为汉文化东传枢纽，出土漆器、铜镜、印玺与汉式墓葬；真番、临屯后并入乐浪、玄菟，二郡存至魏晋，是东北亚国际关系的支点。","figures":["武帝刘彻"],"place":"乐浪郡朝鲜县（今朝鲜平壤）","state":"西汉","sources":["《史记·朝鲜列传》","《汉书·地理志》","乐浪汉墓出土器物"],"tags":["汉四郡","乐浪","郡县东传"]},"related":["cn--b109--m01", "cn--b119--i01"]},
  {"id":"cn--b106--i01","track":"cn","year":-106,"yearApprox":false,"dim":"institution","weight":5,"title":"初置十三州部刺史","summary":"武帝初置部刺史，以六条察郡国，秩六百石。","detail":{"background":"郡国近百，守尉众而难察，中央遣使「无常治、无常事」；吏多奸而冤民无所告，诸侯二千石逾制者日多。","process":"前106年（元封五年）「初置部刺史，掌奉诏条察州，秩六百石，员十三人」，分天下为十三州部（三辅等三河不设）；刺史「以六条问事」，一督强宗豪右田宅逾制、以强凌弱，余五条专察二千石不奉诏、侵渔百姓、冤狱苛刻、阿附豪强、子弟请属交通。","impact":"以低秩临高秩、以中央使臣督地方大吏，是中国监察制度的经典设计，「传车周流、无所留止」；但州由监察区渐变为行政区，刺史改州牧后成为东汉末年割据的制度出口。","figures":["武帝刘彻"],"place":"长安及十三州","state":"西汉","sources":["《汉书·百官公卿表》","《后汉书·百官志》刘昭注引《汉官典职》","尹湾汉墓简牍《集簿》"],"tags":["部刺史","六条问事","监察制度"]},"related":["cn--b124--i01", "cn--b106--p01"]},
  {"id":"cn--b106--p01","track":"cn","year":-106,"yearApprox":false,"dim":"politics","weight":4,"title":"泰山封禅号曰元封","summary":"亲登泰山行封礼，因改元，汉家封禅再定。","detail":{"background":"汉兴以来天子益贵神仙，齐人公孙卿等以「黄帝得宝鼎、仙可致」之书进，武帝连年东巡求之；得宝鼎于汾阴、星孛于东方，遂决意封禅。","process":"前106年（元封元年）四月，帝东巡至泰山下，「如郊祠太一之礼」，「封广丈二尺，高九尺，其下则有玉牒书，书秘」；禅于肃然山，「亲拜」明堂于汶上，令诸生荐绅射牛草具，遂以是年为「元封」元年，兼行北巡海上、碣石。","impact":"封禅在秦始皇之后重定为帝国最高典礼，儒术、方士之说与皇权礼制合流，「元封」一般被认为是西汉第一个当时即行的年号；太史公司马谈不得与封事而卒，直接促成司马迁发愤续成《史记》。","figures":["武帝刘彻","祠官宽舒","司马谈"],"place":"泰山（今山东泰安）","state":"西汉","sources":["《史记·封禅书》","《汉书·武帝纪》"],"tags":["封禅","年号","国家祭祀"]},"related":["cn--b106--i01", "cn--b104--s01"]},
  {"id":"cn--b106--x01","track":"cn","year":-106,"yearApprox":false,"dim":"explore","weight":2,"title":"北至单于台巡行塞外","summary":"并海上，北至单于台，亲劳北边戍卒。","detail":{"background":"封禅既毕，武帝「北至」边塞；自元朔置朔方五原以来，长城、亭障、屯田渐成，边郡有积。","process":"一行「东巡海上，至碣石」，转北「越北边，至单于台」，历朔方、五原，亲见戍卒屯田与甲兵储积，「北抚其民」而还；使使者晓谕匈奴，匈奴终不敢近塞。","impact":"这是汉朝皇帝第一次深入燕山至阴山一线，把军事检阅、地理勘察与外交威压合而为一；单于台自此进入中国北部地理记忆，也是汉匈力量消长的象征性坐标。","figures":["武帝刘彻"],"place":"单于台（今内蒙古呼和浩特西北一带）","state":"西汉","sources":["《史记·匈奴列传》","《汉书·武帝纪》"],"tags":["北巡","单于台","边塞巡视"]},"related":["cn--b110--m01", "cn--b127--i01"]},
  {"id":"cn--b104--s01","track":"cn","year":-104,"yearApprox":false,"dim":"science","weight":4,"title":"太初历成以正月为岁首","summary":"正历，以正月为岁首，色上黄，数用五。","detail":{"background":"汉初因秦历，以十月为岁首，「历纪坏废」，朔晦弦望与天象不合；元封间诏征天下治历者，选邓平、唐都、落下闳与待诏二十余人共议。","process":"前104年（太初元年）五月「正历，以正月为岁首，色上黄，数用五，定官名，协音律」；历以八十一分为日法，一月得二十九日八十一分日之奇，首次把二十四节气逐月配属十二月中，以无中气之月置闰，历成而名《太初》。","impact":"中国历法自此由偏重太阴月转向阴阳合历，以正月为岁首沿用两千一百余年，今农历新年即其遗制；太初历行用百余年，虽屡有改历之议，其框架成为后世历法的基本型。","figures":["邓平","落下闳","唐都","倪宽"],"place":"长安","state":"西汉","sources":["《汉书·律历志》","《汉书·武帝纪》","《史记·历书》"],"tags":["太初历","岁首","置闰法"]},"related":["cn--b106--p01", "cn--b104--s02"]},
  {"id":"cn--b104--s02","track":"cn","year":-104,"yearApprox":false,"dim":"science","weight":2,"title":"落下闳营运浑天之学","summary":"巴人落下闳治历考星，浑天之说自此有征。","detail":{"background":"太初改历须以实测为据，「乃诏御史……治历」，天下治历者会于长安，巴郡落下闳以晓天文被征。","process":"《汉书·律历志》称「巴落下闳营运之」，其业在观测天文、推校日月行度、正二十八宿距度；与唐都同测、邓平同算，构成太初历「实测」与「历算」两条分工，历成而后浑天之学有征。","impact":"落下闳是中国天文史上第一位留下姓名的仪器与历算专家，扬雄以后浑天家皆推其始；以浑仪观测、以历数推验的传统从太初历一直延续到元代郭守敬的简仪。","figures":["落下闳","唐都"],"place":"长安（落下闳出巴郡谯县）","state":"西汉","sources":["《汉书·律历志》","扬雄《法言》","《晋书·天文志》"],"tags":["浑天","落下闳","天文实测"]},"related":["cn--b104--s01"]},
  {"id":"cn--b104--m01","track":"cn","year":-104,"yearApprox":false,"dim":"military","weight":3,"title":"贰师将军首次伐大宛","summary":"发郡国恶少年数万人西行，至郁成败还。","detail":{"background":"汉使通西域「相望于道」，大宛匿其善马不肯与，且攻杀汉使、取其财物；武帝怒，以为不足示威于远国，欲以马为功。","process":"前104年（太初元年）以李夫人之兄李广利为贰师将军（宛有贰师城，汉军欲取善马，即以名城），「发属国六千骑及郡国恶少年数万人」西征；当道小国各城守不肯给食，「比至郁成，士者不过数千，皆饥罢」，攻郁成不能下，「引兵而还」，入敦煌时存者不过十分一二。","impact":"这次惨败使汉朝几乎举国西向，也暴露了敦煌以西无屯田则大军不能存在的补给极限，遂有列亭西展与轮台屯田；汉与匈奴争夺车师、楼兰的战争由此激化。","figures":["李广利","武帝刘彻"],"place":"大宛郁成城（今费尔干纳盆地一带）","state":"西汉","sources":["《史记·大宛列传》","《汉书·西域传》"],"tags":["伐大宛","贰师将军","远征补给"]},"related":["cn--b102--m01", "cn--b126--x01"]},
  {"id":"cn--b102--m01","track":"cn","year":-102,"yearApprox":false,"dim":"military","weight":4,"title":"再伐大宛斩宛王得善马","summary":"发谪戍六万人西出，围宛城，取其马而立其王。","detail":{"background":"首败之后武帝不容再却，「赦囚徒、发七科谪」，又北益出塞击匈奴以断其救；「大宛闻汉之兴兵也」，贵人与国人杀王毋寡而守城。","process":"前102年（太初三年）拜李广利为中将军，「益发天下谪戍」，兵六万人、牛十万、马三万余匹、驴骡橐他以倍数，敦煌以西分道并进；围宛城四十余日，宛贵人「杀其王毋寡，持其首」约和，出善马数十匹、中马以下牝牡三千余匹，汉「立味刺为宛王」而还，「军入玉门者万余人，马千余匹」。","impact":"汉军威自此远播中亚，「外国益颇闻汉之富强」，大宛、康居各遣使奉献；天马、苜蓿、蒲陶东传入长安，敦煌至盐泽亭障西连，丝绸之路全线进入汉制保护之下。","figures":["李广利","毋寡"],"place":"大宛（今费尔干纳盆地）","state":"西汉","sources":["《史记·大宛列传》","《汉书·西域传》"],"tags":["大宛","天马","丝路交通"]},"related":["cn--b104--m01", "cn--b119--i01", "cn--b101--e01"]},
  {"id":"cn--b101--e01","track":"cn","year":-101,"yearApprox":false,"dim":"economy","weight":3,"title":"亭障西展与轮台屯田","summary":"自敦煌西至盐泽往往起亭，轮台以东田牧。","detail":{"background":"两伐大宛后使者与商队往来日众，军食驿传须自给；轮台在东、车师之间，地广水草，可耕而控北道。","process":"前101年前后，汉「自敦煌西至盐泽，往往起亭」，烽燧与城障相接；诏于轮台以东屯田，置使者校尉领护其众，以给使者往来；车师降而复叛，「击破其国，徙其民于酒泉」。","impact":"屯田加亭障是汉在西域创造的低成本经略方式：不驻大军而以兵农合一的据点保障商路，成为此后西域都护府的雏形；居延、敦煌两汉简中的戍卒名籍与廪食簿即其遗存。","figures":["武帝刘彻"],"place":"轮台、车师（今新疆轮台、吐鲁番一带）","state":"西汉","sources":["《汉书·西域传》","《史记·大宛列传》","居延汉简"],"tags":["屯田","亭障","西域经略"]},"related":["cn--b102--m01", "cn--b108--i01"]},
  {"id":"cn--b100--x01","track":"cn","year":-100,"yearApprox":false,"dim":"explore","weight":3,"title":"苏武使匈奴被留十九年","summary":"杖汉节牧羊，卧起操持，节旄尽落。","detail":{"background":"前100年（天汉元年）且鞮侯单于初立，恐汉袭之，尽归汉使留在匈奴者；汉亦遣中郎将苏武持节送匈奴使留在汉者，副中张胜、常惠俱行。","process":"至单于庭，礼未尽而单于倨，汉使副张胜阴与缑王谋劫单于母阏氏归汉，事觉，苏武引佩刀自刺不死；单于幽之大窖中，绝不饮食，武啮雪与旃毛并咽之，数日不死；徙于北海之上无人处，使牧羝，「羝乳乃得归」，掘野鼠去草实而食之，杖汉节牧羊，卧起操持，节旄尽落。","impact":"前81年（始元六年）苏武得归，「留匈奴凡十九岁，始以强壮出，及还，须发尽白」；他使「北海」（今贝加尔湖）见于史册，也是汉使在欧亚内陆北部最早的确切地理记录，其持节不降成为中国古代气节的原型意象。","figures":["苏武","常惠","且鞮侯单于"],"place":"匈奴单于庭与北海（今贝加尔湖）","state":"西汉","sources":["《汉书·李广苏建传》","《资治通鉴·汉纪》"],"tags":["苏武","汉节","北海"]},"related":["cn--b99--m01", "cn--b99--m02"]},
  {"id":"cn--b99--m01","track":"cn","year":-99,"yearApprox":false,"dim":"military","weight":3,"title":"李陵五千步卒败浚稽山","summary":"出居延北行三十日至浚稽山，矢尽道穷而降。","detail":{"background":"前99年（天汉二年）以李陵为骑都尉，将丹阳楚人五千人教射于酒泉、张掖，本期为贰师将军李广利转运，陵自请「别出以分匈奴兵」。","process":"陵「将步卒五千人出居延，北行三十日，至浚稽山」，与单于十余万骑相遇，纵前后战，「斩首三千余级」，且战且南，「行三四日，至拘榆峡」，多射杀之，「斩首万余级」；单于引兵四面遮击，「矢尽道穷」，夜半击鼓不起，陵遂降匈奴，军士「脱身归者四百余人」。","impact":"浚稽山之战是古代步兵以弩阵对骑兵的经典战例，也说明汉军深入漠北已难全身而退；李陵降匈奴在朝廷掀起大狱，牵出司马迁受腐刑，汉匈战争的舆论与刑政矛盾自此公开化。","figures":["李陵","且鞮侯单于","路博德"],"place":"浚稽山（今蒙古戈壁阿尔泰一带）","state":"西汉","sources":["《史记·匈奴列传》","《汉书·李陵传》"],"tags":["浚稽山","李陵","步骑对抗"]},"related":["cn--b99--f01", "cn--b100--x01"]},
  {"id":"cn--b99--m02","track":"cn","year":-99,"yearApprox":false,"dim":"military","weight":2,"title":"贰师三万骑击右贤王于天山","summary":"出酒泉至天山，斩首万余级而还。","detail":{"background":"同年汉为分匈奴之势，贰师将军李广利将三万骑出酒泉，直指天山；「陵既别出」以牵制东路。","process":"前99年（天汉二年）夏，广利「至天山，击右贤王，获首虏万余级而还」，破其西城，收谷而还；「匈奴大入」代郡、雁门以报，两军所杀过当。","impact":"天山之胜与同年李陵之败恰成对照：汉军已能在东天山一带取得胜利，却无法长期控制这一草原与绿洲的过渡地带；此后汉军出塞的路线明显由漠北转向河西与天山南麓。","figures":["李广利","武帝刘彻"],"place":"天山（今新疆博格达山一带）","state":"西汉","sources":["《史记·匈奴列传》","《汉书·武帝纪》"],"tags":["天山","骑兵团击","汉匈战争"]},"related":["cn--b99--m01", "cn--b104--m01"]},
  {"id":"cn--b99--f01","track":"cn","year":-99,"yearApprox":false,"dim":"figure","weight":4,"title":"司马迁为李陵言下腐刑","summary":"盛称陵得士力，武帝以为沮贰师，下狱。","detail":{"background":"李陵兵败而生降，隤其家声，朝中陪位之臣争欲罪陵；司马迁独盛称陵事亲孝、与士信、常奋不顾身以殉国家之急，且言其意「且欲得其当而报汉」，武帝以为此言有讥于贰师将军李广利之丧师。","process":"武帝以迁「欲沮贰师，为陵游说」，下之「蚕室」之刑，「家贫，货赂不足以自赎，交游莫救视」；迁「居则忽忽若有所亡，出则不知其所往」，「肠一日而九回」，而「就极刑而无愠色」。","impact":"这是一次以言论定罪的典型：太史令以史官身份评议军事而受极刑。此后迁为中书令「尊宠任职」而发愤著书，「人固有一死，或重于泰山，或轻于鸿毛」即出于此时，成为后世论生死与著述意义最常被征引的话。","figures":["司马迁","李陵","武帝刘彻"],"place":"长安","state":"西汉","sources":["《汉书·司马迁传》","《报任安书》","《史记·太史公自序》"],"tags":["司马迁","李陵之祸","腐刑"]},"related":["cn--b99--m01", "cn--b98--c01"]},
  {"id":"cn--b98--c01","track":"cn","year":-98,"yearApprox":false,"dim":"culture","weight":4,"title":"史记成书与报任安书","summary":"网罗放失旧闻，究天人之际，成一家之言。","detail":{"background":"司马迁受腐刑后以著述自遣，续其父司马谈以不得与封禅之事、发愤而卒的遗业，「卒述陶唐以来，至于麟止」，自黄帝至太初，为一家之言。","process":"约前98年前后任中书令，与益州刺史任安书，历数「文王拘而演周易，仲尼厄而作春秋，屈原放逐乃赋离骚，左丘失明厥有国语」；自道其旨为「网罗天下放失旧闻，考之行事，稽其成败兴坏之理，凡百三十篇，亦欲以究天人之际，通古今之变，成一家之言」，《汉书》载其书「凡百三十篇，五十二万六千五百字」。","impact":"《史记》上起黄帝、下迄太初，首创以本纪、表、书、世家、列传为骨架的纪传体，为二十四史之祖；《报任安书》则把个人屈辱转化为著述的正当性，是中国散文史上最动人的自述之一。","figures":["司马迁","任安","司马谈"],"place":"长安","state":"西汉","sources":["《汉书·司马迁传》","《史记·太史公自序》"],"tags":["史记","纪传体","发愤著书"]},"related":["cn--b99--f01"]},
  {"id":"cn--b91--p01","track":"cn","year":-91,"yearApprox":false,"dim":"politics","weight":5,"title":"巫蛊之祸太子据兵败自杀","summary":"江充掘蛊太子宫，太子发兵，长安死者数万。","detail":{"background":"武帝末年多病，以为左右多以巫蛊祝诅；江充为水衡都尉、直指绣衣，将胡巫掘地求偶人，所治之处尽指为祝诅，京师吏民转相惊告，以巫蛊坐死者数万人，太子刘据亦屡见灾异之兆。","process":"前91年（征和二年）江充持节入太子宫掘蛊，称得桐木人；太子无以自明，乃矫节发兵，收江充斩之，发长乐宫卫以告百官，取武库兵、舍苑囚为军，与丞相刘屈氂战于长安城中五日，死者数万人；太子东奔湖县，追兵及之，闭阁自缢死，卫皇后自杀，二子一女俱遇害。","impact":"这场大狱摧毁了武帝一系的成年继承人，直接造成此后主少臣重的局面与霍光受遗辅政；武帝晚年族灭江充、作望思台、下轮台诏公开悔过，成为古代帝王以诏书「罪己」的著名先例。","figures":["刘据","江充","刘屈氂","武帝刘彻"],"place":"长安及湖县（今河南灵宝）","state":"西汉","sources":["《汉书·武五子传》","《汉书·江充传》","《资治通鉴·汉纪》"],"tags":["巫蛊之祸","卫太子","长安宫变"]},"related":["cn--b90--c01", "cn--b89--p01", "cn--b86--p01"]},
  {"id":"cn--b90--c01","track":"cn","year":-90,"yearApprox":false,"dim":"culture","weight":2,"title":"湖县作归来望思之台","summary":"武帝悔悟，为故太子作台于湖县。","detail":{"background":"太子死后，有司以其为罪闻，公卿莫敢复言；久之高寝郎田千秋上急变讼太子冤，武帝乃族江充家，而太子已不能复生。","process":"前90年前后，武帝怜太子无辜，于其死所湖县作「归来望思之台」，谥曰戾，为置园邑以守；并追罪构祸之人，烧苏文于渭桥，诛首事之家。","impact":"望思台自此成为文学中「父罪其子、悔之无及」的固定意象，后世题咏不绝；而太子之孙刘病已尚在民间、曾系郡邸狱，为日后宣帝以民间入承大统埋下伏笔。","figures":["武帝刘彻","刘据"],"place":"湖县（今河南灵宝）","state":"西汉","sources":["《汉书·武五子传》","《三辅黄图》"],"tags":["望思台","卫太子","晚年悔悟"]},"related":["cn--b91--p01", "cn--b88--p01"]},
  {"id":"cn--b89--p01","track":"cn","year":-89,"yearApprox":false,"dim":"politics","weight":5,"title":"轮台诏深陈既往之悔","summary":"止轮台屯田之议，封丞相为富民侯，与民休息。","detail":{"background":"前99年李陵以步卒五千陷没漠北，前90年贰师将军李广利将七万人出塞，兵败降匈奴；连年丧师，天下虚耗，边郡骚然，而搜粟都尉桑弘羊等犹请以轮台以东益屯田、起亭隧。","process":"前89年（征和四年）武帝下诏拒其议，「深陈既往之悔」：「乃者贰师败，军士死略离散，悲痛常在朕心。今请远田轮台，欲起亭隧，是扰劳天下，非所以优民也，今朕不忍闻。」又曰「当今务在禁苛暴，止擅赋，力本农，修马复令以补缺，毋乏武备而已」；乃「封丞相为富民侯，以明休息，思富养民」。","impact":"这是中国历史上第一份系统否定本国多年对外政策的皇帝诏书，西汉由「多事」转向「休息」的枢纽；「轮台罪己」自此成为后世谏止开边、忌功黩武的标准典故，昭宣之治由此开端。","figures":["武帝刘彻","桑弘羊","田千秋"],"place":"长安","state":"西汉","sources":["《汉书·西域传》","《汉书·食货志》","《资治通鉴·汉纪》"],"tags":["轮台诏","罪己","与民休息"]},"related":["cn--b88--p01", "cn--b85--s01", "cn--b99--m02"]},
  {"id":"cn--b88--p01","track":"cn","year":-88,"yearApprox":false,"dim":"politics","weight":3,"title":"田千秋白衣讼冤数月至丞相","summary":"高寝郎上急变讼太子，超居相位封富民侯。","detail":{"background":"巫蛊之后公卿莫敢言太子冤；田千秋为高寝郎，位微秩卑，无他材略术学，独据鞍上书讼之。","process":"前88年前后千秋「上急变讼太子冤」，其辞曰「子弄父兵，罪当笞；天子之子过误杀人，于何罪也」，自言「梦一白须老父，教臣上此书，非常人也」；武帝大悟，即时召拜大鸿胪，「数月遂至丞相」，封富民侯。","impact":"一人以白衣无资而超居相位，说明武帝末年用人已不循资格、纯以帝意指归；田千秋敦朴厚重而不知政本实在霍光，昭帝一朝遂为辅政体制的名分支柱，也开后世以名器收人心之例。","figures":["田千秋","武帝刘彻"],"place":"长安","state":"西汉","sources":["《汉书·车千秋传》","《汉书·百官公卿表》","《资治通鉴·汉纪》"],"tags":["田千秋","白衣拜相","巫蛊平反"]},"related":["cn--b91--p01", "cn--b89--p01"]},
  {"id":"cn--b87--p01","track":"cn","year":-87,"yearApprox":false,"dim":"politics","weight":4,"title":"武帝崩于五柞宫葬茂陵","summary":"在位五十四年，寿七十，六月葬茂陵。","detail":{"background":"后元二年（前87）春武帝疾笃于五柞宫；立少子弗陵为皇太子，「年且八岁」（一说六岁），以钩弋夫人「主少母壮」为由责之自杀，以防后妃临朝。","process":"二月甲子帝崩于五柞宫，殡于未央宫前殿，六月葬茂陵，谥曰孝武皇帝；茂陵在槐里，为西汉帝陵中营建最久、规模最盛者，卫青、霍去病、霍光、金日磾、李夫人、公孙弘等皆陪葬，陵旁置陵邑，徙天下富豪以守之。","impact":"武帝一生的疆域、财政、礼制与律令遗产全部交给一个幼年皇帝，形成主少而大臣重的格局，外戚以大司马大将军辅政之局由此开端；茂陵及其陵邑今存陵阙基址、石刻与陪葬墓群，是研究西汉丧葬制度与豪族迁徙的重要实物。","figures":["武帝刘彻","弗陵","钩弋夫人"],"place":"五柞宫与茂陵（今陕西周至、兴平）","state":"西汉","sources":["《汉书·武帝纪》","《史记·孝武本纪》","茂陵陵邑考古报告"],"tags":["武帝之死","茂陵","陵邑"]},"related":["cn--b86--p01", "cn--b117--a01"]},
  {"id":"cn--b86--p01","track":"cn","year":-86,"yearApprox":false,"dim":"politics","weight":4,"title":"霍光等受遗诏辅幼主","summary":"大司马大将军光秉政，四人同拜卧内受诏。","detail":{"background":"武帝将立幼子弗陵，以「主少母壮」为忧，责钩弋夫人死，以防后妃临朝；又以为霍光「出入禁闼二十余年，小心谨慎，未尝有过」，使画工图周公负成王朝诸侯之象以赐之。","process":"前86年六月昭帝立，年八岁；以光为大司马大将军，金日磾为车骑将军，太仆上官桀为左将军，搜粟都尉桑弘羊为御史大夫，「皆拜卧内床下，受诏辅少子」；光领尚书事，天下事壹关决焉，帝委而听之。","impact":"权力重心由丞相府移入禁中，「内朝官领尚书事」自此定形：宰相不专机要，而大司马大将军录尚书事成为两千年权臣的标准头衔。这一年同时确立了以宗庙礼制约束外戚、以禁军与尚书控制朝廷的辅政模式。","figures":["霍光","金日磾","上官桀","桑弘羊","弗陵"],"place":"长安未央宫","state":"西汉","sources":["《汉书·霍光传》","《汉书·昭帝纪》","《汉书·车千秋传》"],"tags":["霍光辅政","领尚书事","内朝"]},"related":["cn--b87--p01", "cn--b91--p01"]},
  {"id":"cn--b85--s01","track":"cn","year":-85,"yearApprox":false,"dim":"science","weight":4,"title":"赵过行代田法与耦犁","summary":"一亩三甽岁代处，作耦犁耧车，用力少而得多。","detail":{"background":"轮台诏后以「力本农」为国是，而郡国民惰于耕、器用苦恶、牛马不足；搜粟都尉赵过能为代田，先试之于公田，令边卒习耕，乃推于民。","process":"其法「一亩三甽，岁代处」：亩中开三沟，播种于沟内，苗长则拔垄上之草附根而培之，来年沟垄互易，以垄为休耕、以沟为集雨抗旱；用耦犁二牛三人以深耕，又作三脚耧车，一过三垄，开沟、下种、覆土同时而毕，可日种一顷；令田官与工徒自铸铁器，教边郡及民。","impact":"代田把休耕、集雨抗旱与畜力深耕制度化，史称「用力少而得谷多」，收常过缦田一斛以上；推广及于边郡、居延、云中、河东、太常与三辅。三脚耧是世界最早的畜力条播机，欧洲到十八世纪才有同类播种器具。","figures":["赵过","田千秋","弗陵"],"place":"三辅及边郡居延、云中、河东","state":"西汉","sources":["《汉书·食货志》","《氾胜之书》辑本","居延汉简"],"tags":["代田法","耦犁","三脚耧车"]},"related":["cn--b89--p01"]},
  {"id":"cn--b82--i01","track":"cn","year":-82,"yearApprox":false,"dim":"institution","weight":3,"title":"罢临屯真番二郡","summary":"省四郡为二，玄菟东迁，乐浪以南入汉郡。","detail":{"background":"朝鲜四郡地广民寡，北界秽、貊，东阻大海，越三千里而守一城，吏卒廪食皆仰海运与辽东转运，实控之力不逮。","process":"前82年（始元五年）汉罢临屯郡，以其民并入乐浪；又省真番郡入玄菟，玄菟郡治遂东北徙于上殷县一带，高句丽、沃沮诸部改隶焉。","impact":"这是汉帝国第一次主动收缩东方郡县，标示以郡县直接统治辽东以东的限界；此后以乐浪、玄菟为支点，属国、候、三老与册封并用，成为中原王朝经营朝鲜半岛与东北亚的长期模式。","figures":["弗陵","霍光"],"place":"乐浪、玄菟（今朝鲜平壤与辽宁新宾一带）","state":"西汉","sources":["《汉书·地理志》","《汉书·昭帝纪》","《三国志·东夷传》"],"tags":["汉四郡","郡县收缩","羁縻"]},"related":["cn--b108--i01"]},
  {"id":"cn--b81--c01","track":"cn","year":-81,"yearApprox":false,"dim":"culture","weight":5,"title":"盐铁会议论禁榷利害","summary":"诏郡国举贤良文学问民间疾苦，共执盐铁酒榷之便否。","detail":{"background":"武帝末年均输、平准、盐铁、酒榷、算缗诸利尽归公上，民困于赋役而吏缘为奸；昭帝初年经费仍不足，郡国多废耕业。始元六年（前81）诏天下举贤良文学六十余人至京师，由御史大夫桑弘羊与丞相田千秋承问，就民间疾苦逐条发难。","process":"贤良文学主张官府盐铁则器物苦恶、价格不平，吏催督使农民弃耒耜而就末作，均输平准名为均平实为与民争利，故请罢之，返利于民，以务农省用为本。桑弘羊反驳：盐铁之利以佐边境军费、赡给戍卒，一旦罢之则经费无所出、边备自虚；均输可以平万物、通委财，是制四夷而强国之势，不可废。双方往复诘难，兼及北边和战、币制、法令与德治之辨。","impact":"朝廷最后罢酒榷而盐铁仍旧，政策并未全盘转向，但把武帝一朝的财政路线第一次公开置于批判之下。宣帝时桓宽据会议记录推衍为《盐铁论》六十篇，是研究汉代经济政策与士人政治观最完整的对话体文献；其中「县官与民争利」之论，成为此后两千年反对禁榷聚敛的标准论据。","figures":["桑弘羊","田千秋","桓宽"],"place":"长安","state":"西汉","sources":["《盐铁论》","《汉书·昭帝纪》","《汉书·食货志》"],"tags":["盐铁会议","贤良文学","禁榷之辩"]},"related":["cn--b119--e01", "cn--b110--e01", "cn--b85--s01"]},
  {"id":"cn--b81--x01","track":"cn","year":-81,"yearApprox":false,"dim":"explore","weight":3,"title":"苏武归汉拜典属国","summary":"留匈奴十九岁，杖节而还，赐爵关内侯。","detail":{"background":"始元六年（前81）春汉与匈奴复通使、修和亲，汉使访求被留者；常惠得夜见汉使，教以武帝在上林射雁、雁足系帛书为言，单于不得已乃承认苏武尚在。","process":"苏武与随行使者九人同归长安，出使时强壮，至是须发尽白；赐爵关内侯、黄金二十斤，数月迁为典属国，秩中二千石，掌四夷朝贡与列侯事务。李陵在匈奴置酒与武诀别，赠诗有「径万里兮度沙幕」之句。","impact":"苏武归国是昭帝初对匈关系转暖的象征，典属国一官自此由武职变为常掌外事的职任；《汉书》为其立传，而李陵、苏武赠答与别后歌诗，成为后世送别与使臣题材诗的源头之一。","figures":["苏武","常惠","李陵"],"place":"长安及匈奴单于庭","state":"西汉","sources":["《汉书·李广苏建传》","《资治通鉴·汉纪》"],"tags":["苏武","典属国","汉匈和亲"]},"related":["cn--b100--x01", "cn--b99--m01"]},
  {"id":"cn--b80--p01","track":"cn","year":-80,"yearApprox":false,"dim":"politics","weight":4,"title":"上官桀桑弘羊之变与燕王旦案","summary":"谋除霍光、废帝立旦，事觉，一党尽族。","detail":{"background":"昭帝年十四，燕王刘旦以武帝长子自居不服辅政；上官桀因子安世谋夺霍光之权，与桑弘羊、盖长公主结为党，使人伪为燕王上书，历数霍光「专权自恣」，请得入宿卫。","process":"元凤元年（前80）其谋发露：霍光称病以观其变，郎署上书者言变书不敬当诛，帝遂命收捕；桀、安世、弘羊及其与党尽族诛，坐死者数千人。同年燕王旦与宗正刘泽谋反事觉，旦置酒与夫人作歌「归空城兮狗不吠，鸡不鸣」而自杀，刘泽伏诛，燕国除为郡。","impact":"此役之后霍光威震海内，公卿以下不敢异言；宣帝初即位，朝谒大将军，「若有芒刺在背」。它确立了一条规则：政本在禁中与领尚书事者，丞相、御史不能与之争，此制贯穿整个西汉后期。","figures":["霍光","上官桀","桑弘羊","刘旦","刘泽"],"place":"长安及燕国（今北京一带）","state":"西汉","sources":["《汉书·霍光传》","《汉书·武五子传》"],"tags":["元凤政变","霍光专权","宗室削国"]},"related":["cn--b86--p01", "cn--b74--p01"]},
  {"id":"cn--b80--i01","track":"cn","year":-80,"yearApprox":false,"dim":"institution","weight":2,"title":"省禁苑假民公田","summary":"减乘舆苑囿，以公田假贫民而薄其租。","detail":{"background":"武帝以来上林、水衡所属苑囿占田辽阔，贫民无地而流冗；昭帝时以「与民休息」为国是，欲省宫廷之费而业农。","process":"元凤年间前后诏省减乘舆马苑、水衡苑囿，「假与城郭、乡邑贫民」耕之，租税从轻；并省小黄门、乐府与太官侈费，令民得入谷于边郡以除罪、以受爵。","impact":"假民公田自此成为汉代安置无地与流亡农民的常法：田仍是官有，农民只取得租佃之「假」，此制为后世官田、职田、屯佃之制提供雏形，也是国家在土地问题上「不均田而给佃」的典型选择。","figures":["弗陵","霍光"],"place":"三辅上林苑及郡国","state":"西汉","sources":["《汉书·昭帝纪》","《汉书·食货志》"],"tags":["假民公田","省禁苑","流亡安置"]},"related":["cn--b89--p01", "cn--b85--s01"]},
  {"id":"cn--b74--p01","track":"cn","year":-74,"yearApprox":false,"dim":"politics","weight":5,"title":"昌邑王贺在位二十七日见废","summary":"受皇帝玺绶，行淫乱失节，为霍光所废。","detail":{"background":"元平元年（前74）四月昭帝崩，年二十一，无嗣。霍光与张安世定议，以广陵王胥「好游猎、无威仪」不可立，乃迎武帝兄孙、昌邑王刘贺，使使者持节迎之。","process":"刘贺六月至长安，即皇帝位，行故昌邑之国凡百二十日而实未改元？在位二十七日，征发故国吏民车载物一千五百余乘，「居丧无礼」，日夜饮宴，与女子杂居；霍光忧懑，与田延年、杨敞等定策，奏皇太后，诏废贺，令归故国，赐黄金千斤，食邑三千户，其群臣二百余人以「辅导不谨」被诛，临行贺叹「猫乃死耳」。","impact":"这是权臣以皇太后诏废帝的第一次完整成功：它同时证明霍光可以立、可以废，也迫使后继者宣帝在朝谒时「若有芒刺在背」；昌邑一系的属吏集团被连根拔起，中央与侯国之间的人身依附关系由此整顿。","figures":["刘贺","霍光","杨敞","田延年"],"place":"长安及昌邑（今山东巨野）","state":"西汉","sources":["《汉书·霍光传》","《汉书·武五子传》","《资治通鉴·汉纪》"],"tags":["废昏立明","霍光定策","昌邑王"]},"related":["cn--b80--p01", "cn--b74--p02"]},
  {"id":"cn--b74--p02","track":"cn","year":-74,"yearApprox":false,"dim":"politics","weight":5,"title":"立皇曾孙病是为宣帝","summary":"取狱中婴儿于民间，汉统复归卫太子一系。","detail":{"background":"刘据兵败而死，皇孙刘病已方在襁褓，系长安郡邸狱；廷尉监丙吉选宽厚者二人以乳养之，逢赦得免，属籍宗正，生长于民间，好游侠，往来长安、三辅之间。","process":"昌邑王既废，御史大夫丙吉与大将军长史皆上书，言宗室贤者唯皇曾孙；遂以元平元年（前74）秋七月迎立之，是曰宣帝。宣帝即位之初，事事关白大将军，谨让而已，权一出霍氏。","impact":"皇统回到卫太子一系，是西汉后期政治合法性的关键一环；宣帝因起于民间，深知吏治得失与百姓疾苦，故为政「自上总领名责实」，信用能吏而抑儒生之论，史称「孝宣之治，信赏必罚，综核名实」，与武帝末年的疲敝形成对照。","figures":["刘病已","丙吉","霍光"],"place":"长安","state":"西汉","sources":["《汉书·宣帝纪》","《汉书·丙吉传》","《资治通鉴·汉纪》"],"tags":["宣帝即位","郡邸狱","孝宣中兴"]},"related":["cn--b74--p01", "cn--b91--p01"]},
  {"id":"cn--b71--m01","track":"cn","year":-71,"yearApprox":false,"dim":"military","weight":4,"title":"十五万骑五道出塞合击匈奴","summary":"本始三年汉军五道并出，乌孙兵自西相应。","detail":{"background":"匈奴连年入边，又西击乌孙，取车师田卒；本始三年（前71）汉大举谋报，遣将军凡五道并出。","process":"汉以步骑十五万分五道出塞：度辽将军出张掖、前将军出云中、虎牙将军出五原、祁连将军出酒泉、蒲类将军出西河，各率骑二万余，期会；乌孙昆弟翁归靡亦自发其众击右谷蠡王庭。汉军出塞各数百千里，所获少而罢费甚，多遇空庐；乌孙则「获单于叔父、诸王名号者，四万余级，牛马七十余万」。","impact":"这是汉军规模最大的多路合围，虽未取得歼灭战果，却让匈奴同时受北、西、东三方压力；同年冬单于自乌孙引还，遇大雨雪，人马冻死者什六七，属国多叛，匈奴由此转弱，是双方力量关系的转折点之一。","figures":["范明友","赵充国","翁归靡","壶衍鞮单于"],"place":"五原至天山一线","state":"西汉","sources":["《汉书·匈奴传》","《汉书·西域传》","《汉书·昭帝纪》"],"tags":["五道出塞","乌孙夹击","匈奴之衰"]},"related":["cn--b119--i01", "cn--b71--x01"]},
  {"id":"cn--b71--x01","track":"cn","year":-71,"yearApprox":false,"dim":"explore","weight":3,"title":"解忧公主与乌孙、龟兹","summary":"汉宗女两世嫁乌孙，通使城郭国，兄弟为昆弟。","detail":{"background":"细君公主卒后，汉复以楚王刘戊之孙为江都王女，号解忧公主，续嫁乌孙，居赤谷城，与匈奴、西域诸国处于夹缝之间。","process":"乌孙昆弟翁归靡上书请「为解忧公主家室」与汉并力，许以共击匈奴；公主三子二女，元为乌孙嗣子，长子元以后为汉所立，其弟女适龟兹王，龟兹王来朝于汉；汉以长罗侯常惠持节护之。","impact":"和亲在乌孙变成有军事实效的联盟：乌孙三万骑与汉军夹击匈奴，正出此盟；而公主之女为龟兹后，使汉的典章、乐舞与吏员西入塔里木盆地，龟兹乐与汉使节由此常通，成为都护府建立的政治前提。","figures":["解忧","翁归靡","常惠"],"place":"乌孙赤谷城（今伊塞克湖一带）","state":"西汉","sources":["《汉书·西域传》","《资治通鉴·汉纪》"],"tags":["和亲","乌孙","龟兹"]},"related":["cn--b126--x01", "cn--b71--m01"]},
  {"id":"cn--b70--i01","track":"cn","year":-70,"yearApprox":false,"dim":"institution","weight":2,"title":"边郡属国处降者","summary":"置属国都尉，因其故俗而籍其胜兵。","detail":{"background":"自元狩以来匈奴、羌胡降者日众，散处边郡，既须养赡，又须防其翻覆；昭宣之间乌桓、羌人内属者复多。","process":"本始、地节间于张掖、西河、酒泉、天水等郡置属国都尉，「主降者」，不改其部族、君长与畜牧之俗，唯以汉使领护，籍其胜兵之数，使分处要地、有事征发；属国置丞、置候，秩比二千石，独立于郡。","impact":"属国制度以「不易其俗而收其兵用」为原则，成为汉唐处置内附游牧部族的模板，后世羁縻府州、内附部落皆由此演化；它既给边郡提供了骑兵与劳力，也造成东汉以后并居边郡的部族坐大这一长期隐患。","figures":["刘病已"],"place":"张掖、西河、酒泉等边郡","state":"西汉","sources":["《汉书·百官公卿表》","《后汉书·郡国志》刘昭注","居延汉简"],"tags":["属国都尉","降者安置","因俗而治"]},"related":["cn--b127--i01", "cn--b60--i01"]},
  {"id":"cn--b68--f01","track":"cn","year":-68,"yearApprox":false,"dim":"figure","weight":3,"title":"霍光薨与宣帝亲政之渐","summary":"大司马大将军光病免，谥宣成侯，封邑如故。","detail":{"background":"地节二年（前68）春霍光病，三月薨；宣帝与皇太后亲临其丧，赐梓宫、便房、黄肠题凑，东园温明之器，葬礼之盛，汉世功臣无与为比。","process":"霍光既葬，宣帝始亲郊庙、自总万机；以张安世为卫尉，典二宫卫率，徙霍禹为大司马而夺其印绶，收其禁兵，诸霍皆为卿相而失实；光诸婿诸驸马仍并领禁省，家属治第宅、僭拟乘舆。","impact":"这是皇权自下而上回收权臣遗产的过程：不惊动其人而先换其兵，两年之后族灭霍氏，成为后世处置外戚权门的样本；它也说明领尚书事体制的存亡，全系于皇帝能否取得禁中与北军。","figures":["霍光","刘病已","张安世"],"place":"长安及平陵（今陕西咸阳西北）","state":"西汉","sources":["《汉书·霍光传》","《汉书·宣帝纪》"],"tags":["霍光之死","皇权回收","黄肠题凑"]},"related":["cn--b80--p01", "cn--b64--p01"]},
  {"id":"cn--b66--c01","track":"cn","year":-66,"yearApprox":true,"dim":"culture","weight":3,"title":"桓宽推衍盐铁论成书","summary":"宣帝时汝南桓宽推衍盐铁会议之议，为六十篇。","detail":{"background":"始元六年的盐铁会议虽罢酒榷而盐铁如故，然当时公卿与贤良文学答问之辞未有定本，其议往往散在士人传述之间。","process":"宣帝时，汝南人桓宽以曾从与会者闻其说，乃「推衍盐铁之议，增广条目，极其论难」，著为《盐铁论》凡六十篇，以文学、贤良与御史大夫、丞相史往复诘难为体，兼及力役、币制、边备、法制与礼义之本。","impact":"这是中国最早以政策辩论为主体的政论文献，也是汉代经济思想唯一成系统的对话文本；其崇本抑末、与民休息之论经此书定型，成为此后两千年批评禁榷聚敛者的武器库。","figures":["桓宽","桑弘羊"],"place":"汝南至长安一带","state":"西汉","sources":["《盐铁论》","《汉书·食货志》"],"tags":["盐铁论","经济思想","政策辩论"]},"related":["cn--b81--c01", "cn--b119--e01"]},
  {"id":"cn--b65--i01","track":"cn","year":-65,"yearApprox":false,"dim":"institution","weight":2,"title":"置孝弟力田与三老劝率","summary":"诏郡国务农桑，以乡官三老、力田课最。","detail":{"background":"宣帝数诏郡国务在农桑，而郡国之吏多以狱讼、赋敛为课，劝率无人；武帝末以来流民未尽还，编户多困。","process":"元康（前65—前62）之前，诏郡国置孝弟、力田，与乡三老、啬夫、游徼同为乡官，专掌劝课农桑、表率风俗；又于三辅及边郡置农官、都水、均输，数诏无出今年算赋、减天下口钱。","impact":"把「劝农」写成有编制的职责，是中国基层治理史上少见的制度尝试：它使中央的农桑考课落到乡里，形成此后两千余年「三老、力田」的乡官谱系，也透露了帝国无法直接干预土地分配时的替代办法。","figures":["刘病已"],"place":"郡国乡里及三辅","state":"西汉","sources":["《汉书·宣帝纪》","《汉书·百官公卿表》","尹湾汉简《集簿》"],"tags":["三老力田","乡官制度","劝农"]},"related":["cn--b134--i01", "cn--b80--i01"]},
  {"id":"cn--b65--p01","track":"cn","year":-65,"yearApprox":false,"dim":"politics","weight":3,"title":"苏武与霍光日磾并侍中曹","summary":"诏举故旧尝侍中曹者，独以义节称。","detail":{"background":"宣帝追念武帝以来旧恩，图功臣于麒麟阁；同时数诏郡国存问年七十以上、鳏寡孤独，高者得复其子之算，又举孝子、贞妇以厚风俗。","process":"甘露前后诏举武帝时尝侍中、典属国、持节使绝域者之后，苏武之子、金日磾之孙并得官；又令太官赐年长孤老酒肉，郡国岁上孝子、贞妇，以劝风俗。","impact":"把持节使绝域与宿卫旧恩列为一等功劳，是宣帝中兴叙事的一部分：既表彰实务性的人才，又为养老与风俗之政提供伦理示范；这类诏令在《汉书》本纪中密集出现，构成「孝宣之治」的软性一面。","figures":["刘病已","苏武","金日磾"],"place":"长安及郡国","state":"西汉","sources":["《汉书·宣帝纪》","《汉书·李广苏建传》"],"tags":["养老之政","中兴叙事","风俗劝率"]},"related":["cn--b51--a01", "cn--b81--x01"]},
  {"id":"cn--b64--p01","track":"cn","year":-64,"yearApprox":false,"dim":"politics","weight":4,"title":"霍氏满门以谋反族诛","summary":"霍禹谋为乱，事觉，云、山自杀，显弃市。","detail":{"background":"霍光死后，其子禹、孙云、山袭封，诸婿驸马皆掌宿卫；宣帝初政，渐夺其兵，转任诸刘为卿；霍显骄奢，此前曾使女医淳于衍进毒药杀许皇后，至此事亦渐露。","process":"地节四年（前64）夏，霍禹与其兄弟子婿谋以午日劫丞相、御史，因欲废帝；事泄，禹被腰斩，霍显及诸昆弟、党与皆弃市，一家族灭，霍云、霍山自杀，皇后霍氏废处昭台宫。宣帝于是躬亲万机，以丙吉为丞相、魏相为御史大夫，机要始还台阁。","impact":"霍氏之灭结束了武帝末以来大司马大将军专政的第一轮，也为外戚划定一条警戒线：可以贵宠，不可以典禁兵；宣帝以后许、史、王三家相继而起，这条教训终究没能拦住西汉的衰亡。","figures":["刘病已","霍禹","霍显","丙吉","魏相"],"place":"长安","state":"西汉","sources":["《汉书·霍光传》","《汉书·外戚传》","《汉书·丙吉传》"],"tags":["霍氏覆灭","外戚警戒","宣帝亲政"]},"related":["cn--b68--f01", "cn--b74--p02"]},
  {"id":"cn--b61--m01","track":"cn","year":-61,"yearApprox":false,"dim":"military","weight":4,"title":"赵充国屯田奏记平先零羌","summary":"以七十余岁将兵，罢骑兵而留田，羌遂瓦解。","detail":{"background":"神爵元年（前61）先零羌与诸羌解仇结盟，通使匈奴，欲遮隔玉门；汉遣御史大夫丙吉问可使者，赵充国时年七十余，自请驰至金城，图上方略。","process":"赵充国至金城，先以兵威招降罕、幵等羌，禁军士不得攻击已降者；又奏罢骑兵万人的转输之费，留步卒万人因田于湟水、临羌以西，治乡亭、缮邮亭、积谷物，且耕且守，谓羌本可坐致。其议与公卿相难，宣帝数使使者问之，后卒用其策。","impact":"先零羌不待大兵而自溃，斩首与降者各以万数，金城属国遂置；屯田奏记记省戍卒、罢转输之利，成为后世「以屯代兵」的经典，也是羌患长期化的开始。","figures":["赵充国","刘病已"],"place":"金城、湟水一带（今甘肃兰州至青海湟中）","state":"西汉","sources":["《汉书·赵充国传》","《资治通鉴·汉纪》"],"tags":["赵充国","屯田","先零羌"]},"related":["cn--b70--i01", "cn--b101--e01"]},
  {"id":"cn--b60--p01","track":"cn","year":-60,"yearApprox":false,"dim":"politics","weight":4,"title":"日逐王降汉，僮仆都尉自是亡","summary":"匈奴日逐王先贤掸将万骑西向，郑吉迎之。","detail":{"background":"匈奴虚闾权渠单于立后国内不安，日逐王先贤掸与单于有隙；匈奴故置僮仆都尉，司西域诸国赋税，役使城郭之国，汉使往来皆苦之。","process":"神爵二年（前60）日逐王先贤掸将众万余西向降汉，护鄯善以西使者郑吉发诸国兵迎之，送长安，汉封为归德侯；匈奴僮仆都尉自此不复置，北道诸国并归于汉。","impact":"匈奴在西域的统治机构自此终结，西域第一次同时由一国都护统领；两年后匈奴内部五单于并立、呼韩邪南附，西域都护府的成立成为瓜分草原政治遗产的关键一着。","figures":["郑吉","先贤掸"],"place":"乌垒、渠犁（今新疆轮台、库尔勒一带）","state":"西汉","sources":["《汉书·西域传》","《汉书·郑甘陈汤传》","《资治通鉴·汉纪》"],"tags":["日逐王降","僮仆都尉","北道归汉"]},"related":["cn--b60--i01", "cn--b71--m01"]},
  {"id":"cn--b60--i01","track":"cn","year":-60,"yearApprox":false,"dim":"institution","weight":5,"title":"西域都护府初置","summary":"号曰都护，治乌垒城，并护南北两道诸国。","detail":{"background":"自张骞凿空、贰师伐宛之后，汉使遍往来城郭诸国；轮台、车师、渠犁屯田相继，日逐王又降，西域南北道皆向汉，非置官统督不能制。","process":"神爵二年（前60）汉以郑吉为西域都护，治乌垒城（今新疆轮台东），统督察大宛以东、南北道三十六国，置副校尉、丞、司马、候、千人；诸国所受汉官印绶、屯田、客使与城郭之守皆属都护。","impact":"这是中原王朝第一次将西域纳入常设军政管辖，其办法是册封当地君长、驻校尉与田卒、控驿道而非编户征赋，是一种成本极低的间接统治；「都护」自此成为历朝控御边疆的通名，西域亦由此正式进入中国史。","figures":["郑吉","刘病已"],"place":"乌垒城（今新疆轮台东）","state":"西汉","sources":["《汉书·西域传》","《资治通鉴·汉纪》","尼雅佉卢文与汉简"],"tags":["西域都护","乌垒城","边疆治理"]},"related":["cn--b126--x01", "cn--b101--e01", "cn--b60--p01"]},
  {"id":"cn--b55--i01","track":"cn","year":-55,"yearApprox":true,"dim":"institution","weight":3,"title":"耿寿昌奏立常平仓","summary":"边郡谷贱则增价而籴，名曰常平。","detail":{"background":"宣帝以京师用度不足，漕关东四百万石乃给；大司农中丞耿寿昌治度支，请先籴三辅、弘农、河东、上党、太原之谷以实京师，省关东漕事过半。","process":"五凤中（约前55年）寿昌奏：边郡岁丰则谷价甚贱，农夫反伤，请谷贱之时增其价而籴以利民，贵则减价而粜，名曰常平仓；又请以水运、漕渠相续，省关东漕事之半。","impact":"常平仓制度以官方籴粜来平抑谷价、保护小农与军粮供应，自是历代王朝备荒与稳价的标配，一直沿用到清末；它同时也是古代中国「以财政手段调节市场」最早的成熟设计，其得失之争贯穿此后两千年。","figures":["耿寿昌","刘病已"],"place":"三辅及边郡诸仓","state":"西汉","sources":["《汉书·食货志》","《汉书·沟洫志》"],"tags":["常平仓","平抑谷价","耿寿昌"]},"related":["cn--b110--e01", "cn--b65--i01"]},
  {"id":"cn--b55--m01","track":"cn","year":-55,"yearApprox":false,"dim":"military","weight":3,"title":"匈奴五单于并立自相攻击","summary":"神爵以来匈奴内乱，五六单于更相诛灭。","detail":{"background":"虚闾权渠单于死后，匈奴贵人与诸部相继自立，单于之号日多；日逐王先贤掸东降之后，西部远有郅支、近有呼韩邪，各据一方。","process":"约前55年，匈奴诸部并自立为单于，凡五六号，更相攻击，国中大乱，饥饿相食，畜产耗减；诸王、将帅多将其众降汉。汉公卿或议乘其乱而取之，或以为当存其国、示以恩信。","impact":"匈奴的统一体在此十余年间彻底解体，草原的分裂与饥荒成为汉不战而胜的原因，也把南匈奴的内附与北匈奴的西迁一并推到前台；汉廷由此开始以册封、粮赈与质子操纵草原政治。","figures":["呼韩邪单于","郅支单于"],"place":"蒙古高原","state":"西汉","sources":["《汉书·匈奴传》","《资治通鉴·汉纪》"],"tags":["五单于并立","匈奴内乱","草原解体"]},"related":["cn--b60--p01"]},
  {"id":"cn--b53--e01","track":"cn","year":-53,"yearApprox":false,"dim":"economy","weight":3,"title":"减天下口钱与算赋之议","summary":"郡国盐铁、漕役烦扰，御史请省费宽赋。","detail":{"background":"宣帝时商贾已盛而吏多侵渔，民有口钱、算赋之出：生子重生三岁即出口钱，算赋人百二十钱，边用钱不足，郡国常有困乏；大司农钱谷出入，岁有簿籍。","process":"甘露、黄龙之间数诏减天下口钱、无出算赋，省苑囿、假贫民田，罢角抵与奇玩之物；丞相、御史条奏郡国不便者数事，皆以省费宽民为务。","impact":"减赋与省费并不能扭转土地兼并与流民问题，却确立了「中兴」时期的财政政策样式：以宽赋、劝农、屯田、常平为组合，而不再依赖算缗、告缗式掠夺；这为元成以后外戚与豪族坐大留下财政空间。","figures":["刘病已","黄霸"],"place":"长安及郡国","state":"西汉","sources":["《汉书·食货志》","《汉书·宣帝纪》","《汉书·黄霸传》"],"tags":["宽赋","省费","中兴财政"]},"related":["cn--b65--i01", "cn--b55--i01"]},
  {"id":"cn--b51--a01","track":"cn","year":-51,"yearApprox":false,"dim":"art","weight":2,"title":"麒麟阁十一功臣图形","summary":"上思股肱之美，图画霍光等十一人于麒麟阁。","detail":{"background":"神爵、五凤之际西羌既定、匈奴且款塞，宣帝以为中兴之业已就，追念武昭以来佐命之功，乃图功臣以示劝率。","process":"甘露三年（前51）图大司马大将军博陆侯霍光、张安世、韩增、赵充国、魏相、丙吉、杜延年、刘德、梁丘贺、萧望之、苏武十一人于未央宫麒麟阁，法其制度、纪其功德，各题官爵邑里；霍光独不书名，但题「大司马大将军博陆侯姓霍氏」。","impact":"以图形纪功是帝国塑造臣节典范的政治手段，把功臣变成可视的榜样的同时，也悄悄排除了霍光之族、桑弘羊与卫太子之冤；「麒麟阁」、「凌烟阁」自此为历代王朝表彰功臣的通名。","figures":["刘病已","霍光","苏武","赵充国"],"place":"长安未央宫麒麟阁","state":"西汉","sources":["《汉书·李广苏建传》","《三辅黄图》","《汉书·叙传》"],"tags":["麒麟阁","功臣图像","中兴叙事"]},"related":["cn--b81--x01", "cn--b64--p01"]},
  {"id":"cn--b51--c01","track":"cn","year":-51,"yearApprox":false,"dim":"culture","weight":4,"title":"石渠阁讲论五经异同","summary":"诏诸儒讲五经同异，天子亲称制临决。","detail":{"background":"武帝立五经博士后，今文各家以「师法」「家法」相非，同经异说，章句滋多；宣帝闻《穀梁春秋》与《公羊》义理有异，欲正其得失。","process":"甘露三年（前51）冬，诏诸儒于未央殿中石渠阁讲论《诗》《书》《礼》《乐》《春秋》《易》诸经异同，太子太傅萧望之等平奏其议，「天子亲称制临决焉」；议定后增立《梁丘易》、大小《夏侯尚书》、《穀梁春秋》博士。","impact":"经学论议自此以皇帝裁决收束，家法之争由师门之异变成朝廷礼制的一部分；穀梁、欧阳等家既得立，学官渐多、章句益繁，也为成哀以后古文经学兴起与今古文之争埋下题目。","figures":["刘病已","萧望之","梁丘贺","韦贤"],"place":"长安未央宫石渠阁","state":"西汉","sources":["《汉书·宣帝纪》","《汉书·艺文志》","《汉书·儒林传》"],"tags":["石渠阁","五经异同","家法"]},"related":["cn--b136--i01", "cn--b130--c01"]},
  {"id":"cn--b49--p01","track":"cn","year":-49,"yearApprox":false,"dim":"politics","weight":4,"title":"呼韩邪单于入朝甘泉","summary":"南单于款塞朝汉，位在诸侯王上，赐以印绶。","detail":{"background":"匈奴内乱，呼韩邪为郅支所败，用左伊秩訾王计，称臣入朝以求汉援；黄龙元年（前49）正月，呼韩邪单于朝于甘泉宫。","process":"宣帝郊见甘泉，呼韩邪单于仰见汉家仪卫而拜；汉赐黄金、衣被、锦帛、车马，宠以殊礼，令位在诸侯王上、称臣为藩服；明年复来朝，礼遇益厚，北边自是数世不见烟火之警。","impact":"这是匈奴最高首领第一次以臣属身份入朝，草原与中原的关系由敌国对等转为册封君臣；汉以少量帛粮换得北边数世不见烟火之警，也由此背上了扶植南单于、与北匈奴争草原的义务，遂有后来郅支被诛之事。","figures":["呼韩邪单于","刘病已","左伊秩訾王"],"place":"甘泉宫（今陕西淳化西北）","state":"西汉","sources":["《汉书·匈奴传》","《汉书·宣帝纪》","《资治通鉴·汉纪》"],"tags":["呼韩邪入朝","册封君臣","北边安定"]},"related":["cn--b55--m01", "cn--b60--i01"]},
  {"id":"cn--b48--i01","track":"cn","year":-48,"yearApprox":false,"dim":"institution","weight":4,"title":"元帝初政罢奢靡之费","summary":"省乐府员、罢角抵诸戏，假苑囿田地与贫民。","detail":{"background":"武帝末至昭宣，宫廷苑囿、乐府、角抵诸费甚巨，斗鸡走马、希微珍巧之物并积于黄门；元帝以儒素即位，欲以节俭收民心。","process":"初元元年（前48）诏省乐府员之半，罢角抵与希微珍玩，出后宫未尝见者，省乘舆狗马；又诏假水衡、少府苑囿田地与贫民，减诸侯王朝献之费。","impact":"省费宽民自此成为元、成两朝的常调，与宣帝中兴的财政作风相续；但外戚与近习的用度并未因此收束，宦寺用事之局反而在数年后打开。","figures":["刘奭","贡禹"],"place":"长安","state":"西汉","sources":["《汉书·元帝纪》","《汉书·贡禹传》"],"tags":["省费","乐府","假民苑囿"]},"related":["cn--b48--e01", "cn--b80--i01", "cn--b64--p01"]},
  {"id":"cn--b48--e01","track":"cn","year":-48,"yearApprox":false,"dim":"economy","weight":3,"title":"贡禹请罢采珠冶铸之议","summary":"以民废于末作，请一切禁巧工而返之田。","detail":{"background":"贡禹以贤良征为谏大夫，上疏历言民坐铸钱、采珠玉、治园冶而犯法者众，富人大贾被服文绣而农夫不足。","process":"禹请以工巧无用之作为禁，罢尚方珍巧之物，禁采珠玉、治锦绣，壹力农桑，并请禁郡国私铸、专以五铢；章下公卿，议者以为不可卒行，元帝不能尽用。","impact":"这是西汉后期以儒术为据的重农抑末纲领最完整的一次陈述，虽未成立法，却为此后的禁奢诏与限田议定下议题；盐铁之利则因财政不能绝源而长存。","figures":["贡禹","刘奭"],"place":"长安","state":"西汉","sources":["《汉书·贡禹传》","《汉书·食货志》"],"tags":["重农抑末","禁奢","贡禹"]},"related":["cn--b48--i01", "cn--b81--c01", "cn--b53--e01"]},
  {"id":"cn--b47--p01","track":"cn","year":-47,"yearApprox":false,"dim":"politics","weight":4,"title":"弘恭石显以中书用事","summary":"萧望之下狱自杀，周堪免官，宦者典枢机自此始。","detail":{"background":"元帝多疾、不亲万机，中书令弘恭、仆射石显久典枢机；帝重儒臣萧望之、周堪，欲以为辅，而忌外戚许、史。","process":"初元二年（前47）望之、堪劝帝罢恭、显，上书言中书为政本、宜以儒士居之；恭、显遂与许史相表里，劾望之「怀执意见、要功罔上」，请下廷尉。帝素不知廷尉即狱，望之仰药自杀，堪免官。","impact":"儒臣在禁中近习面前第一次公开的失败：自是公卿以下复畏恭、显，石显与五鹿充宗并用，士人清议与宦寺之争自此贯穿两汉，也促成后世以士人取代中书之制。","figures":["刘奭","萧望之","弘恭","石显"],"place":"长安","state":"西汉","sources":["《汉书·萧望之传》","《汉书·佞幸传》","《资治通鉴·汉纪》"],"tags":["中书宦官","萧望之死","士人与近习"]},"related":["cn--b51--c01", "cn--b22--p01", "cn--b45--p01"]},
  {"id":"cn--b47--x01","track":"cn","year":-47,"yearApprox":false,"dim":"explore","weight":2,"title":"郅支单于西徙坚昆","summary":"杀汉使江宰等，北走坚昆，与乌孙康居相攻。","detail":{"background":"匈奴内乱既久，呼韩邪南附称臣，郅支骨都侯单于自立于北庭，遣子入侍于汉，又杀汉使者江宰等四人以绝和。","process":"前47年前后，郅支引兵北走坚昆（今叶尼塞河上游一带），北击乌揭，西取大宛之地，与康居相结，数求汉归其侍子而汉不能制。","impact":"郅支西迁把汉匈冲突从中部草原移到中亚七河一带，也把一个匈奴单于送到康居、大宛之间；丝路北道因此生出新问题，为陈汤后来矫制发兵提供了理由。","figures":["郅支单于","江宰"],"place":"坚昆、康居（今叶尼塞河上游至哈萨克七河地区）","state":"西汉","sources":["《汉书·匈奴传》","《汉书·陈汤传》"],"tags":["郅支","坚昆","中亚交通"]},"related":[]},
  {"id":"cn--b46--a01","track":"cn","year":-46,"yearApprox":false,"dim":"art","weight":3,"title":"海昏侯墓出土金器简牍","summary":"南昌得列侯之制，黄金饼蹄与竹简书籍并出。","detail":{"background":"昌邑王刘贺以行淫废归故国，数年后徙封豫章海昏侯，就国而卒；其墓在鄱阳湖西岸、赣江之滨。","process":"2011至2015年考古发掘南昌海昏侯墓（大型带墓道、藏椁、便房之制），得金饼数百、马蹄金与麟趾金数十、五铢钱二十余万枚，又出竹简《论语》、《诗》类书、医书与日报、漆器、青铜灯、衣镜及真车马陪葬坑。","impact":"这是现存汉代列侯墓中保存最完整、随葬最丰的一座，实证了列侯葬制、酎金与黄金衡制的规模；简牍与衣镜画像则为经学扩散与早期人物画提供了新材料。","figures":["刘贺"],"place":"豫章海昏（今江西南昌新建区）","state":"西汉","sources":["海昏侯墓考古报告","《汉书·武五子传》"],"tags":["海昏侯墓","金饼","列侯葬制"]},"related":["cn--b74--p01", "cn--b51--a01"]},
  {"id":"cn--b46--f01","track":"cn","year":-46,"yearApprox":false,"dim":"figure","weight":1,"title":"海昏侯刘贺卒于国","summary":"就国豫章，削户三千，卒谥海昏侯。","detail":{"background":"刘贺废归昌邑，朝廷以其行淫乱削户三千；神爵三年（前59）徙封豫章为海昏侯，邑千户，不得朝聘，与故国吏民隔离。","process":"前46年前后贺卒于侯国，有司奏其罪当绝国，元帝以其先尝即位、旋复悔过，为定谥曰海昏侯；子代立，食邑如故，其国至东汉尚存。","impact":"一位在位二十七日的皇帝变成江南侯国的初封者，这一处置既见宣帝之后的政治宽简，也把昌邑一系的故吏彻底边缘化；海昏侯国成为汉制在豫章的支点之一。","figures":["刘贺"],"place":"海昏（今江西永修、新建一带）","state":"西汉","sources":["《汉书·武五子传》","《资治通鉴·汉纪》"],"tags":["刘贺","海昏侯","废王结局"]},"related":["cn--b74--p01", "cn--b46--a01"]},
  {"id":"cn--b45--p01","track":"cn","year":-45,"yearApprox":false,"dim":"politics","weight":3,"title":"外戚许史盛而京房讥灾异","summary":"帝舅史高为大司马，京房以异灾推原近习。","detail":{"background":"元帝以师傅外戚自辅，舅乐平侯史高以大司马车骑将军领尚书事，许伯、许嘉子弟并在侍中；同时日蚀、地震数至。","process":"初元、永光之间（前48—前33），京房以焦延寿易说推灾异，数上书言乱之本在近习，请考功课吏以应天变；永光二年（约前42）坐讥切为石显所构，弃市，妻徙边。","impact":"外戚与中书宦官同时得势，使儒臣两头受压；以灾异指斥近习自此成为士人唯一的进言通道，京房之死则是这条通道上的第一个著名牺牲。","figures":["京房","史高","石显"],"place":"长安","state":"西汉","sources":["《汉书·京房传》","《汉书·元帝纪》"],"tags":["外戚","灾异","京房"]},"related":["cn--b40--s01", "cn--b47--p01", "cn--b22--p01"]},
  {"id":"cn--b43--c01","track":"cn","year":-43,"yearApprox":false,"dim":"culture","weight":2,"title":"丞相匡衡说齐诗","summary":"无说诗匡鼎来，解人颐之语行于朝廷。","detail":{"background":"匡衡世习《齐诗》，家贫而力学，说诗冠一时；以经术自累迁至丞相，封乐乡侯，朝廷大议多引经义为断。","process":"建昭、竟宁之间（约前43—前34）衡为御史大夫、丞相，数引《诗》义傅经决事，说诗为世所称，时人为之语曰「无说诗，匡鼎来；匡说诗，解人颐」。","impact":"经学由家法变成士人升进的正途，解经者的名望可与官爵并称；以《诗》为决事之据，也确立了此后以经术缘饰吏事的样板，其弊则在章句破碎与经义附会。","figures":["匡衡"],"place":"长安","state":"西汉","sources":["《汉书·匡衡传》","《西京杂记》"],"tags":["齐诗","家法","以经饰吏"]},"related":["cn--b51--c01", "cn--b124--i01"]},
  {"id":"cn--b40--s01","track":"cn","year":-40,"yearApprox":false,"dim":"science","weight":2,"title":"京房立考功课吏之科","summary":"以课第能否为黜陟，替资历与举主之荐。","detail":{"background":"京房治《易》于焦延寿，好钟律、知音声，以六十四卦候气、分配昼夜寒温，以灾异验政事之得失。","process":"约前40年前后，房上书请试诸生以功课、令百官各效其功，以课最能否为黜陟；又自请试守郡，出为魏郡太守，行前再上书请得专辟吏、岁尽奏课，其议终为石显所阻。","impact":"以量化课第取代资历与举主之荐，是汉代吏治思想中罕见的制度设想；其法虽废，考功课吏与综核名实之论却自此成为批判吏治因循的常用命题。","figures":["京房","焦延寿"],"place":"长安及魏郡（今河北大名一带）","state":"西汉","sources":["《汉书·京房传》"],"tags":["考功课吏","易学","焦京之学"]},"related":["cn--b45--p01", "cn--b65--i01"]},
  {"id":"cn--b36--p01","track":"cn","year":-36,"yearApprox":false,"dim":"politics","weight":2,"title":"元帝劳军渭桥议省戍卒","summary":"北边无事，天子自劳士众，议罢边备吏卒。","detail":{"background":"呼韩邪内附以后，北边自朔方至敦煌数世不见烟火之警，吏民逸于田作；单于复上书愿朝，朝臣议其费。","process":"建昭三年（前36）前后，元帝幸上林、临渭桥，亲劳将帅士众，车骑填咽；诏郡国举茂才，选博士弟子，议省边郡戍卒与吏员，以宽转输之费。","impact":"劳军、省戍、举贤三事并下，把北边无事经营为太平的表征；这类符号性政治活动的增多，正是元成之际朝政由实务转向典礼与符命的写照。","figures":["刘奭"],"place":"长安及北边郡","state":"西汉","sources":["《汉书·元帝纪》","《汉书·匈奴传》"],"tags":["劳军","省戍","太平叙事"]},"related":["cn--b49--p01", "cn--b33--p02"]},
  {"id":"cn--b36--m01","track":"cn","year":-36,"yearApprox":false,"dim":"military","weight":3,"title":"陈汤矫制诛郅支单于","summary":"假节发戊己校尉屯田兵入康居，斩郅支。","detail":{"background":"郅支单于西徙坚昆后与康居为婚，屡攻乌孙、大宛，又杀辱汉使；西域都护不能制，朝廷以道远不肯出。","process":"建昭三年（前36）西域都护甘延寿、副校尉陈汤矫发戊己校尉屯田吏卒与车师等六国兵，分两道逾葱岭，围郅之于都赖水上，斩阏氏、太子、名王以下千五百余级；传首长安，悬槁街十日。","impact":"明犯强汉者虽远必诛一语自此而定型，汉军威第一次深入中亚七河；然矫制之功与赏罚之议相难数十年，暴露出都护体制下中央对边将既用又防的两难。","figures":["陈汤","甘延寿","郅支单于"],"place":"康居都赖水（今哈萨克塔拉兹一带）","state":"西汉","sources":["《汉书·陈汤传》","《资治通鉴·汉纪》"],"tags":["郅支","矫制","都赖水"]},"related":["cn--b47--x01", "cn--b60--i01"]},
  {"id":"cn--b33--p01","track":"cn","year":-33,"yearApprox":false,"dim":"politics","weight":3,"title":"元帝崩成帝立王氏始贵","summary":"竟宁元年元帝崩，太子骜立，舅王凤秉政。","detail":{"background":"竟宁元年（前33）五月元帝崩于未央宫，在位十六年，年四十二；皇太子刘骜即位，是曰成帝；帝舅史高与许、史、王氏俱以外家进。","process":"六月成帝以舅王凤为卫尉侍中，阳朔中迁大司马大将军领尚书事，王谭、王商、王立、王根、王逢时同日封侯，号五侯；刘向以宗室老儒召，典校禁中秘书。","impact":"元帝一朝外戚与宦寺相参的格局被单方面打破，外戚王氏自此独大，历元、成、哀、平四世不衰；后来的限田之议与禅代之言，都从这一权力结构里长出。","figures":["刘骜","王凤","刘向"],"place":"长安","state":"西汉","sources":["《汉书·元帝纪》","《汉书·成帝纪》","《汉书·外戚传》"],"tags":["成帝即位","五侯","校书"]},"related":["cn--b47--p01", "cn--b26--p01", "cn--b26--i01"]},
  {"id":"cn--b33--p02","track":"cn","year":-33,"yearApprox":false,"dim":"politics","weight":4,"title":"王嫱配呼韩邪号宁胡阏氏","summary":"以良家子妻单于，边城不闭，改元竟宁。","detail":{"background":"呼韩邪单于既朝甘泉，复请和亲，愿保塞上谷以西至敦煌，请汉罢边备塞吏卒；汉公卿以为不可卒许。","process":"竟宁元年（前33），后宫良家子王嫱字昭君，入宫数岁不得见，乃自请掖庭令求行；帝以赐单于，单于号曰宁胡阏氏，上书愿世世保塞；汉因改元曰竟宁，以志边塞之安。","impact":"和亲自此由对等国家之礼转为册封君臣之仪：汉得竟宁之名，匈奴得公主与缯絮之利，北边得息肩；而画工弃市一类传说，使王嫱成为后世文学中宫怨与和戎最持久的形象。","figures":["王嫱","呼韩邪单于","刘奭"],"place":"长安及匈奴单于庭","state":"西汉","sources":["《汉书·元帝纪》","《汉书·匈奴传》","《西京杂记》"],"tags":["昭君出塞","和亲","竟宁"]},"related":["cn--b49--p01", "cn--b55--m01"]},
  {"id":"cn--b31--p01","track":"cn","year":-31,"yearApprox":false,"dim":"politics","weight":2,"title":"成帝微行而委政王凤","summary":"数微行过市里，军国一事决于大司马。","detail":{"background":"成帝善修容仪而不好史，多畜燕乐；建始、河平之间，外家王氏与赵飞燕、李氏之宠渐盛。","process":"前31年前后，帝数微出私谒长者，过市里、斗鸡走马，张放、淳于长等以幸臣侍中用事；王凤领尚书事，奏免御史大夫、大臣多其所斥，公卿守文奉法而已。","impact":"皇权的私人化与政务的代理化同时发生，外戚专政、幸臣乱政与士人上书三条线并行；薛宣、翟方进一辈名臣只能以循职自守，汉制的弹性由此渐失。","figures":["刘骜","王凤","张放"],"place":"长安","state":"西汉","sources":["《汉书·成帝纪》","《汉书·叙传》","《资治通鉴·汉纪》"],"tags":["微行","外戚专政","幸臣"]},"related":["cn--b33--p01", "cn--b22--p01"]},
  {"id":"cn--b29--i01","track":"cn","year":-29,"yearApprox":false,"dim":"institution","weight":2,"title":"黄霸式化尤异为天下最","summary":"以治行尤异赐爵关内侯，课最先教化。","detail":{"background":"宣元以来以条课课吏，而郡国长吏多文法吏，能兴教化、明礼让者寡；上以治行效验为高，故有尤异之科。","process":"前29年前后，颍川太守黄霸以治行尤异，赐爵关内侯、黄金百斤，征为丞相；诏郡国举茂才、孝弟，以教化最多为课首，乡三老、力田岁有常科。","impact":"把教化成效列入考课最上，是汉代循吏政治的极致形态；但其赏易为虚名所冒，阳郡计薄之类欺罔随之而生，名实之辨自此成为吏治的老问题。","figures":["黄霸","刘奭"],"place":"颍川（今河南禹州一带）","state":"西汉","sources":["《汉书·循吏传》","《汉书·宣帝纪》"],"tags":["循吏","教化考课","条课"]},"related":["cn--b65--i01", "cn--b64--p01"]},
  {"id":"cn--b28--s01","track":"cn","year":-28,"yearApprox":false,"dim":"science","weight":2,"title":"浑仪与历数之器渐备","summary":"治历者并校疏密，浑象之制始具规模。","detail":{"background":"太初历行用既久，朔晦弦望与天象多不合，宣元以来诏治历者并校诸家疏密，历数须与仪器相辅。","process":"河平（前28—前25）之间，待诏治历者以浑仪校日月行度、课蚀分数，历数与仪器始相须为用；其后耿寿昌、刘歆相继推校，至东汉遂有三统、四分诸历。","impact":"浑天仪器由粗具规模到可复验的量化，是历法改革的物质条件；张衡的浑天仪与漏刻、东汉四分历的更造，都承接这一系器物与算法而下。","figures":["耿寿昌","刘歆"],"place":"长安","state":"西汉","sources":["《汉书·律历志》","《晋书·天文志》"],"tags":["浑仪","治历","课蚀"]},"related":["cn--b104--s01", "cn--b104--s02"]},
  {"id":"cn--b26--c01","track":"cn","year":-26,"yearApprox":false,"dim":"culture","weight":3,"title":"刘向撰新序说苑","summary":"采传记行事，以类相从，成劝诫之书。","detail":{"background":"成帝时外戚盛、宴乐多，刘向以宗室老儒典校秘书，屡上书言灾异与王氏之渐，言不见用。","process":"约前26年前后，向辑先秦以来传记行事，删取指意，成《新序》《说苑》数十篇，又奏《列女传》八篇以戒后庭与近习；其书以类相从，篇终系以君子曰。","impact":"这是中国最早的劝诫类书编纂：把儒术从章句转成可征引的政治伦理语汇，其体例直接影响《白虎通》与后世类书；文风由铺陈之赋转为议论之文，也是汉散文过渡的一环。","figures":["刘向"],"place":"长安","state":"西汉","sources":["《汉书·楚元王传》","《说苑》","《七略》辑校"],"tags":["新序说苑","劝诫之文","类书"]},"related":["cn--b26--i01", "cn--b22--p01"]},
  {"id":"cn--b26--i01","track":"cn","year":-26,"yearApprox":false,"dim":"institution","weight":4,"title":"诏诸儒校禁中秘书","summary":"河平三年刘向等分门校书，条其篇目而奏之。","detail":{"background":"河平三年（前26）以禁中秘书多残亡散逸、简编脱乱，诏光禄大夫刘向与谒者、乘舆书吏共校之。","process":"刘向校经传诸子诗赋，步兵校尉任宏校兵书，太史令尹咸校数术，侍医李柱国校方技；每一书已，向辄条其篇目、撮其指意，录而奏之；向卒，哀帝复令其子刘歆卒父业，遂据以成《七略》。","impact":"中国的目录学与校勘学由此诞生：一人成书则一篇叙录的体例为后世四库提要所承，所校之本与部次即成《汉书·艺文志》的骨架；先秦典籍之多得传于今，全赖此役。","figures":["刘向","刘歆","任宏"],"place":"长安未央宫禁中","state":"西汉","sources":["《汉书·艺文志》","《汉书·楚元王传》"],"tags":["校书","目录学","七略"]},"related":["cn--b26--c01", "cn--b51--c01", "cn--b6--c01"]},
  {"id":"cn--b26--p01","track":"cn","year":-26,"yearApprox":false,"dim":"politics","weight":2,"title":"五侯并封与王章之祸兆","summary":"王谭、王商、王根、王立同日受封为侯。","detail":{"background":"河平、阳朔之间成帝崇厚外家，大司马王凤权位日盛，王谭、王商、王根、王立、王逢时并以舅弟贵显。","process":"约前26年，封王谭为平阿侯、王商为成都侯、王立为红阳侯、王根为曲阳侯、王逢时为高平侯，五人同日受封，宾客满朝；京兆尹王章数以直谏忤凤，刘向因之上封事言王氏应灾异。","impact":"以同日分封自固外家，是外戚专政的组织形式；王章之死、刘向之废，使讥切近习由汉廷常例变为高危之事，清议从此转入图谶与符命一类的通道。","figures":["王凤","王章","刘向"],"place":"长安","state":"西汉","sources":["《汉书·元后传》","《汉书·王章传》"],"tags":["五侯","外戚分封","清议"]},"related":["cn--b22--p01", "cn--b33--p01"]},
  {"id":"cn--b24--p01","track":"cn","year":-24,"yearApprox":false,"dim":"politics","weight":3,"title":"成都侯王商以讪怏死","summary":"大司马凤构之，帝疑丞相商，呕血而死。","detail":{"background":"王商以帝舅为丞相，持重有威，王凤忌其不附己，使其党劾商以闺门之事；商素行谨，朝廷疑之。","process":"阳朔（前24—前20）初，王凤使御史大夫张忠奏商，削其爵；商召诣廷尉，未及对簿，呕薨而死，谥戾侯；凤之权愈震，公卿以下侧目。","impact":"外戚内部也须以禁中与廷尉相倾轧，说明王氏之权已非皇帝所能调节；丞相去位而大司马益重，是西汉末权臣与宰相地位互换的关健一段。","figures":["王凤","王商"],"place":"长安","state":"西汉","sources":["《汉书·王商传》","《汉书·元后传》"],"tags":["外戚内争","丞相","大司马"]},"related":["cn--b26--p01"]},
  {"id":"cn--b22--p01","track":"cn","year":-22,"yearApprox":false,"dim":"politics","weight":4,"title":"王章以灾异讼王凤下狱死","summary":"上书言凤不可任，帝不纳，坐大不敬死。","detail":{"background":"自河平以来日蚀、地震数至，议者多以为王氏并盛之应；京兆尹王章刚直敢言，与宗正刘向相善。","process":"前22年前后，章以灾异上封事，言王凤不可专任，帝召凤示之，凤因而称病笃；帝优诏留之，章由是见疏，后坐事下廷尉死，妻子徙合浦。","impact":"章死后公卿以下皆侧目于凤，言路尽变；刘向、辛庆忌之徒不复以书触之，而汉室的合法性危机只能以图谶与符命表达，至哀、平之间遂成不可遏之流。","figures":["王章","王凤","刘向"],"place":"长安","state":"西汉","sources":["《汉书·王章传》","《汉书·元后传》","《资治通鉴·汉纪》"],"tags":["王章之狱","言路","灾异"]},"related":["cn--b26--p01", "cn--b26--c01"]},
  {"id":"cn--b18--p01","track":"cn","year":-18,"yearApprox":false,"dim":"politics","weight":2,"title":"谷永数上疏言外家之祸","summary":"以灾异推外戚，辞切而身附王氏，言不见用。","detail":{"background":"成帝无嗣而好燕乐，赵飞燕、李氏姊妹贵震后宫，外家王氏专政于朝，丁、傅继起于外，灾异连年不绝。","process":"元延、绥和之间（约前12至前7年），谷永数上疏言帝王宜省声色、广继嗣、远外家，辞指甚切；然其所以屡得进言，实由王氏所引，故所言王章、许班之党，议者非之。","impact":"以灾异说政已沦为外戚与幸臣互相攻讦的工具：谷永言外家之祸而身出外家之门，这种错位说明经学谏诤已失其独立位置，士人乃渐转趋图谶与禅让之说。","figures":["谷永","刘骜"],"place":"长安及三辅","state":"西汉","sources":["《汉书·薛宣传》","《汉书·百官公卿表》"],"tags":["循吏","条教","文牍治理"]},"related":["cn--b29--i01", "cn--b64--p01"]},
  {"id":"cn--b15--p01","track":"cn","year":-15,"yearApprox":false,"dim":"politics","weight":3,"title":"薛宣为丞相条奏吏治","summary":"以能吏居相位，条郡国便宜，务在举贤省事。","detail":{"background":"永始以来郡国以督责为治，民多轻犯法而吏缘为奸；薛宣以治行累迁左冯翊、御史大夫，遂代为丞相。","process":"永始二年（前15）薛宣代翟方进为丞相，封高阳侯；条奏郡国吏治不便者数事，务在举贤、省事、薄刑、劝农，以二千石为纲纪，责属县以条教课最，而不得苛扰。","impact":"循吏政治至此已成一种文牍化的技术治理：条教、课最、簿书相循，能息一时之狱讼而不能抑兼并；宣旋以广汉太守奏免，能吏之不相容于权门，亦可见汉制之穷。","figures":["薛宣","刘骜"],"place":"长安及郡国","state":"西汉","sources":["《汉书·薛宣传》","《汉书·百官公卿表》"],"tags":["灾异","外戚","谏诤之困"]},"related":["cn--b22--p01", "cn--b6--c01"]},
  {"id":"cn--b15--p02","track":"cn","year":-15,"yearApprox":false,"dim":"politics","weight":3,"title":"翟方进以灾异策免自杀","summary":"荧惑守心，郎官言其咎在丞相，即日自杀。","detail":{"background":"成帝以来灾异连属，日蚀、地震、荧惑守心之占相接，议者多以王氏应之；故事三公每以灾异策免，而荧惑之占尤为切至。","process":"永始二年（前15）十二月荧惑守心，郎官行秘者言其变宜应在大臣，有司奏丞相翟方进奉职不谨、议明圣之术不实，策免相位，赐黄金百斤、酒脯；方进即日自杀。","impact":"以经学吏业致位丞相而以灾异死其位，说明灾异课三公已成朝中无人敢否定的制度；此后师丹、孔光、王莽皆以灾异与符命进退，相位成了权门与天命之间的缓冲。","figures":["翟方进","刘骜"],"place":"长安","state":"西汉","sources":["《汉书·翟方进传》","《汉书·天文志》"],"tags":["灾异","策免","三公"]},"related":["cn--b15--p01", "cn--b6--c01"]},
  {"id":"cn--b7--i01","track":"cn","year":-7,"yearApprox":false,"dim":"institution","weight":3,"title":"师丹请限田限奴婢","summary":"诏诸侯王列侯吏民名田各以顷亩为限，议竟寝。","detail":{"background":"哀帝初即位，外家丁、傅新贵，关东流民与奴婢市贩之盛百倍于武帝之末；大司空师丹在位，以为非抑兼并无以安民。","process":"绥和二年（前7）师丹与丞相孔光奏请：诸侯王、列侯、关内侯、吏民名田皆毋得过三十顷，诸侯王奴婢毋过二百人，列侯、公主百人，关内侯、吏民三十人，期尽三年，犯者没入官；诏书已下，而丁、傅、故贵之家不便，遂寝。","impact":"这是中国古代第一次由中央明令限制土地与奴婢的占有量，也是王莽王田之令的直接前例；其失败表明在豪族与外戚并起的结构里，限田之法终无从执行。","figures":["师丹","刘欣"],"place":"长安","state":"西汉","sources":["《汉书·食货志》","《汉书·师丹传》","《资治通鉴·汉纪》"],"tags":["限田议","奴婢","师丹"]},"related":[]},
  {"id":"cn--b6--c01","track":"cn","year":-6,"yearApprox":false,"dim":"culture","weight":3,"title":"刘歆请立古文经博士","summary":"移让太常博士，争立毛诗逸礼古文。","detail":{"background":"刘歆校秘书，见《左氏春秋》、《毛诗》、《逸礼》、《古文尚书》皆在秘府，以为此皆丘明、孔氏之旧文；时博士专守今文家法。","process":"约前6年前后，歆移书让太常博士，请为《左氏春秋》、《毛诗》、《逸礼》、《古文尚书》更置博士；诸博士以为非先君所立，不可复加，朝臣多非歆者，歆惧出，为河内五官太守。","impact":"今古文之争自此公开化，经学由家法之学转为文献与义理之争；古文经学所携的周官、明堂、井田之说随之入世，为王莽摄政提供了制度蓝本与经典依据。","figures":["刘歆"],"place":"长安","state":"西汉","sources":["《汉书·楚元王传》","《汉书·刘歆传》","《汉书·艺文志》"],"tags":["古文经","今古文之争","博士"]},"related":["cn--b26--i01"]},
  {"id":"cn--b6--e01","track":"cn","year":-6,"yearApprox":false,"dim":"economy","weight":3,"title":"五铢钱与市易之盛","summary":"天下效五铢，郡国铸钱者多，谷贱钱重。","detail":{"background":"自元鼎行上林三官五铢以来，钱之重重大小如一，私铸稍息；至成哀之间，谷贱钱少之议与珠金银玉之积并起。","process":"约前6年前后，谷贱伤农、钱少不足用，议者或请更铸大钱以实边用；同时京师贵戚与贾竖以钱为市，长安、洛阳的市肆、赊贷之业并起，民赋与奴婢之价皆以钱计。","impact":"货币化已把汉代社会推到以钱计物、以钱计税的地步：钱重则谷贱伤农，钱轻则奸铸复起，这一两难至王莽货币改革而彻底爆发，成为新室速亡的原因之一。","figures":["刘欣"],"place":"长安及郡国","state":"西汉","sources":["《汉书·食货志》","《盐铁论》","西汉五铢钱范"],"tags":["五铢钱","钱谷轻重","市易"]},"related":["cn--b113--e01"]},
  {"id":"cn--b2--p01","track":"cn","year":-2,"yearApprox":false,"dim":"politics","weight":3,"title":"董贤断袖与哀帝之宠","summary":"宠臣董贤年二十二位至三公，帝欲禅之。","detail":{"background":"哀帝倦怠政事，宠爱幸臣董贤，出则参乘、入则御坐，欲以顾命辅政；其时外家丁、傅已替，王氏退处里第。","process":"约前2年至前1年，董贤年二十二由黄门郎迁至大司马，封高安侯，赏赐以亿计，为起第于长安，将作大匠亲治其居，武库禁兵、尚方珍器皆入董氏；帝且欲以玺绶属之。","impact":"以幸臣取代外戚、以私宠压制公论，等于同时开罪所有既得集团；故哀帝崩之日王莽即日收捕丁、傅，并召还王氏，董贤与妻当日自杀，家财薄计四万余万入于县官。","figures":["董贤","刘欣","王莽"],"place":"长安","state":"西汉","sources":["《汉书·佞幸传》","《汉书·王莽传》","《资治通鉴·汉纪》"],"tags":["董贤","幸臣","外戚代兴"]},"related":["cn--b1--p01"]},
  {"id":"cn--b1--p01","track":"cn","year":-1,"yearApprox":false,"dim":"politics","weight":3,"title":"王莽就封新都安汉公","summary":"退处数岁复起，以大司马领尚书事还朝。","detail":{"background":"成帝崩，莽以王太后（政君）侄为大司马，旋为哀帝外家丁、傅所黜，就第于新都；一时朝臣多为言其冤。","process":"前1年至前1年之间，莽就新都侯国，杜门自守；元寿元年（前2）日蚀，朝臣举莽与孔光，征还，拜为大司马，尊号曰安汉公（居摄以前）；太后临朝，政归禁中。","impact":"一次退让反而成就了道德资本，这是西汉末政治的奇异逻辑；莽以礼法、节俭、让爵为具，得士人之望而居权位，外戚由专权转为篡代的准备已近完成。","figures":["王莽","刘欣","孔光"],"place":"长安及新都（今河南南阳一带）","state":"西汉","sources":["《汉书·王莽传》","《资治通鉴·汉纪》"],"tags":["王莽","安汉公","外戚"]},"related":["cn--b2--p01"]},
  {"id":"cn--1--p02","track":"cn","year":1,"yearApprox":false,"dim":"politics","weight":2,"title":"元始之际符命与四夷称臣","summary":"以瑞命边功累加上尊号，改制之议渐成。","detail":{"background":"自王莽领尚书事，黄支、苏来摩之类远物与瑞命日陈于廷，边遣使说乌孙、匈奴，使咸上寿称臣，以成中兴与受命之象。","process":"元始初，益州塞外种人献犀象、大雀，匈奴单于上书言莽功德、愿无得报，西域诸国并侍子于长安；有司据瑞应、符命奏上安汉公之号，又请以元始纪年、定明堂、辟雍、经学之制。","impact":"符命与瑞应以中央的名义被批量制造出来：纪年、尊号、边功与礼制合成一套合法性话语，此后的禅代与告命皆沿此程序，王莽是把它第一次做得完整的人。","figures":["王莽","刘衎"],"place":"长安","state":"西汉","sources":["《汉书·王莽传》","《汉书·地理志》"],"tags":["符命","尊号","瑞应"]},"related":[]},
  {"id":"cn--2--i01","track":"cn","year":2,"yearApprox":false,"dim":"institution","weight":2,"title":"元始间起明堂辟雍","summary":"于南郊立明堂、辟雍，三雍之制始备。","detail":{"background":"自武帝以来议明堂不一，元帝、王莽之际儒者据《周官》《王制》之说，欲以三雍为受命改正之具。","process":"元始二年前后，莽奏起明堂、辟雍、灵台于长安南郊，为学者筑舍万区，定昏礼、乡射之仪；太常、博士与诸生会课于辟雍之中，简阅大合于明堂之上。","impact":"三雍自此成为帝国最高礼制与教育的空间型式，洛阳东汉承之，其影响直至魏晋南北朝；同时它把经学中的周制想象第一次变成实际的都城规划。","figures":["王莽","刘衎"],"place":"长安南郊","state":"西汉","sources":["《汉书·王莽传》","《三辅黄图》","汉长安城南郊遗址发掘"],"tags":["明堂辟雍","礼制建设","周官之学"]},"related":["cn--5--c01", "cn--9--i01"]},
  {"id":"cn--5--p01","track":"cn","year":5,"yearApprox":false,"dim":"politics","weight":3,"title":"元后崩与王莽加九锡","summary":"王政君死，葬合渭陵；莽受九锡，位在三公上。","detail":{"background":"元始五年莽妻以女为后，其姑王政君年八十九而崩；孝宣后与元后之间，王氏之权尽归莽。","process":"5年二月王政君崩，与元帝合葬渭陵，莽亲执丧事，调发四辅、三公、郡国材料，起坟甚高；其年莽加九锡，衣服、车骑、宫卫拟于天子，与太皇太后共定策。","impact":"葬礼之奢是政治信号的公开化：王氏与汉室在礼制上已无差等；一年之后代汉之局，正是在这种仪注与符命相累积的过程中被完成的。","figures":["王莽","王政君"],"place":"长安及渭陵","state":"西汉","sources":["《汉书·元后传》","《汉书·王莽传》"],"tags":["元后之葬","九锡","礼制逾等"]},"related":["cn--b1--p01", "cn--9--p01"]},
  {"id":"cn--5--c01","track":"cn","year":5,"yearApprox":false,"dim":"culture","weight":4,"title":"元始五年诸生会集考论","summary":"征天下通一经及逸礼古书者数千人，会集阙下。","detail":{"background":"莽欲以周官、礼经为改制张本，征通逸礼、古书、毛诗、周官、尔雅、天文、律历、谶记、小学者至京师。","process":"5年诏征天下学者凡数千人，各以同类集于阙下记说，刘歆主其事；以《周官》得见经传之助，卒立《周官》之经，莽据之以定井田、五均、爵制、封域之说。","impact":"这是经学与政治合流的关键一步：出土文献与古文经被直接编成改制的法律，其后果不仅是经学之争，更使国家制度的蓝本第一次完整取自经典文本，而代价是失败的改革。","figures":["刘歆","王莽"],"place":"长安","state":"西汉","sources":["《汉书·刘歆传》","《汉书·王莽传》","《周礼》"],"tags":["周官","征集群儒","以经改制"]},"related":["cn--b6--c01", "cn--9--i01", "cn--9--i02"]},
  {"id":"cn--6--p01","track":"cn","year":6,"yearApprox":false,"dim":"politics","weight":3,"title":"居摄践祚与孺子之立","summary":"莽摄皇帝位，改元居摄，欲代汉自明。","detail":{"background":"帝崩无嗣，择宣帝玄孙婴年二岁立之，号孺子；莽以太后诏居摄，如周公故事，而自名其年曰居摄。","process":"6年莽即天子位、南面朝诸侯，以子安汉公之礼自处，称摄皇帝；改居摄元年，建明堂、行宗祀，以《周书》王若曰之文为据；刘歆、王舜等共定其仪，有司奏言莽宜如周公。","impact":"居摄是汉代政治语言中最露骨的一次周公模仿：它把摄政合法化到称帝的最后一步，但也激起翟义起兵与宗室之怨，使此后两年间朝野共识由赞成摄政变成反对代汉。","figures":["王莽","刘婴"],"place":"长安","state":"西汉","sources":["《汉书·王莽传》","《资治通鉴·汉纪》"],"tags":["居摄","孺子","周公之喻"]},"related":["cn--5--p01", "cn--7--m01"]},
  {"id":"cn--7--m01","track":"cn","year":7,"yearApprox":false,"dim":"military","weight":4,"title":"翟义起兵与东方三郡响应","summary":"东郡太守翟义举兵，众十余万，旋败死。","detail":{"background":"莽居摄，宗室与郡县多不服；东郡太守翟义为故丞相翟方进少子，与严尤、霍宣等结谋，以讨莽为名。","process":"7年九月翟义起于东郡，移檄东郡、淮阳、汝南之兵众十余万，三辅之民数千人响应；莽效《周书·大诰》作书自解，遣王邑等将兵东征，义败死，其党尽族，独刘歆、孔光不以为罪。","impact":"这次兵变使王莽对郡县豪吏失去信任，转向以符命、酷吏与频繁改制来重建控制；同时它也是汉室最后的官方勤王尝试，此后讨莽的旗帜便从士大夫转移到饥民与铜马之众。","figures":["翟义","王莽","王邑"],"place":"东郡及三辅","state":"西汉","sources":["《汉书·翟方进传》","《汉书·王莽传》"],"tags":["翟义起兵","居摄危机","郡县豪吏"]},"related":["cn--b15--p02", "cn--6--p01", "cn--9--p01"]},
  {"id":"cn--9--p01","track":"cn","year":9,"yearApprox":false,"dim":"politics","weight":5,"title":"王莽即真定国号曰新","summary":"受孺子之禅，定有天下之号曰新，改元始建国。","detail":{"background":"居摄三年符命大起，白石丹书、金匮图谶出于延陵、扶风；莽以天命、人心与图纬之说即真。","process":"9年正月莽拜祠高庙，授孺子玺绶，以戊子代甲子，定国号曰新，改元始建国，降汉帝为定安公，以女妻之；追谥黄帝、舜为始祖，以周、齐之后为二王后，尽易汉家制度、官名、服色。","impact":"新室代汉是中国历史上第一次以符命、禅让与经典制度蓝本三结合的政权更替；它以和平方式取得正统，却因改制过密、名实交丧，十五年间便使天下瓦解，遂成此后禅代最被反复讨论的先例。","figures":["王莽","刘婴"],"place":"长安","state":"新","sources":["《汉书·王莽传》","《资治通鉴·汉纪》"],"tags":["新莽代汉","符命","始建国"]},"related":["cn--7--m01", "cn--9--i01", "cn--23--p01"]},
  {"id":"cn--9--i01","track":"cn","year":9,"yearApprox":false,"dim":"institution","weight":5,"title":"王田令禁买卖奴婢","summary":"更名天下田曰王田，奴婢曰私属，皆不得卖买。","detail":{"background":"汉末豪强兼并不止，贫民卖子为奴婢，朝廷不能禁；莽据《周官》井田之说，欲以复古之法为天下齐民。","process":"9年下诏：更名天下田曰王田，一家男丁不满八口而田过一井者，以余田授九族乡党；天下奴婢皆曰私属，不得卖买；犯者投诸四裔，以御魑魅；行之五年而民不便，至12年遂罢王田、奴婢之禁，得卖如故。","impact":"这是中国历史上唯一一次以恢复井田为名的全国土地国有令；其法虽止行三年而废，却定下此后一千八百年关于土地与奴婢的根本争论，也使新室永远失去了地主与商人的支持。","figures":["王莽"],"place":"长安及天下郡县","state":"新","sources":["《汉书·王莽传》","《汉书·食货志》"],"tags":["王田","私属","土地国有"]},"related":["cn--b7--i01", "cn--9--i02", "cn--17--p01"]},
  {"id":"cn--9--i02","track":"cn","year":9,"yearApprox":false,"dim":"institution","weight":4,"title":"五均六筦官市赊贷","summary":"于六郡立五均官，统酒、盐、铁、铸钱与名山大泽。","detail":{"background":"汉世富商大贾以逐利相高，平准、均输之法自成帝、哀帝以后渐弛；王莽欲以官市齐物价、抑兼并，而府库之入仰于此。","process":"9年诏长安及洛阳、邯郸、临淄、宛、成都立五均司市、钱府官：以每月物价上中下三等平之，民欲卖者官为收，欲买者贱则取之；又设赊贷，贫民欲得赊钱者以月息三十取一；兼行酒、盐、铁、铸钱、名山大泽之征，是谓六筦。","impact":"王莽把财政从税赋改造为经营，这是古代中国最大胆的官营市场实验；其法以能吏与计簿为命脉，吏缘为奸，徒为烦扰，反使农商俱废，故史称农商失业、食货俱废。","figures":["王莽","桑弘羊遗法"],"place":"长安及五都市","state":"新","sources":["《汉书·食货志》","《汉书·王莽传》"],"tags":["五均六筦","官市赊贷","市场管制"]},"related":["cn--9--i01", "cn--9--e01", "cn--17--p01"]},
  {"id":"cn--9--e01","track":"cn","year":9,"yearApprox":false,"dim":"economy","weight":4,"title":"宝货制与刀布之复","summary":"更黄金曰黄石，作龟宝、布货十品之目。","detail":{"background":"汉专用五铢钱，民间便之，七十一场不变；王莽以古者货贝、刀布之文为据，欲以繁复的货币等级收民之藏而别其轻重。","process":"9年废五铢而行宝货：黄金重一斤直万钱，朱、白、苍黄、赤墀凡五物；银为二品；铜贝三十品，大、壮、中、小、幼凡五品；又作小直千、中直五百、幺中三百、壮百、小五十凡五十八品；民以为不便，私用五铢，遂禁天下不得挟钱，铸钱者罪至死。","impact":"货币由繁而乱、由乱而废：一、二十余年间四次改币，币值与重量不符、名号繁不可晓，百姓两为奸巧，农商失业；新莽的货币试验成为中国货币史上最著名的失败案例。","figures":["王莽"],"place":"长安及郡国","state":"新","sources":["《汉书·食货志》","《汉书·王莽传》","新莽货币实物"],"tags":["宝货制","刀布","币制紊乱"]},"related":["cn--9--i02", "cn--b6--e01", "cn--14--e01"]},
  {"id":"cn--10--i01","track":"cn","year":10,"yearApprox":false,"dim":"institution","weight":3,"title":"改官名与五等爵","summary":"大司农羲和、水衡虞衡，尽易汉家百官之名。","detail":{"background":"莽以《周官》《王制》之文为据，欲使官称与古制相合；于是府、寺、卿、大夫之名一变于天下。","process":"10年置四辅、四将、九卿、二十七大夫、八十一元士，以大司农羲和、少府共己、水衡虞衡、太仆趣马名官；郡太守曰大尹、都尉曰太尉，县令长分五等，爵曰公侯伯子男；五等之封行于贵近，而吏民苦其簿书。","impact":"名称与印绶的大改使郡县文书、仓卒驿传一时皆乱，官制在复古的名义下反而失去可执行性；此等制度虚转，是新室政令不行于天下的直接原因之一。","figures":["王莽"],"place":"长安及郡国","state":"新","sources":["《汉书·百官公卿表》","《汉书·王莽传》"],"tags":["官名复古","五等爵","文书之乱"]},"related":["cn--9--p01", "cn--9--i01"]},
  {"id":"cn--11--x01","track":"cn","year":11,"yearApprox":false,"dim":"explore","weight":3,"title":"易匈奴名与征高句丽","summary":"分匈奴为十五单于，改高句丽为王下，边患遂起。","detail":{"background":"莽以四夷称臣为义，不能容单于与汉敌体之旧；又以乌孙、匈奴和亲之号多易，欲以名分制之。","process":"11年使五威将王骏等至匈奴，以新室印绶易汉故玺，改匈奴为降奴服于，又分其国地、立呼韩邪子孙十五人俱为单于；发高句丽兵击匈奴，候擅令改其王为下，其众遂亡塞外，与辽东兵相杀。","impact":"名分之争在北方成了实际的挑衅：自是匈奴数入边，并护乌桓、羌胡，北边自云中至辽东数千里萧然，士民转徙；新室之亡，实自边祸启之。","figures":["王莽","王骏"],"place":"长安及匈奴、高句丽","state":"新","sources":["《汉书·匈奴传》","《汉书·王莽传》","《汉书·地理志》"],"tags":["名分外交","北边之患","高句丽"]},"related":["cn--1--p02", "cn--b33--p02", "cn--b47--x01"]},
  {"id":"cn--12--i01","track":"cn","year":12,"yearApprox":false,"dim":"institution","weight":2,"title":"禁挟五铢与废王田令","summary":"民私用五铢钱，罪至徙；王田、奴婢之禁亦弛。","detail":{"background":"宝货既行而民间不用，五铢久便而法令严禁；王田之令又使卖买相冒、吏不能禁，改制之政已自屈于俗。","process":"12年以民不便，诏废王田、奴婢之禁，得卖买如故；惟下吏民不得私挟五铢、黄金，违者以罪罪之，公卿以下至吏民坐铸钱、挟钱抵罪者甚众。","impact":"三年之内，井田之说废、挟钱之禁令行，改制由复古的理想退为财政的搜括；新室自此失去士人与富民的支持，而苛法与转输之役并至，天下遂乱。","figures":["王莽"],"place":"长安及郡国","state":"新","sources":["《汉书·食货志》","《汉书·王莽传》"],"tags":["废王田","挟钱之禁","政策退却"]},"related":["cn--9--i01", "cn--9--e01", "cn--17--p01"]},
  {"id":"cn--13--d01","track":"cn","year":13,"yearApprox":false,"dim":"disaster","weight":3,"title":"河南魏郡大疫与蝗","summary":"郡国大疫，飞蝗从东方来，民多饿死。","detail":{"background":"新室改制既密，北边转输又急，加以河决郡国、师出无时；关东之民先困于役，复因于疫，户口耗减实始于此。","process":"13年前后，河南、大司农部、魏郡、陈留大疫，又有飞蝗自东方起，蔽天而下，所集无处；吏民因疫死者众，郡国仓廪不能赈，流民入关者且万人。","impact":"天灾与政弊相因为害：大疫使编户与田租之入骤减，边兵与转输反增，遂为天凤以后四方并起的局面定下了基调，也是绿林赤眉得以扩员的直接原因。","figures":["王莽"],"place":"河南、魏郡、陈留","state":"新","sources":["《汉书·五行志》","《汉书·王莽传》"],"tags":["大疫","飞蝗","流民"]},"related":["cn--17--p01", "cn--18--m01"]},
  {"id":"cn--14--e01","track":"cn","year":14,"yearApprox":false,"dim":"economy","weight":3,"title":"再改货布货币之制","summary":"更作货布、货泉二品，废宝货繁目。","detail":{"background":"宝货二十余品不可行，民间但以谷帛相市，农商失业，而官中铸造犹不止；每一改币则民一次失其业。","process":"14年罢大小钱，更作货布（长二十五分，直五百）、货泉（重五铢，直一），以二品并行；禁民不得挟五铢、勿敢铸，犯者罪至徙，然私铸不可禁，市价日贵而民益贫。","impact":"自始建国至天凤，货币四变而民益困：币制与财政既不能信于民，则一切政令随之失信，这是新朝经济崩坏的枢纽，也是光武中元以后专行五铢的教训所由。","figures":["王莽"],"place":"长安及郡国","state":"新","sources":["《汉书·食货志》","《汉书·王莽传》","新莽货布货泉实物"],"tags":["货布","货泉","币信之失"]},"related":["cn--9--e01", "cn--12--i01", "cn--40--e01"]},
  {"id":"cn--16--s01","track":"cn","year":16,"yearApprox":false,"dim":"science","weight":3,"title":"路平造铜浑仪刻漏","summary":"以漏刻度浑仪以候天，昼夜各有中。","detail":{"background":"律历之家久以浑仪、候度校刻漏之节；莽欲定声律、度、量、衡以明天命，故钟律、权量与天文之器并治于灵台。","process":"天凤间，命太史待诏典浑仪，考律历于钟律；路平作铜浑仪，令史张衡之属承其业，以漏刻候之，一日夜各有中，以推日月行度与节气之先后。","impact":"律吕、度、量、衡与浑仪、刻漏在汉末被合成一整套可复验的天文计量体系：此为张衡浑象、候风地动仪之直接前提，也是中国仪器史上第一次以标准时长来校验天文观测。","figures":["路平","王莽"],"place":"长安灵台","state":"新","sources":["《汉书·律历志》","《晋书·天文志》"],"tags":["浑仪","刻漏","声律度量衡"]},"related":["cn--b104--s01", "cn--b28--s01"]},
  {"id":"cn--17--p01","track":"cn","year":17,"yearApprox":false,"dim":"politics","weight":4,"title":"绿林起于新莽天凤四年","summary":"荆州岁饥，流民散入绿林中，推王匡王凤。","detail":{"background":"天凤三年荆州大水，饥民入野泽掘凫茨而食；地方吏职以苛法相追、以簿书相课，民穷无所诉，遂相率为群。","process":"17年（天凤四年）新市人王匡、王凤为饥民所推，评其诤讼，藏于绿林山中，数月间至七八千人；又有南郡张霸、羊牧等并起，四方散归之，号新市兵。","impact":"民之乱起于饥与法之并至：新莽对流民无赈而有督，绿林遂由小盗为大军，五年之间下数郡，十七年间与汉室相始终，是亡新的两股力量之首。","figures":["王匡","王凤"],"place":"绿林山（今湖北大洪山一带）","state":"新","sources":["《汉书·王莽传》","《后汉书》","《资治通鉴·汉纪》"],"tags":["绿林","流民","饥民起义"]},"related":["cn--b89--p01", "cn--13--d01", "cn--18--m01"]},
  {"id":"cn--18--m01","track":"cn","year":18,"yearApprox":false,"dim":"military","weight":3,"title":"樊崇起莒作赤眉军","summary":"琅邪饥人樊崇起兵，以朱眉相别为号。","detail":{"background":"关东连年不登，民弃田卖爵而相率为群；琅邪、东海之间饥人尤多，而郡太守不恤，反督以赋役。","process":"18年（天凤五年）莒人樊崇起兵，先据武城、高鱼，转战入泰山，众至万余；以朱涂眉为号，故名赤眉。军中所约：杀人者死、伤人者偿创，无文书、旗帜、号令，口呼为营。","impact":"赤眉起于饥民而无士人参与，故能因其粗朴而得众，也因其无政而终不能守；绿林、赤眉两路之合，使新莽在三年内土崩，而两汉之际的农民军从此成为易姓改代的决定力量。","figures":["樊崇"],"place":"琅邪、泰山（今山东莒县一带）","state":"新","sources":["《汉书·王莽传》","《后汉书·刘盆子传》"],"tags":["赤眉","流民","饥民起义"]},"related":["cn--17--p01", "cn--23--p01", "cn--26--m01"]},
  {"id":"cn--21--m01","track":"cn","year":21,"yearApprox":true,"dim":"military","weight":2,"title":"下江新市兵出荆州","summary":"绿林分军为二，下江兵入南郡、江北。","detail":{"background":"新莽发兵四万余人，分道向荆州击绿林，而军粮、簿书皆仰郡县；郡县承平久，吏士不相习，兵出而贼益多。","process":"21年前后，绿林军以王匡、王凤为纽兵，分其别部入南郡蓝头，号下江兵；时王莽遣太师羲仲景尚等将兵东下，为乱兵所杀；新市兵与舂陵刘伯升起兵会合，共约立宗室。","impact":"下江兵与舂陵宗室军的联合是起义从饥民之乱变为改朝换代的关键一步，从此有了士人、宗室与地方吏职，其组织水平与赤眉全然不同。","figures":["王匡","刘伯升"],"place":"南郡、江夏","state":"新","sources":["《汉书·王莽传》","《后汉书·光武帝纪》"],"tags":["下江兵","舂陵","联军"]},"related":["cn--17--p01", "cn--22--m01"]},
  {"id":"cn--22--m01","track":"cn","year":22,"yearApprox":false,"dim":"military","weight":4,"title":"寻邑百万之围与昆阳之战","summary":"莽使王邑将天下兵百万，围昆阳，汉军三千陷之。","detail":{"background":"王莽以昆阳当南北之要，诏大司空王邑、司徒王寻征天下兵，自郡国选练武人，合六十三万人，号称百万。","process":"23年二月王邑围昆阳，城中惟下江、新市八千人；刘秀以步骑三千为先锋，自城西出冲，斩王寻；会大风大雨、屋瓦皆飞，王莽军大乱溃走，士卒相腾藉，滍水为之不流；莽军辎重、财物、军书不可胜数。","impact":"昆阳以少敌多，是古代中国最著名的战例之一；其破在于王邑不纳严尤舍南救北、专攻小城之计，也在于新室军众来自四方而不可信。此役后新室军主力不复能用。","figures":["刘秀","王邑","王寻","严尤"],"place":"昆阳（今河南叶县）","state":"新","sources":["《后汉书·光武帝纪》","《汉书·王莽传》","《资治通鉴·汉纪》"],"tags":["昆阳之战","以少击众","新莽崩溃"]},"related":["cn--23--p01", "cn--21--m01", "cn--25--p01"]},
  {"id":"cn--23--p01","track":"cn","year":23,"yearApprox":false,"dim":"politics","weight":5,"title":"更始入长安与王莽死","summary":"三辅兵共起，商人杜吴斩莽于渐台之上。","detail":{"background":"更始既立，诸将北渡河，关东诸城皆下；王邑败还，新室已不能调兵，惟以读书、铸威斗自慰。","process":"23年十月申屠建等自武关入，析县人起兵应之；三辅豪桀复共攻长安，商人杜吴杀莽于桂宫，武士斩其头，军人共分肢体，有司烧其宫；汉宫人得莽首送宛，更始传首诣阙，悬于宛市，莽之头后送洛阳，汉之太官烹其肉。","impact":"新莽亡于工商与乱兵之手：商人杜吴斩莽头一事本身即说明新室连最后的都市支持者亦不能维持。更始入关之始，人心归于刘氏，天下之乱却因更始之政而继续。","figures":["王莽","刘玄","申屠建"],"place":"长安","state":"新","sources":["《汉书·王莽传》","《后汉书·刘玄传》","《资治通鉴·汉纪》"],"tags":["更始入关","王莽之死","新室亡"]},"related":["cn--22--m01", "cn--24--p02", "cn--25--p01"]},
  {"id":"cn--24--p02","track":"cn","year":24,"yearApprox":false,"dim":"politics","weight":3,"title":"更始都长安而失纪纲","summary":"拜官千余人，长安为笑，诸将横恣不奉法。","detail":{"background":"更始入长安，以宗室与诸将分任三公、列侯，而号令不出于一门；将军赵萌、李松各竞其势，日争于殿前。","process":"24年更始居长安，封诸将数百人，或一日拜吏二千余员；长安语曰斗家炊事、灶家给使；诸将掠民，三辅吏民失望，而更始自乐宴饮，不复亲政。","impact":"更始一败于无政：士人与地方望风思汉而不得其主，光武得河北、邓禹得关中，皆以更始之失为条件。赤眉、隗嚣随之俱起，天下复入割据之局。","figures":["刘玄","赵萌"],"place":"长安","state":"更始","sources":["《后汉书·刘玄传》","《资治通鉴·汉纪》"],"tags":["更始失政","滥封","割据再乱"]},"related":["cn--23--p01", "cn--25--p01", "cn--26--m01"]},
  {"id":"cn--25--p01","track":"cn","year":25,"yearApprox":false,"dim":"politics","weight":4,"title":"光武即位于河北","summary":"以符命即位于鄗南，改元建武，国号汉。","detail":{"background":"24年刘秀持节河北，抚降、断狱、除王莽苛政；邓禹、冯异、寇恂相次归附，遂与更始分道，北破铜马、青犊之众于河北，号称铜马帝。","process":"25年六月己未，即皇帝位于鄗南之阴，设坛场、燎，祭天地，改元曰建武，国号曰汉；以邓禹为大司徒、吴汉为大司马，定都洛阳，号曰东京。","impact":"东汉自光武起于河北，其规模定于此日；其政治之重心亦由是转于尚书台与南阳、颍川、河北三方士人，而外戚、近习与功臣之制为两汉之异。","figures":["刘秀","邓禹","吴汉"],"place":"鄗（今河北柏乡）","state":"东汉","sources":["《后汉书·光武帝纪》","《东观汉记》","《资治通鉴·汉纪》"],"tags":["光武即位","建武","东汉开端"]},"related":["cn--24--p02", "cn--28--c01", "cn--31--i01"]},
  {"id":"cn--25--p02","track":"cn","year":25,"yearApprox":false,"dim":"politics","weight":3,"title":"光武都洛阳","summary":"以河北之地与关东之漕，定都于洛。","detail":{"background":"长安残破，赤眉之众未平；洛邑当天下之中而有漕运，河北有根本，且关中豪强与更始之党犹在，都之不便。","process":"25年十月车驾东巡，遂留洛阳，舍于南宫，定以为都；以河北、颍川、南阳三域为根本，罢长安宫庙之修，惟立宗庙、社稷于洛城之中。其后遣吴汉、冯异拒赤眉于崤底，27年正月降其众八万余口，樊崇面缚诣阙。","impact":"东汉都洛，使国家的重心自西向东转移，河北、颍川、南阳三个士人集团随之得势；关中自此不复为都，中国古都史上一次长久的转移实成于此。","figures":["刘秀","吴汉","冯异"],"place":"洛阳","state":"东汉","sources":["《后汉书·光武帝纪》","《东观汉记》"],"tags":["都洛阳","地理重心","崤底之降"]},"related":["cn--25--p01", "cn--26--m01"]},
  {"id":"cn--26--m01","track":"cn","year":26,"yearApprox":false,"dim":"military","weight":3,"title":"赤眉入长安与宗庙之焚","summary":"樊崇立刘盆子为帝，入长安，烧宫庙。","detail":{"background":"赤眉无文书、旗帜，转掠二十余万人而西，与更始诸将相拒于弘农；食尽而遂入关，其势不可复止。","process":"26年正月赤眉至长安，立刘盆子为帝，年十五；攻入城，更始肉袒降，寻为张卽所杀；赤眉纵兵大掠，发掘茂陵、长安诸陵，烧宫室、宗庙、府库，二岁之间，长安市肆中与人相食。","impact":"赤眉之祸甚于兵：关中自是虚耗，光武所以能制天下，正在以郡国屯田、赈给流民而得人心，反证流民之乱根在失所而非乐乱。","figures":["樊崇","刘盆子"],"place":"长安","state":"更始","sources":["《后汉书·刘盆子传》","《汉书·王莽传》","《资治通鉴·汉纪》"],"tags":["赤眉入关","发掘陵寝","关中残破"]},"related":["cn--18--m01", "cn--24--p02", "cn--25--p01"]},
  {"id":"cn--28--c01","track":"cn","year":28,"yearApprox":false,"dim":"culture","weight":4,"title":"退功臣而进文吏","summary":"邓禹、吴汉等以列侯奉朝请，不临职事。","detail":{"background":"汉室中兴，功臣二十八人并据高爵，多至食邑数县；光武以天下初定，不欲使武人典兵而干吏事。","process":"建武中，以功臣为列侯、奉朝请而不得为吏，大司马吴汉以下多以骑都尉、列侯奉请；同时征隐逸、用文吏：卓茂、伏湛、侯霸以经行进，以太常、大司徒居相位。","impact":"以厚禄与高爵换去功臣的权力，是光武留给后世最出名的政治设计；与宋初杯酒释兵权相类而温和得多，代价是士风与吏事之分，文吏、武功两条轨道从此判然。","figures":["刘秀","邓禹","吴汉","卓茂"],"place":"洛阳","state":"东汉","sources":["《后汉书·光武帝纪》","《后汉书·邓寇列传》","《后汉书·卓茂传》"],"tags":["退功臣","文吏政治","奉朝请"]},"related":["cn--25--p01", "cn--30--i01", "cn--b124--i01"]},
  {"id":"cn--30--i01","track":"cn","year":30,"yearApprox":false,"dim":"institution","weight":4,"title":"并省四百余县","summary":"并乐浪九真之远，省县四百，吏员十置其一。","detail":{"background":"王莽以来户口耗减，郡县多置而吏员繁；光武以军兴之后财用不足，欲以简省官职宽民力而清簿书。","process":"建武六年（30）前后诏，省吏职，十分置一，并省四百余县，凡乐浪、九真之远与内郡小县皆见省；边郡都尉、属国仍置，且以见官为定制。","impact":"这是中国史上一次大规模的精兵简政：它使东汉的吏员、赋役规模较西汉缩小，代价是地方行政能力下降，边郡与县乡之政渐委于豪右，为东汉中叶以后的地方割据留了伏笔。","figures":["刘秀"],"place":"洛阳及郡国","state":"东汉","sources":["《后汉书·光武帝纪》","《续汉书·郡国志》"],"tags":["并省郡县","精简吏员","东汉初政"]},"related":["cn--28--c01", "cn--40--e01", "cn--39--p01"]},
  {"id":"cn--31--i01","track":"cn","year":31,"yearApprox":true,"dim":"institution","weight":3,"title":"六诏释放奴婢与省减刑罚","summary":"自建武二年至十五年，前后六诏吏民被略为奴婢者免为庶人。","detail":{"background":"王莽以来，兵连、饥疫相仍，吏民多被掠卖为奴婢；汉世田宅、奴婢本不禁卖，而乱离之民自鬻者不可胜数。","process":"光武自即位至建武十五年前后，累诏：吏民被青、徐寇贼所略为奴婢者，皆勿听，得自出；遭饥乱而卖为奴婢者，一切免为庶人；又除王莽时苛法，省大辟之条，前后十省，死者岁以千数，谓有减于前。","impact":"释放奴婢之诏是中国法律史上第一次以全国诏令承认被略者的自由身份，它把身部曲、客与奴婢的界线重画了一次；而十省刑法则定下东汉宽简之名。两者皆以皇权直接干预民间身份，为后来曹魏、西晋的奴婢与部曲立法开了先例。","figures":["刘秀"],"place":"洛阳及郡国","state":"东汉","sources":["《后汉书·光武帝纪》","《资治通鉴·汉纪》"],"tags":["释放奴婢","省刑","身份制度"]},"related":["cn--30--i01", "cn--39--p01", "cn--b7--i01"]},
  {"id":"cn--39--p01","track":"cn","year":39,"yearApprox":false,"dim":"politics","weight":3,"title":"度田之诏与青州之乱","summary":"诏郡国度田比户口，十郡守坐贬死。","detail":{"background":"天下初定，南阳帝里与诸豪右之家田宅过制，郡国户口不实，赋役由是不平；光武欲以核实为治。","process":"建武十五年（39）诏州郡度民田、比核户口，务均赋役；郡守以下十数人坐度田不实下狱死，青、徐、幽、冀之豪叛，杀吏以应；光武以张湛等喻之，诛首恶而赦其余，事遂止。","impact":"度田失败是中国帝国史上的一次决定性事件：皇权无法真正清点豪族的土地，东汉中叶以后田庄与部曲之盛、豪右之不治，其根在此；此后朝廷只能依靠口赋与计簿，而不再能按实田征赋。","figures":["刘秀","张湛"],"place":"洛阳及青徐幽冀","state":"东汉","sources":["《后汉书·光武帝纪》","《后汉书·刘良传》","《资治通鉴·汉纪》"],"tags":["度田","豪右","赋役不均"]},"related":["cn--30--i01", "cn--b7--i01", "cn--31--i01"]},
  {"id":"cn--40--e01","track":"cn","year":40,"yearApprox":false,"dim":"economy","weight":3,"title":"复行五铢钱","summary":"马援请复五铢，光武许之，天下以为便。","detail":{"background":"建武初年军兴，布帛、谷食皆当钱用；王莽之货布、货泉犹在民间，轻重无法，故货不得通、谷帛益贵。","process":"建武十六年（40）伏波将军马援请复铸五铢钱，从之，于是王莽之货布、货泉皆废；民间复以钱为市，农商得通，谷价渐平。","impact":"五铢之复定东汉一朝的币本，此后八十多年不改，至董卓铸小钱而坏；它同时说明王莽以名物乱币制的失败，光武以恢复旧物为务，正是新汉两朝政治作风之别。","figures":["马援","刘秀"],"place":"洛阳及郡国","state":"东汉","sources":["《后汉书·马援传》","《后汉书·光武帝纪》","东汉五铢钱范"],"tags":["五铢钱","马援","币制回复"]},"related":["cn--9--e01", "cn--14--e01", "cn--b113--e01"]},
  {"id":"cn--43--x01","track":"cn","year":43,"yearApprox":false,"dim":"explore","weight":3,"title":"马援平交趾置二征县","summary":"楼船将军马援浮海南下，平交趾、九真。","detail":{"background":"交趾女子征侧、征贰反，攻没郡县六十五城，自立为王；九真、日南与合浦的蛮里皆应之，海上之道不通。","process":"42—43年马援为伏波将军，率楼船二千余艘，将士二万，浮海至交趾，与贼战于浪泊，斩征侧等，徙其渠帅三百余口于零陵；于其地置二征县，立铜柱为汉之极界。","impact":"东汉第一次在岭南以海路运兵成功，交趾自此长属中国郡县，而铜柱之说成为后世南海边疆的象征；马援门人之众与军中的疫疾，也见出南方军役的艰难。","figures":["马援","征侧"],"place":"交趾、九真（今越南北部红河三角洲）","state":"东汉","sources":["《后汉书·马援传》","《后汉书·南蛮传》","《水经注·温水》"],"tags":["马援","交趾","铜柱"]},"related":["cn--b111--i01", "cn--40--e01", "world--40--p01"]},
  {"id":"cn--48--p01","track":"cn","year":48,"yearApprox":false,"dim":"politics","weight":4,"title":"南匈奴日逐王比称藩内附","summary":"日逐王比自立为呼韩邪单于，款五原塞，愿保北边。","detail":{"background":"王莽末，匈奴复胁乌桓、取西域，北边为寇；光武以天下新定，止于赂遗结好，不能复制单于之庭，而匈奴内部分裂之机已熟。","process":"48年匈奴日逐王比自立为呼韩邪单于，遣使奉记，愿为藩蔽、求入朝；其众数万落，南边五原、云中、定襄塞下而居。49年汉遣中郎将段郴、副校尉王郁持节即单于庭，赐玺绶、衣冠，置使匈奴中郎将将兵卫护之，南庭自此世为汉保塞。","impact":"匈奴自此南北分为二庭：南部民户渐入并、雍诸郡，与汉杂居，开了此后内迁胡口的先例；北部退保漠北，终为东汉边功与军费之所系。北匈奴之西迁与草原权力的再编，亦以48年之分为起点。","figures":["比","刘秀","段郴"],"place":"五原塞（今内蒙古包头一带）与洛阳","state":"东汉","sources":["《后汉书·南匈奴传》","《后汉书·光武帝纪》","《资治通鉴·汉纪》"],"tags":["南匈奴内附","使匈奴中郎将","南北分庭"]},"related":["cn--b33--p02", "cn--b60--i01", "cn--11--x01"]},
  {"id":"cn--57--p01","track":"cn","year":57,"yearApprox":false,"dim":"politics","weight":3,"title":"明帝即位与吏职修整","summary":"帝善刑名，数文法，而上下相奉以谨。","detail":{"background":"中元二年光武崩，太子庄立，是为明帝；帝少而好学，从桓荣受欧阳《尚书》，善刑名之学，能通《春秋》。","process":"57年明帝即位；永平元年改元，令郎官、尚书各以条课其职，躬耕籍田，以经义自试；数遣使巡行郡国，问鳏寡、不能自存者，赐以谷帛，严斥郡县之欺簿者。","impact":"明帝之政以综核名实为要，吏职修而刑罚中，与章帝之宽厚相补，史并称明章之治；同时帝好佛法、亲讲经于辟雍，为东汉的宗教与学术开了新局。","figures":["刘庄"],"place":"洛阳","state":"东汉","sources":["《后汉书·明帝纪》","《后汉书·循吏传》"],"tags":["明帝即位","综核名实","籍田之礼"]},"related":["cn--28--c01", "cn--59--c01", "cn--57--f01"]},
  {"id":"cn--57--f01","track":"cn","year":57,"yearApprox":false,"dim":"figure","weight":3,"title":"王充作论衡于会稽","summary":"疾俗儒之守文，作《论衡》八十五篇以订虚妄。","detail":{"background":"王充（27—约97）字仲任，会稽上虞人，师事班彪，家贫无书，常游洛阳市肆，阅所卖书，一见辄能记诵。","process":"明帝永平之初，充仕郡功曹，以谏争去职，退而居会稽、钱塘之间，作《论衡》八十五篇，讥世俗之虚妄，言天地故、人无意，又疾俗儒信师而是古。","impact":"《论衡》是汉代最彻底的自然主义与怀疑论之作，以物类相应之理说灾异，以效验征实之法断是非，冲破了谶纬与天人感应的一统；王充之名至魏晋始著，而其对后世反迷信之论影响深远。","figures":["王充","班彪"],"place":"会稽上虞（今浙江上虞）","state":"东汉","sources":["《论衡·自纪》","《后汉书·王充传》"],"tags":["论衡","疾虚妄","效验之论"]},"related":["cn--b98--c01", "cn--59--c01"]},
  {"id":"cn--59--c01","track":"cn","year":59,"yearApprox":false,"dim":"culture","weight":3,"title":"明帝亲临辟雍讲论","summary":"自为通德论，命桓荣讲《尚书》于辟雍。","detail":{"background":"明帝以经学自修，尊桓荣为帝师；荣受欧阳《尚书》，以授太子，累迁太常、关内侯，赐以辎车乘马。","process":"59年（永平二年）三雍初成，帝先宗祀光武于明堂，乃临辟雍，令桓荣执经讲《尚书》，自为《通德论》以难之；又行养老、乡射之礼，以弟子之礼见荣。诏天下通经者皆得举于太常，岁以课试为程。","impact":"皇帝在辟雍以师礼事经师，为太学讲论之礼定了范式：东汉以经学起家之家与太常、博士的关系自此极深，门生、故吏遍天下，弘农杨氏、汝南袁氏四世三公的局面由此而成。","figures":["刘庄","桓荣"],"place":"洛阳辟雍","state":"东汉","sources":["《后汉书·桓荣传》","《后汉书·明帝纪》"],"tags":["皇帝讲学","经学家族","辟雍之礼"]},"related":["cn--b124--i01", "cn--2--i01", "cn--57--f01"]},
];
